## План рефакторингу з використанням шаблону Unit of Work

Шаблон Unit of Work дозволить нам:
1. Керувати транзакціями більш ефективно
2. Відкласти обробку зв'язків між сутностями до моменту збереження
3. Зменшити кількість запитів до бази даних через кешування сутностей

Ось що я пропоную зробити:

### 1. Створення класу UnitOfWork

Спочатку створимо клас UnitOfWork, який буде відповідати за:
- Керування транзакціями
- Кешування сутностей
- Відстеження змін
- Збереження всіх змін в одній транзакції

```java
public class UnitOfWork implements AutoCloseable {
 private final Connection connection;
 private final Map<Class<?>, Map<Object, Object>> entityCache = new HashMap<>();
 private final Set<Object> newEntities = new HashSet<>();
 private final Set<Object> dirtyEntities = new HashSet<>();
 private final Set<Object> removedEntities = new HashSet<>();
 private final Map<Object, Set<Object>> relationships = new HashMap<>();

 public UnitOfWork(Connection connection) {
 this.connection = connection;
 try {
 this.connection.setAutoCommit(false);
 } catch (SQLException e) {
 throw new RuntimeException("Не вдалося ініціалізувати UnitOfWork", e);
 }
 }

 public <T> void registerNew(T entity) {
 newEntities.add(entity);
 cacheEntity(entity);
 }

 public <T> void registerDirty(T entity) {
 dirtyEntities.add(entity);
 cacheEntity(entity);
 }

 public <T> void registerRemoved(T entity) {
 removedEntities.add(entity);
 }

 public <T, R> void registerRelationship(T entity, R relatedEntity) {
 relationships.computeIfAbsent(entity, k -> new HashSet<>()).add(relatedEntity);
 }

 @SuppressWarnings("unchecked")
 public <T, ID> Optional<T> findInCache(Class<T> entityClass, ID id) {
 Map<Object, Object> classCache = entityCache.get(entityClass);
 if (classCache != null) {
 return Optional.ofNullable((T) classCache.get(id));
 }
 return Optional.empty();
 }

 private <T> void cacheEntity(T entity) {
 try {
 Class<?> entityClass = entity.getClass();
 Field idField = entityClass.getDeclaredField("id");
 idField.setAccessible(true);
 Object id = idField.get(entity);

 if (id != null) {
 entityCache.computeIfAbsent(entityClass, k -> new HashMap<>()).put(id, entity);
 }
 } catch (Exception e) {
 // Ігноруємо помилки при кешуванні
 }
 }

 public void commit() {
 try {
 // Зберігаємо нові сутності
 for (Object entity : newEntities) {
 saveEntity(entity);
 }

 // Оновлюємо змінені сутності
 for (Object entity : dirtyEntities) {
 updateEntity(entity);
 }

 // Видаляємо сутності
 for (Object entity : removedEntities) {
 deleteEntity(entity);
 }

 // Зберігаємо зв'язки
 saveRelationships();

 connection.commit();

 // Очищаємо колекції
 newEntities.clear();
 dirtyEntities.clear();
 removedEntities.clear();
 relationships.clear();

 } catch (Exception e) {
 try {
 connection.rollback();
 } catch (SQLException ex) {
 throw new RuntimeException("Не вдалося виконати відкат транзакції", ex);
 }
 throw new RuntimeException("Не вдалося зберегти зміни", e);
 }
 }

 private void saveEntity(Object entity) {
 // Реалізація збереження сутності
 }

 private void updateEntity(Object entity) {
 // Реалізація оновлення сутності
 }

 private void deleteEntity(Object entity) {
 // Реалізація видалення сутності
 }

 private void saveRelationships() {
 // Реалізація збереження зв'язків
 }

 @Override
 public void close() {
 try {
 if (!connection.getAutoCommit()) {
 connection.rollback();
 connection.setAutoCommit(true);
 }
 } catch (SQLException e) {
 throw new RuntimeException("Не вдалося закрити UnitOfWork", e);
 }
 }
}
```

### 2. Спрощення GenericRepository

Тепер спростимо GenericRepository, перенісши логіку роботи зі зв'язками в UnitOfWork:

```java
public class GenericRepository<T, ID> {
 private final UnitOfWork unitOfWork;
 private final Class<T> entityClass;
 private final String tableName;

 public GenericRepository(UnitOfWork unitOfWork, Class<T> entityClass, String tableName) {
 this.unitOfWork = unitOfWork;
 this.entityClass = entityClass;
 this.tableName = tableName;
 }

 public Optional<T> findById(ID id) throws SQLException {
 // Спочатку шукаємо в кеші
 Optional<T> cachedEntity = unitOfWork.findInCache(entityClass, id);
 if (cachedEntity.isPresent()) {
 return cachedEntity;
 }

 // Якщо не знайдено в кеші, шукаємо в базі даних
 String sql = String.format("SELECT * FROM %s WHERE id = ?", tableName);
 try (var statement = unitOfWork.getConnection().prepareStatement(sql)) {
 statement.setObject(1, id);
 try (var resultSet = statement.executeQuery()) {
 if (resultSet.next()) {
 T entity = mapResultSetToEntity(resultSet);
 unitOfWork.registerClean(entity);
 return Optional.of(entity);
 }
 return Optional.empty();
 }
 }
 }

 public List<T> findAll() throws SQLException {
 String sql = String.format("SELECT * FROM %s", tableName);
 try (var statement = unitOfWork.getConnection().prepareStatement(sql);
 var resultSet = statement.executeQuery()) {
 List<T> entities = new ArrayList<>();
 while (resultSet.next()) {
 T entity = mapResultSetToEntity(resultSet);
 unitOfWork.registerClean(entity);
 entities.add(entity);
 }
 return entities;
 }
 }

 public T save(T entity) {
 unitOfWork.registerNew(entity);
 return entity;
 }

 public T update(T entity) {
 unitOfWork.registerDirty(entity);
 return entity;
 }

 public void delete(T entity) {
 unitOfWork.registerRemoved(entity);
 }

 private T mapResultSetToEntity(ResultSet resultSet) throws SQLException {
 // Реалізація відображення ResultSet на сутність
 }
}
```

### 3. Створення спеціалізованих репозиторіїв

Для роботи зі зв'язками створимо спеціалізовані репозиторії:

```java
public class AudiobookRepository extends GenericRepository<Audiobook, UUID> {
 public AudiobookRepository(UnitOfWork unitOfWork) {
 super(unitOfWork, Audiobook.class, "audiobooks");
 }

 public void addToCollection(Audiobook audiobook, Collection collection) {
 unitOfWork.registerRelationship(audiobook, collection);
 }

 public void removeFromCollection(Audiobook audiobook, Collection collection) {
 unitOfWork.removeRelationship(audiobook, collection);
 }

 public List<Collection> getCollections(Audiobook audiobook) throws SQLException {
 String sql = """
 SELECT c.* FROM collections c
 INNER JOIN audiobook_collection ac ON c.id = ac.collection_id
 WHERE ac.audiobook_id = ?
 """;
 try (var statement = unitOfWork.getConnection().prepareStatement(sql)) {
 statement.setObject(1, audiobook.getId());
 try (var resultSet = statement.executeQuery()) {
 List<Collection> collections = new ArrayList<>();
 while (resultSet.next()) {
 Collection collection = mapResultSetToEntity(resultSet, Collection.class);
 collections.add(collection);
 }
 return collections;
 }
 }
 }
}

public class CollectionRepository extends GenericRepository<Collection, UUID> {
 public CollectionRepository(UnitOfWork unitOfWork) {
 super(unitOfWork, Collection.class, "collections");
 }

 public void addAudiobook(Collection collection, Audiobook audiobook) {
 unitOfWork.registerRelationship(collection, audiobook);
 }

 public void removeAudiobook(Collection collection, Audiobook audiobook) {
 unitOfWork.removeRelationship(collection, audiobook);
 }

 public List<Audiobook> getAudiobooks(Collection collection) throws SQLException {
 String sql = """
 SELECT a.* FROM audiobooks a
 INNER JOIN audiobook_collection ac ON a.id = ac.audiobook_id
 WHERE ac.collection_id = ?
 """;
 try (var statement = unitOfWork.getConnection().prepareStatement(sql)) {
 statement.setObject(1, collection.getId());
 try (var resultSet = statement.executeQuery()) {
 List<Audiobook> audiobooks = new ArrayList<>();
 while (resultSet.next()) {
 Audiobook audiobook = mapResultSetToEntity(resultSet, Audiobook.class);
 audiobooks.add(audiobook);
 }
 return audiobooks;
 }
 }
 }
}
```

### 4. Створення EntityMapper

Для спрощення роботи з рефлексією створимо окремий клас EntityMapper:

```java
public class EntityMapper {
 public static <T> T mapResultSetToEntity(ResultSet resultSet, Class<T> entityClass) throws SQLException {
 try {
 T entity = entityClass.getDeclaredConstructor().newInstance();
 Field[] fields = entityClass.getDeclaredFields();

 for (Field field : fields) {
 if (isSimpleField(field)) {
 field.setAccessible(true);
 String columnName = camelCaseToSnakeCase(field.getName());
 Object value = resultSet.getObject(columnName);
 if (value != null) {
 field.set(entity, convertValue(value, field.getType()));
 }
 }
 }

 return entity;
 } catch (Exception e) {
 throw new SQLException("Не вдалося зіставити ResultSet із сутністю", e);
 }
 }

 private static boolean isSimpleField(Field field) {
 String fieldName = field.getName();
 Class<?> fieldType = field.getType();

 // Ігноруємо колекції та зв'язки
 return !fieldName.equals("collections") && 
 !fieldName.equals("audiobooks") && 
 !Collection.class.isAssignableFrom(fieldType) &&
 !fieldType.isAssignableFrom(List.class);
 }

 private static Object convertValue(Object value, Class<?> targetType) {
 if (value == null && !targetType.isPrimitive()) {
 return null;
 }

 if (targetType == String.class) {
 return value.toString();
 } else if (targetType == UUID.class && value instanceof String) {
 return UUID.fromString((String) value);
 } else if ((targetType == Integer.class || targetType == int.class) && value instanceof Number) {
 return ((Number) value).intValue();
 } else if (targetType == LocalDateTime.class && value instanceof Timestamp) {
 return ((Timestamp) value).toLocalDateTime();
 } else if (targetType.isEnum() && value instanceof String) {
 return Enum.valueOf((Class<Enum>) targetType, (String) value);
 }

 return value;
 }

 public static String camelCaseToSnakeCase(String input) {
 if (input == null || input.isEmpty()) {
 return input;
 }
 return input.replaceAll("([a-z])([A-Z]+)", "$1_$2").toLowerCase();
 }
}
```

