 private T mapResultSetToEntity(ResultSet resultSet) throws SQLException {
 return mapResultSetToEntity(resultSet, entityClass);
 }

 private <E> E mapResultSetToEntity(ResultSet resultSet, Class<E> clazz) throws SQLException {
 try {
 E entity = clazz.getDeclaredConstructor().newInstance();
 Field[] fields = clazz.getDeclaredFields();

 for(Field field : fields) {
 // TODO: refactor
 if(!field.getName().equals("id") && !field.getName().equals("collections") && !field.getName().equals("audiobooks")) {
 field.setAccessible(true);
 Object value = resultSet.getObject(camelCaseToSnakeCase(field.getName()));
 if(value != null) {
 field.set(entity, convertValue(value, field.getType()));
 }
 }
 }

 return entity;
 } catch (Exception e) {
 throw new SQLException("Не вдалося зіставити ResultSet із сутністю", e);
 }
 }

 private Object convertValue(Object value, Class<?> targetType) {
 if(value == null && !targetType.isPrimitive()) {
 return null;
 }

 switch (targetType.getName()) {
 case "java.lang.String":
 return value.toString();
 case "java.util.UUID":
 if(value instanceof String) {
 return UUID.fromString((String) value);
 }
 return value;
 case "java.lang.Integer":
 case "int":
 if(value instanceof Number) {
 return ((Number) value).intValue();
 }
 return value;
 case "java.time.LocalDateTime":
 if(value instanceof Timestamp) {
 return ((Timestamp) value).toLocalDateTime();
 }
 return null;
 case "FileFormat":
 if(value instanceof String) {
 return FileFormat.valueOf((String) value);
 }
 return value;
 default:
 return value;
 }
 }

 public static String camelCaseToSnakeCase(String input) {
 if (input == null || input.isEmpty()) {
 return input;
 }
 return input.replaceAll("([a-z])([A-Z]+)", "$1_$2").toLowerCase();
 }

 public static String snakeCaseToCamelCase(String input) {
 if (input == null || input.isEmpty()) {
 return input;
 }
 StringBuilder result = new StringBuilder();
 boolean toUpperCase = false;
 for (char ch : input.toCharArray()) {
 if (ch == '_') {
 toUpperCase = true;
 } else {
 result.append(toUpperCase ? Character.toUpperCase(ch) : ch);
 toUpperCase = false;
 }
 }
 return result.toString();
 }
