iobook_id = ? AND collection_id = ?\";\n try (var connection = unitOfWork.getConnection();\n var statement = connection.prepareStatement(sql)) {\n statement.setObject(1, audiobookId);\n statement.setObject(2, collectionId);\n statement.executeUpdate();\n }\n }\n \n /**\n * \u041e\u0442\u0440\u0438\u043c\u0443\u0454 \u0441\u043f\u0438\u0441\u043e\u043a \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433 \u0434\u043b\u044f \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457.\n * \n * @param collectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\n * @throws SQLException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u043b\u0430 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n */\n public List<Audiobook> getAudiobooksForCollection(UUID collectionId) throws SQLException {\n String sql = \"\"\"\n SELECT a.* FROM audiobooks a\n INNER JOIN audiobook_collection ac ON a.id = ac.audiobook_id\n WHERE ac.collection_id = ?\n \"\"\";\n try (var connection = unitOfWork.getConnection();\n var statement = connection.prepareStatement(sql)) {\n statement.setObject(1, collectionId);\n try (var resultSet = statement.executeQuery()) {\n return unitOfWork.getAudiobooks().mapResultSetToList(resultSet);\n }\n }\n }\n \n /**\n * \u041e\u0442\u0440\u0438\u043c\u0443\u0454 \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439 \u0434\u043b\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438.\n * \n * @param audiobookId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\