 251	 private Object convertValue(Object value, Class<?> targetType) {
 252	 if(value == null && !targetType.isPrimitive()) {
 253	 return null;
 254	 }
 255	
 256	 switch (targetType.getName()) {
 257	 case "java.lang.String":
 258	 return value.toString();
 259	 case "java.util.UUID":
 260	 if(value instanceof String) {
 261	 return UUID.fromString((String) value);
 262	 }
 263	 return value;
 264	 case "java.lang.Integer":
 265	 case "int":
 266	 if(value instanceof Number) {
 267	 return ((Number) value).intValue();
 268	 }
 269	 return value;
 270	 case "java.time.LocalDateTime":
 271	 if(value instanceof Timestamp) {
 272	 return ((Timestamp) value).toLocalDateTime();
 273	 }
 274	 return null;
 275	 case "FileFormat":
 276	 if(value instanceof String) {
 277	 return FileFormat.valueOf((String) value);
 278	 }
 279	 return value;
 280	 default:
 281	 return value;
 282	 }
 283	 }
