 285	 public static String camelCaseToSnakeCase(String input) {
 286	 if (input == null || input.isEmpty()) {
 287	 return input;
 288	 }
 289	 return input.replaceAll("([a-z])([A-Z]+)", "$1_$2").toLowerCase();
 290	 }
 291	
 292	 public static String snakeCaseToCamelCase(String input) {
 293	 if (input == null || input.isEmpty()) {
 294	 return input;
 295	 }
 296	 StringBuilder result = new StringBuilder();
 297	 boolean toUpperCase = false;
 298	 for (char ch : input.toCharArray()) {
 299	 if (ch == '_') {
 300	 toUpperCase = true;
 301	 } else {
 302	 result.append(toUpperCase ? Character.toUpperCase(ch) : ch);
 303	 toUpperCase = false;
 304	 }
 305	 }
 306	 return result.toString();
 307	 }
 308	}
