\u043d\u044f \u043d\u043e\u0432\u043e\u0457 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n Collection collection = new Collection();\n collection.setId(UUID.randomUUID());\n collection.setUserId(user.getId());\n collection.setName(\"Favorite Audiobooks\");\n collection.setCreatedAt(LocalDateTime.now());\n \n // \u0417\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n unitOfWork.getCollections().save(collection);\n \n // \u0421\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0430\u0432\u0442\u043e\u0440\u0430\n Author author = new Author();\n author.setId(UUID.randomUUID());\n author.setFirstName(\"Stephen\");\n author.setLastName(\"King\");\n author.setBio(\"Famous horror writer\");\n \n // \u0417\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0430\u0432\u0442\u043e\u0440\u0430\n unitOfWork.getAuthors().save(author);\n \n // \u0421\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043d\u043e\u0432\u043e\u0457 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n Audiobook audiobook = new Audiobook();\n audiobook.setId(UUID.randomUUID());\n audiobook.setAuthorId(author.getId());\n audiobook.setTitle(\"The Shining\");\n audiobook.setDuration(720);\n audiobook.setReleaseYear(2020);\n audiobook.setDescription(\"A horror novel about a family in an isolated hotel\");\n \n // \u0417\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n unitOfWork.getAudiobooks().save(audiobook);\n \n // \u0414\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0434\u043e \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n RelationshipService relationshipService = new RelationshipService(unitOfWork);\n relationshipService.addAudiobookToCollection(audiobook.getId(), collection.getId());\n \n // \u041e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0432\u0441\u0456\u0445 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433 \u0443 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n List<Audiobook> audiobooksInCollection = relationshipService.getAudiobooksForCollection(collection.getId());\n System.out.println(\"Audiobooks in collection: \" + audiobooksInCollection.size());\n \n // \u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0442\u0440\u0430\u043d\u0437\u0430\u043a\u0446\u0456\u0457\n unitOfWork.commitTransaction();\n \n } catch (Exception e) {\n // \u0412\u0456\u0434\u043a\u0430\u0442 \u0442\u0440\u0430\u043d\u0437\u0430\u043a\u0446\u0456\u0457 \u0443 \u0440\u0430\u0437\u0456 \u043f\u043e\u043c\u0438\u043b\u043a\u0438\n unitOfWork.rollbackTransaction();\n e.printStackTrace();\n }\n \n } catch (Exception e) {\n e.printStackTrace();\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер створимо приклад використання UnitOfWork:
