import java.sql.Connection;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Реалізація патерну Unit of Work для управління транзакціями та змінами сутностей.
 * Відстежує нові, оновлені та видалені сутності, синхронізуючи їх із базою даних у межах однієї транзакції.
 * Дозволяє налаштувати назви таблиць для репозиторіїв, подібно до Entity Framework Core.
 */
public class UnitOfWork implements AutoCloseable {
 private final Connection connection;
 private final Map<Class<?>, GenericRepository<?, ?>> repositories;
 private final Map<Class<?>, String> tableNames;
 private final List<Object> newEntities;
 private final List<Object> updatedEntities;
 private final List<Object> deletedEntities;

 /**
 * Конструктор Unit of Work.
 *
 * @param connection З'єднання з базою даних
 */
 public UnitOfWork(Connection connection) {
 this.connection = connection;
 this.repositories = new HashMap<>();
 this.tableNames = new HashMap<>();
 this.newEntities = new ArrayList<>();
 this.updatedEntities = new ArrayList<>();
 this.deletedEntities = new ArrayList<>();
 }

 /**
 * Реєстрація назви таблиці для певного типу сутності.
 *
 * @param entityClass Клас сутності
 * @param tableName Назва таблиці в базі даних
 */
 public void registerTableName(Class<?> entityClass, String tableName) {
 tableNames.put(entityClass, tableName);
 }

 /**
 * Отримання репозиторію для певного типу сутності.
 *
 * @param entityClass Клас сутності
 * @param <T> Тип сутності
 * @param <ID> Тип ідентифікатора
 * @return Репозиторій для роботи з сутністю
 */
 public <T, ID> GenericRepository<T, ID> getRepository(Class<T> entityClass) {
 return (GenericRepository<T, ID>) repositories.computeIfAbsent(entityClass, k -> {
 String tableName = tableNames.getOrDefault(entityClass, entityClass.getSimpleName().toLowerCase());
 return new GenericRepository<>(connection, entityClass, tableName);
 });
 }

 /**
 * Реєстрація нової сутності для збереження.
 *
 * @param entity Сутність для збереження
 */
 public void registerNew(Object entity) {
 newEntities.add(entity);
 }

 /**
 * Реєстрація сутності для оновлення.
 *
 * @param entity Сутність для оновлення
 */
 public void registerUpdated(Object entity) {
 updatedEntities.add(entity);
 }

 /**
 * Реєстрація сутності для видалення.
 *
 * @param entity Сутність для видалення
 */
 public void registerDeleted(Object entity) {
 deletedEntities.add(entity);
 }

 /**
 * Виконання всіх зареєстрованих змін у базі даних у межах однієї транзакції.
 *
 * @throws SQLException У разі помилки доступу до бази даних
 * @throws IllegalAccessException У разі проблем із доступом до полів сутності
 */
 public void commit() throws SQLException, IllegalAccessException {
 try {
 connection.setAutoCommit(false);

 for (Object entity : newEntities) {
 Class<?> entityClass = entity.getClass();
 GenericRepository<Object, Object> repo = (GenericRepository<Object, Object>) getRepository(entityClass);
 repo.save(entity);
 }

 for (Object entity : updatedEntities) {
 Class<?> entityClass = entity.getClass();
 GenericRepository<Object, Object> repo = (GenericRepository<Object, Object>) getRepository(entityClass);
 Object id = entityClass.getDeclaredField("id").get(entity);
 repo.update(id, entity);
 }

 for (Object entity : deletedEntities) {
 Class<?> entityClass = entity.getClass();
 GenericRepository<Object, Object> repo = (GenericRepository<Object, Object>) getRepository(entityClass);
 Object id = entityClass.getDeclaredField("id").get(entity);
 repo.delete(id);
 }

 connection.commit();
 clear();
 } catch (Exception e) {
 connection.rollback();
 throw new SQLException("Не вдалося виконати транзакцію", e);
 } finally {
 connection.setAutoCommit(true);
 }
 }

 /**
 * Очищення списків зареєстрованих сутностей.
 */
 private void clear() {
 newEntities.clear();
 updatedEntities.clear();
 deletedEntities.clear();
 }

 /**
 * Закриття з'єднання з базою даних.
 *
 * @throws SQLException У разі помилки при закритті з'єднання
 */
 @Override
 public void close() throws SQLException {
 if (!connection.isClosed()) {
 connection.close();
 }
 }
}

Також, мені потрібно ConnectionPool клас.

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Пул з'єднань для управління JDBC-з'єднаннями з базою даних.
 * Забезпечує потокобезпечне отримання та повернення з'єднань із підтримкою обмеження максимальної кількості з'єднань.
 */
public class ConnectionPool {
 private static volatile ConnectionPool instance;
 private final BlockingQueue<Connection> availableConnections;
 private final BlockingQueue<Connection> usedConnections;
 private final String url;
 private final String user;
 private final String password;
 private final int maxConnections;
 private final AtomicBoolean isInitialized = new AtomicBoolean(false);

 /**
 * Приватний конструктор для ініціалізації пулу з'єднань.
 *
 * @param url URL бази даних
 * @param user Ім'я користувача
 * @param password Пароль
 * @param maxConnections Максимальна кількість з'єднань
 */
 private ConnectionPool(String url, String user, String password, int maxConnections) {
 this.url = url;
 this.user = user;
 this.password = password;
 this.maxConnections = maxConnections;
 this.availableConnections = new ArrayBlockingQueue<>(maxConnections);
 this.usedConnections = new ArrayBlockingQueue<>(maxConnections);
 initializePool();
 }

 /**
 * Отримання єдиного екземпляра пулу з'єднань (патерн Singleton).
 *
 * @param url URL бази даних
 * @param user Ім'я користувача
 * @param password Пароль
 * @param maxConnections Максимальна кількість з'єднань
 * @return Екземпляр пулу з'єднань
 */
 public static ConnectionPool getInstance(String url, String user, String password, int maxConnections) {
 if (instance == null) {
 synchronized (ConnectionPool.class) {
 if (instance == null) {
 instance = new ConnectionPool(url, user, password, maxConnections);
 }
 }
 }
 return instance;
 }

 /**
 * Ініціалізація пулу з'єднань.
 */
 private void initializePool() {
 if (isInitialized.compareAndSet(false, true)) {
 for (int i = 0; i < maxConnections; i++) {
 try {
 availableConnections.add(createConnection());
 } catch (SQLException e) {
 throw new RuntimeException("Не вдалося ініціалізувати пул з'єднань", e);
 }
 }
 }
 }

 /**
 * Створення нового з'єднання з базою даних.
 *
 * @return Нове з'єднання
 * @throws SQLException У разі помилки створення з'єднання
 */
 private Connection createConnection() throws SQLException {
 return DriverManager.getConnection(url, user, password);
 }

 /**
 * Отримання з'єднання з пулу.
 *
 * @return Доступне з'єднання
 * @throws SQLException Якщо немає доступних з'єднань
 */
 public Connection getConnection() throws SQLException {
 Connection connection;
 try {
 connection = availableConnections.take(); // Блокується, якщо пул порожній
 if (connection.isClosed()) {
 connection = createConnection();
 }
 } catch (InterruptedException e) {
 Thread.currentThread().interrupt();
 throw new SQLException("Перервано очікування з'єднання", e);
 }

 synchronized (this) {
 if (usedConnections.size() >= maxConnections) {
 throw new SQLException("Досягнуто максимальної кількості з'єднань");
 }
 usedConnections.add(connection);
 }
 return connection;
 }

 /**
 * Повернення з'єднання до пулу.
 *
 * @param connection З'єднання для повернення
 */
 public void releaseConnection(Connection connection) {
 if (connection != null) {
 synchronized (this) {
 usedConnections.remove(connection);
 }
 try {
 if (!connection.isClosed()) {
 availableConnections.offer(connection);
 }
 } catch (SQLException e) {
 // Логування помилки
 }
 }
 }

 /**
 * Закриття всіх з'єднань і очищення пулу.
 *
 * @throws SQLException У разі помилки закриття з'єднань
 */
 public void shutdown() throws SQLException {
 synchronized (this) {
 for (Connection conn : availableConnections) {
 conn.close();
 }
 for (Connection conn : usedConnections) {
 conn.close();
 }
 availableConnections.clear();
 usedConnections.clear();
 isInitialized.set(false);
 instance = null;
 }
 }
}



