>(connection, Collection.class, \"collections\");\n this.audiobookFiles = new GenericRepository<>(connection, AudiobookFIle.class, \"audiobook_files\");\n this.listeningProgress = new GenericRepository<>(connection, ListeningProgress.class, \"listening_progress\");\n \n this.newEntities = new ArrayList<>();\n this.updatedEntities = new ArrayList<>();\n this.deletedEntities = new ArrayList<>();\n }\n\n /**\n * \u041e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u044e \u0434\u043b\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433.\n *\n * @return \u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0439 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\n */\n public GenericRepository<Audiobook, UUID> getAudiobooks() {\n return audiobooks;\n }\n\n /**\n * \u041e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u044e \u0434\u043b\u044f \u0430\u0432\u0442\u043e\u0440\u0456\u0432.\n *\n * @return \u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0439 \u0430\u0432\u0442\u043e\u0440\u0456\u0432\n */\n public GenericRepository<Author, UUID> getAuthors() {\n return authors;\n }\n\n /**\n * \u041e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u044e \u0434\u043b\u044f \u0436\u0430\u043d\u0440\u0456\u0432.\n *\n * @return \u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0439 \u0436\u0430\u043d\u0440\u0456\u0432\n */\n public GenericRepository<Genre, UUID> getGenres() {\n return genres;\n }\n\n /**\n * \u041e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u044e \u0434\u043b\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0456\u0432.\n *\n * @return \u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0439 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u043