\u044f \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f\n */\n public void registerNew(Object entity) {\n newEntities.add(entity);\n }\n\n /**\n * \u0420\u0435\u0454\u0441\u0442\u0440\u0430\u0446\u0456\u044f \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456 \u0434\u043b\u044f \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f.\n *\n * @param entity \u0421\u0443\u0442\u043d\u0456\u0441\u0442\u044c \u0434\u043b\u044f \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f\n */\n public void registerUpdated(Object entity) {\n updatedEntities.add(entity);\n }\n\n /**\n * \u0420\u0435\u0454\u0441\u0442\u0440\u0430\u0446\u0456\u044f \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456 \u0434\u043b\u044f \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f.\n *\n * @param entity \u0421\u0443\u0442\u043d\u0456\u0441\u0442\u044c \u0434\u043b\u044f \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f\n */\n public void registerDeleted(Object entity) {\n deletedEntities.add(entity);\n }\n\n /**\n * \u0412\u0438\u043a\u043e\u043d\u0430\u043d\u043d\u044f \u0432\u0441\u0456\u0445 \u0437\u0430\u0440\u0435\u0454\u0441\u0442\u0440\u043e\u0432\u0430\u043d\u0438\u0445 \u0437\u043c\u0456\u043d \u0443 \u0431\u0430\u0437\u0456 \u0434\u0430\u043d\u0438\u0445 \u0443 \u043c\u0435\u0436\u0430\u0445 \u043e\u0434\u043d\u0456\u0454\u0457 \u0442\u0440\u0430\u043d\u0437\u0430\u043a\u0446\u0456\u0457.\n *\n * @throws SQLException \u0423 \u0440\u0430\u0437\u0456 \u043f\u043e\u043c\u0438\u043b\u043a\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u0443 \u0434\u043e \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445\n * @throws IllegalAccessException \u0423 \u0440\u0430\u0437\u0456 \u043f\u0440\u043e\u0431\u043b\u0435\u043c \u0456\u0437 \u0434\u043e\u0441\u0442\u0443\u043f\u043e\u043c \u0434\u043e \u043f\u043e\u043b\u0456\u0432 \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456\n */\n public void commit() throws SQLException, IllegalAccessException {\n try {\n connection.setAutoCommit(false);\n\n // \u0417\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u043d\u043e\u0432\u0438\u0445 \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0435\u0439\n for (Object entity : newEntities) {\n if (entity instanceof Audiobook) {\n audiobooks.save((Audiobook) entity);\n } else if (entity instanceof Author) {\n authors.save((Author) entity);\n } else if (entity instanceof Genre) {\n genres.save((Genre) entity);\n } else if (entity instanceof User) {\n users.save((User) entity);\n } else if (entity instanceof Collection) {\n collections.save((Collection) entity);\n } else if (entity instanceof AudiobookFIle) {\n audiobookFiles.save((AudiobookFIle) entity);\n } else if (entity instanceof ListeningProgress) {\n listeningProgress.save((ListeningProgress) entity);\n }\n }\n\n // \u041e\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0456\u0441\u043d\u0443\u044e\u0447\u0438\u0445 \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0435\u0439\n for (Object entity : updatedEntities) {\n UUID id = getEntityId(entity);\n if (entity instanceof Audiobook) {\n audiobooks.update(id, (Audiobook) entity);\n } else if (entity instanceof Author) {\n authors.update(id, (Author) entity);\n } else if (entity instanceof Genre) {\n genres.update(id, (Genre) entity);\n } else if (entity instanceof User) {\n users.update(id, (User) entity);\n } else if (entity instanceof Collection) {\n collections.update(id, (Collection) entity);\n } else if (entity instanceof AudiobookFIle) {\n audiobookFiles.update(id, (AudiobookFIle) entity);\n } else if (entity instanceof ListeningProgress) {\n listeningProgress.update(id, (ListeningProgress) entity);\n }\n }\n\n // \u0412\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0435\u0439\n for (Object entity : deletedEntities) {\n UUID id = getEntityId(entity);\n if (entity instanceof Audiobook) {\n audiobooks.delete(id);\n } else if (entity instanceof Author) {\n authors.delete(id);\n } else if (entity instanceof Genre) {\n genres.delete(id);\n } else if (entity instanceof User) {\n users.delete(id);\n } else if (entity instanceof Collection) {\n collections.delete(id);\n } else if (entity instanceof AudiobookFIle) {\n audiobookFiles.delete(id);\n } else if (entity instanceof ListeningProgress) {\n listeningProgress.delete(id);\n }\n }\n\n connection.commit();\n clear();\n } catch (Exception e) {\n connection.rollback();\n throw new SQLException(\"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0432\u0438\u043a\u043e\u043d\u0430\u0442\u0438 \u0442\u0440\u0430\u043d\u0437\u0430\u043a\u0446\u0456\u044e\", e);\n } finally {\n connection.setAutoCommit(true);\n }\n }\n\n /**\n * \u041e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\u0430 \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456.\n *\n * @param entity \u0421\u0443\u0442\u043d\u0456\u0441\u0442\u044c\n * @return \u0406\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456\n * @throws IllegalAccessException \u0423 \u0440\u0430\u0437\u0456 \u043f\u0440\u043e\u0431\u043b\u0435\u043c \u0456\u0437 \u0434\u043e\u0441\u0442\u0443\u043f\u043e\u043c \u0434\u043e \u043f\u043e\u043b\u0456\u0432 \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456\n */\n private UUID getEntityId(Object entity) throws IllegalAccessException {\n try {\n Field idField = entity.getClass().getDeclaredField(\"id\");\n idField.setAccessible(true);\n return (UUID) idField.get(entity);\n } catch (NoSuchFieldException e) {\n throw new IllegalAccessException(\"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438 \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0441\u0443\u0442\u043d\u043e\u0441\u0442\u0456\");\n }\n }\n\n /**\n * \u041e\u0447\u0438\u0449\u0435\u043d\u043d\u044f \u0441\u043f\u0438\u0441\u043a\u0456\u0432 \u0437\u0430\u