 26	 GenericRepository<User, UUID> getUsers();
 27	 GenericRepository<Collection, UUID> getCollections();
 28	 GenericRepository<AudiobookFIle, UUID> getAudiobookFiles();
 29	 GenericRepository<ListeningProgress, UUID> getListeningProgress();
 30	 
 31	 void beginTransaction() throws SQLException;
 32	 void commitTransaction() throws SQLException;
 33	 void rollbackTransaction() throws SQLException;
 34	 Connection getConnection();
 35	 void close() throws Exception;
 36	}
 37	```
