 95	 @SuppressWarnings("unchecked")
 96	 public void commit() throws SQLException, IllegalAccessException {
 97	 try {
 98	 connection.setAutoCommit(false);
 99	
 100	 // Збереження нових сутностей
 101	 for (Object entity : newEntities) {
 102	 processEntity(entity, OperationType.SAVE);
 103	 }
 104	
 105	 // Оновлення існуючих сутностей
 106	 for (Object entity : updatedEntities) {
 107	 processEntity(entity, OperationType.UPDATE);
 108	 }
 109	
 110	 // Видалення сутностей
 111	 for (Object entity : deletedEntities) {
 112	 processEntity(entity, OperationType.DELETE);
 113	 }
 114	
 115	 connection.commit();
 116	 clear();
 117	 } catch (Exception e) {
 118	 connection.rollback();
 119	 throw new SQLException("Не вдалося виконати транзакцію", e);
 120	 } finally {
 121	 connection.setAutoCommit(true);
 122	 }
 123	 }
