 140	 @SuppressWarnings("unchecked")
 141	 private <T> void processEntity(Object entity, OperationType operationType) throws SQLException, IllegalAccessException, NoSuchFieldException {
 142	 Class<?> entityClass = entity.getClass();
 143	 GenericRepository<T, Object> repo = (GenericRepository<T, Object>) getRepository((Class<T>) entityClass);
 144	 T typedEntity = (T) entity;
 145	
 146	 switch (operationType) {
 147	 case SAVE:
 148	 repo.save(typedEntity);
 149	 break;
 150	 case UPDATE:
 151	 Object updateId = entityClass.getDeclaredField("id").get(entity);
 152	 repo.update(updateId, typedEntity);
 153	 break;
 154	 case DELETE:
 155	 Object deleteId = entityClass.getDeclaredField("id").get(entity);
 156	 repo.delete(deleteId);
 157	 break;
 158	 }
 159	 }
