package com.arakviel.persistence.util;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.Objects;
import java.util.stream.Collectors;
import org.springframework.stereotype.Component;

@Component
public final class DatabaseInitializer {

 private final ConnectionManager connectionManager;

 public DatabaseInitializer(ConnectionManager connectionManager) {
 this.connectionManager = connectionManager;
 }

 public void init() {

 try (Connection connection = connectionManager.get();
 Statement statementForDDL = connection.createStatement();
 Statement statementForDML = connection.createStatement()) {
 statementForDDL.execute(getSQL("ddl.sql"));
 statementForDML.execute(getSQL("dml.sql"));
 } catch (SQLException throwables) {
 throw new RuntimeException(throwables);
 }
 }

 private String getSQL(final String resourceName) {
 return new BufferedReader(
 new InputStreamReader(
 Objects.requireNonNull(
 ConnectionManager.class
 .getClassLoader()
 .getResourceAsStream(resourceName))))
 .lines()
 .collect(Collectors.joining("\n"));
 }
}","rich_text_json_repr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"зайди в resources, і запускай ініціалізацію бази даних при запуску програми. Якщо вона вже існує, тоді не потрібно. Зроби H2 як файлу базу даних. Викор. найкращі практики."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"ось приклад, із старого проєкту."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"package com.arakviel.persistence.util;"},{"type":"hardBreak"},{"type":"text","text":""},{"type":"hardBreak"},{"type":"text","text":"import java.io.BufferedReader;"},{"type":"hardBreak"},{"type":"text","text":"import java.io.InputStreamReader;"},{"type":"hardBreak"},{"type":"text","text":"import java.sql.Connection;"},{"type":"hardBreak"},{"type":"text","text":"import java.sql.SQLException;"},{"type":"hardBreak"},{"type":"text","text":"import java.sql.Statement;"},{"type":"hardBreak"},{"type":"text","text":"import java.util.Objects;"},{"type":"hardBreak"},{"type":"text","text":"import java.util.stream.Collectors;"},{"type":"hardBreak"},{"type":"text","text":"import org.springframework.stereotype.Component;"},{"type":"hardBreak"},{"type":"text","text":""},{"type":"hardBreak"},{"type":"text","text":"@Component"},{"type":"hardBreak"},{"type":"text","text":"public final class DatabaseInitializer {"},{"type":"hardBreak"},{"type":"text","text":""},{"type":"hardBreak"},{"type":"text","text":" private final ConnectionManager connectionManager;"},{"type":"hardBreak"},{"type":"text","text":""},{"type":"hardBreak"},{"type":"text","text":" public DatabaseInitializer(ConnectionManager connectionManager) {"},{"type":"hardBreak"},{"type":"text","text":" this.connectionManager = connectionManager;"},{"type":"hardBreak"},{"type":"text","text":" }"},{"type":"hardBreak"},{"type":"text","text":""},{"type":"hardBreak"},{"type":"text","text":" public void init() {"},{"type":"hardBreak"},{"type":"text","text":""},{"type":"hardBreak"}