043d\u0430 CREATE DOMAIN \u0434\u043b\u044f H2\n ddlScript = ddlScript.replace(\"CREATE TYPE file_format_enum AS ENUM\", \n \"CREATE DOMAIN file_format_enum AS VARCHAR(10) CHECK (VALUE IN\");\n \n // \u0412\u0438\u043f\u0440\u0430\u0432\u043b\u044f\u0454\u043c\u043e \u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0441 ON DELETE CASCADE\n ddlScript = ddlScript.replace(\",\\n ON DELETE CASCADE\", \" ON DELETE CASCADE\");\n \n // \u0412\u0438\u043a\u043e\u043d\u0443\u0454\u043c\u043e \u043a\u043e\u0436\u0435\u043d \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 \u043e\u043a\u0440\u0435\u043c\u043e\n try {\n // \u0421\u043f\u043e\u0447\u0430\u0442\u043a\u0443 \u0441\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e users\n String createUsersTable = \"CREATE TABLE users (\\n\" +\n \" PRIMARY KEY(id),\\n\" +\n \" id UUID,\\n\" +\n \" username VARCHAR(64) NOT NULL,\\n\" +\n \" CONSTRAINT users_username_key\\n\" +\n \" UNIQUE (username),\\n\" +\n \" CONSTRAINT users_username_not_empty_check\\n\" +\n \" CHECK (length(trim(username)) > 0),\\n\" +\n \" password_hash VARCHAR(256) NOT NULL,\\n\" +\n \" email VARCHAR(256) NOT NULL,\\n\" +\n \" CONSTRAINT users_email_key\\n\" +\n \" UNIQUE (email),\\n\" +\n \" CONSTRAINT users_email_not_empty_check\\n\" +\n \" CHECK (length(trim(email)) > 0)\\n\" +\n \")\";\n statementForDDL.execute(createUsersTable);\n \n // \u041f\u043e\u0442\u0456\u043c \u0441\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e authors\n String createAuthorsTable = \"CREATE TABLE authors (\\n\" +\n \" PRIMARY KEY(id),\\n\" +\n \" id UUID,\\n\" +\n \" first_name VARCHAR(64) NOT NULL,\\n\" +\n \" last_name VARCHAR(64) NOT NULL,\\n\" +\n \" bio TEXT,\\n\" +\n \" image_path VARCHAR(2048)\\n\" +\n \")\";\n statementForDDL.execute(createAuthorsTable);\n \n // \u0421\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e genres\n String createGenresTable = \"CREATE TABLE genres (\\n\" +\n \" PRIMARY KEY(id),\\n\" +\n \" id UUID,\\n\" +\n \" name VARCHAR(64) NOT NULL,\\n\" +\n \" CONSTRAINT genres_name_key\\n\" +\n \" UNIQUE (name),\\n\" +\n \" description TEXT\\n\" +\n \")\";\n statementForDDL.execute(createGenresTable);\n \n // \u0421\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e collections\n String createCollectionsTable = \"CREATE TABLE collections (\\n\" +\n \" PRIMARY KEY(id),\\n\" +\n \" id UUID,\\n\" +\n \" user_id UUID,\\n\" +\n \" CONSTRAINT collections_user_id_users_id_fkey\\n\" +\n \" FOREIGN KEY (user_id)\\n\" +\n \" REFERENCES users(id) ON DELETE CASCADE,\\n\" +\n \" name VARCHAR(128) NOT NULL,\\n\" +\n \" CONSTRAINT collections_name_not_empty_check\\n\" +\n \" CHECK (length(trim(name)) > 0),\\n\" +\n \" created_at TIMESTAMP\\n\" +\n \")\";\n statementForDDL.execute(createCollectionsTable);\n \n // \u0421\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e audiobooks\n String createAudiobooksTable = \"CREATE TABLE audiobooks (\\n\" +\n \" PRIMARY KEY(id),\\n\" +\n \" id UUID,\\n\" +\n \" author_id UUID,\\n\" +\n \" CONSTRAINT audiobooks_author_id_authors_id_fkey\\n\" +\n \" FOREIGN KEY (author_id)\\n\" +\n \" REFERENCES authors(id) ON DELETE CASCADE,\\n\" +\n \" genre_id UUID,\\n\" +\n \" CONSTRAINT audiobooks_genre_id_genres_id_fkey\\n\" +\n \" FOREIGN KEY (genre_id)\\n\" +\n \" REFERENCES genres(id) ON DELETE CASCADE,\\n\" +\n \" title VARCHAR(256) NOT NULL,\\n\" +\n \" CONSTRAINT audiobooks_title_not_empty_check\\n\" +\n \" CHECK (length(trim(title)) > 0),\\n\" +\n \" duration INTEGER NOT NULL,\\n\" +\n \" CONSTRAINT audiobooks_duration_positive_check\\n\" +\n \" CHECK (duration > 0),\\n\" +\n \" release_year INTEGER,\\n\" +\n \" CONSTRAINT audiobooks_release_year_range_check\\n\" +\n \" CHECK (release_year BETWEEN 1900 AND 2100),\\n\" +\n \" description TEXT,\\n\" +\n \" cover_image_path VARCHAR(2048)\\n\" +\n \")\";\n statementForDDL.execute(createAudiobooksTable);\n \n // \u0421\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e audiobook_files\n String createAudiobookFilesTable = \"CREATE TABLE audiobook_files (\\n\" +\n \" PRIMARY KEY(id),\\n\" +\n \" id UUID,\\n\" +\n \" audiobook_id UUID,\\n\" +\n \" CONSTRAINT audiobook_files_audiobook_id_audiobooks_id_fkey\\n\" +\n \" FOREIGN KEY (audiobook_id)\\n\" +\n \" REFERENCES audiobooks(id) ON DELETE CASCADE,\\n\" +\n \" file_path VARCHAR(2048) NOT NULL,\\n\" +\n \" file_format VARCHAR(10) NOT NULL,\\n\" +\n \" file_size BIGINT NOT NULL,\\n\" +\n \" CONSTRAINT audiobook_files_file_size_positive_check\\n\" +\n \" CHECK (file_size > 0),\\n\" +\n \" duration INTEGER NOT NULL,\\n\" +\n \" CONSTRAINT audiobook_files_duration_positive_check\\n\" +\n \" CHECK (duration > 0),\\n\" +\n \" bitrate INTEGER NOT NULL,\\n\" +\n \" CONSTRAINT audiobook_files_bitrate_positive_check\\n\" +\n \" CHECK (bitrate > 0)\\n\" +\n \")\";\n statementForDDL.execute(createAudiobookFilesTable);\n \n // \u0421\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e audiobook_collection\n String createAudiobookCollectionTable = \"CREATE TABLE audiobook_collection (\\n\" +\n \" PRIMARY KEY(audiobook_id, collection_id),\\n\" +\n \" audiobook_id UUID,\\n\" +\n \" CONSTRAINT audiobook_collection_audiobook_id_audiobooks_id_fkey\\n\" +\n \" FOREIGN KEY (audiobook_id)\\n\" +\n \" REFERENCES audiobooks(id) ON DELETE CASCADE,\\n\" +\n \" collection_id UUID,\\n\" +\n \" CONSTRAINT audiobook_collection_collection_id_collections_id_fkey\\n\" +\n \" FOREIGN KEY (collection_id)\\n\" +\n \" REFERENCES collections(id) ON DELETE CASCADE\\n\" +\n \")\";\n statementForDDL.execute(createAudiobookCollectionTable);\n \n // \u0421\u0442\u0432\u043e\u0440\u044e\u0454\u043c\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u044e listening_progress\n String createListeningProgressTable = \"CREATE TABLE listening_progress (\\n\" +\n \" PRIMARY KEY(id),\\n\" +\n \" id UUID,\\n\" +\n \" user_id UUID,\\n\" +\n \" CONSTRAINT listening_progress_user_id_users_id_fkey\\n\" +\n \" FOREIGN KEY (user_id)\\n\" +\n \" REFERENCES users(id) ON DELETE CASCADE,\\n\" +\n \" audiobook_id UUID,\\n\" +\n \" CONSTRAINT listening_progress_audiobook_id_audiobooks_id_fkey\\n\" +\n \" FOREIGN KEY (audiobook_id)\\n\" +\n \" REFERENCES audiobooks(id) ON DELETE CASCADE,\\n\" +\n \" position INTEGER NOT NULL,\\n\" +\n \" CONSTRAINT listening_progress_position_positive_check\\n\" +\n \" CHECK (position >= 0),\\n\" +\n \" updated_at TIMESTAMP NOT NULL\\n\" +\n \")\";\n statementForDDL.execute(createListeningProgressTable);\n \n } catch (SQLException e) {\n System.err.println(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u0456 \u0442\u0430\u0431\u043b\u0438\u0446\u044c: \" + e.getMessage());\n throw e;\n }", "old_str_start_line_number": 80, "old_str_end_line_number": 90}]}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Я бачу помилку синтаксису в SQL-скрипті при створенні таблиці `collections`. Проблема в рядку з `ON DELETE CASCADE`, який не може бути окремим рядком в H2. Давайте виправимо цю помилку в методі `createDatabase` класу `DatabaseInitializer`:
