 348	 public static String camelCaseToSnakeCase(String input) {
 349	 if (input == null || input.isEmpty()) {
 350	 return input;
 351	 }
 352	 return input.replaceAll("([a-z])([A-Z]+)", "$1_$2").toLowerCase();
 353	 }
 354	
 355	 public static String snakeCaseToCamelCase(String input) {
 356	 if (input == null || input.isEmpty()) {
 357	 return input;
 358	 }
 359	 StringBuilder result = new StringBuilder();
 360	 boolean toUpperCase = false;
 361	 for (char ch : input.toCharArray()) {
 362	 if (ch == '_') {
 363	 toUpperCase = true;
 364	 } else {
 365	 result.append(toUpperCase ? Character.toUpperCase(ch) : ch);
 366	 toUpperCase = false;
 367	 }
 368	 }
 369	 return result.toString();
 370	 }
 371	}
