package com.arakviel.infrastructure.persistence;

import com.arakviel.domain.enitites.Audiobook;
import com.arakviel.domain.enitites.Collection;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * Клас для управління зв'язками між сутностями.
 * Відповідає за завантаження та збереження зв'язків між сутностями, такими як Audiobook та Collection.
 */
public class EntityRelationshipManager {
 private final Connection connection;

 /**
 * Створює новий менеджер зв'язків між сутностями.
 *
 * @param connection з'єднання з базою даних
 */
 public EntityRelationshipManager(Connection connection) {
 this.connection = connection;
 }

 /**
 * Завантажує колекції для аудіокниги.
 *
 * @param audiobook аудіокнига, для якої потрібно завантажити колекції
 * @throws SQLException якщо виникла помилка при роботі з базою даних
 */
 public void loadCollectionsForAudiobook(Audiobook audiobook) throws SQLException {
 String sql = """
 SELECT c.* FROM collections c
 INNER JOIN audiobook_collection ac ON c.id = ac.collection_id
 WHERE ac.audiobook_id = ?
 """;
 try (PreparedStatement statement = connection.prepareStatement(sql)) {
 statement.setObject(1, audiobook.getId());
 try (ResultSet resultSet = statement.executeQuery()) {
 List<Collection> collections = new ArrayList<>();
 while (resultSet.next()) {
 Collection collection = mapResultSetToCollection(resultSet);
 collections.add(collection);
 }
 audiobook.setCollections(collections);
 }
 }
 }

 /**
 * Завантажує аудіокниги для колекції.
 *
 * @param collection колекція, для якої потрібно завантажити аудіокниги
 * @throws SQLException якщо виникла помилка при роботі з базою даних
 */
 public void loadAudiobooksForCollection(Collection collection) throws SQLException {
 String sql = """
 SELECT a.* FROM audiobooks a
 INNER JOIN audiobook_collection ac ON a.id = ac.audiobook_id
 WHERE ac.collection_id = ?
 """;
 try (PreparedStatement statement = connection.prepareStatement(sql)) {
 statement.setObject(1, collection.getId());
 try (ResultSet resultSet = statement.executeQuery()) {
 List<Audiobook> audiobooks = new ArrayList<>();
 while (resultSet.next()) {
 Audiobook audiobook = mapResultSetToAudiobook(resultSet);
 audiobooks.add(audiobook);
 }
 collection.setAudiobooks(audiobooks);
 }
 }
 }

 /**
 * Додає аудіокнигу до колекції.
 *
 * @param audiobookId ідентифікатор аудіокниги
 * @param collectionId ідентифікатор колекції
 * @throws SQLException якщо виникла помилка при роботі з базою даних
 */
 public void addAudiobookToCollection(UUID audiobookId, UUID collectionId) throws SQLException {
 String sql = "INSERT INTO audiobook_collection (audiobook_id, collection_id) VALUES (?, ?)";
 try (PreparedStatement statement = connection.prepareStatement(sql)) {
 statement.setObject(1, audiobookId);
 statement.setObject(2, collectionId);
 statement.executeUpdate();
 }
 }

 /**
 * Видаляє аудіокнигу з колекції.
 *
 * @param audiobookId ідентифікатор аудіокниги
 * @param collectionId ідентифікатор колекції
 * @throws SQLException якщо виникла помилка при роботі з базою даних
 */
 public void removeAudiobookFromCollection(UUID audiobookId, UUID collectionId) throws SQLException {
 String sql = "DELETE FROM audiobook_collection WHERE audiobook_id = ? AND collection_id = ?";
 try (PreparedStatement statement = connection.prepareStatement(sql)) {
 statement.setObject(1, audiobookId);
 statement.setObject(2, collectionId);
 statement.executeUpdate();
 }
 }
...

 /**
 * Видаляє всі зв'язки для колекції.
 *
 * @param collectionId ідентифікатор колекції
 * @throws SQLException якщо виникла помилка при роботі з базою даних
 */
 public void deleteCollectionRelationships(UUID collectionId) throws SQLException {
 String sql = "DELETE FROM audiobook_collection WHERE collection_id = ?";
 try (PreparedStatement statement = connection.prepareStatement(sql)) {
 statement.setObject(1, collectionId);
 statement.executeUpdate();
 }
 }

 /**
 * Зберігає зв'язки між аудіокнигою та її колекціями.
 *
 * @param audiobook аудіокнига, зв'язки якої потрібно зберегти
 * @throws SQLException якщо виникла помилка при роботі з базою даних
 */
 public void saveAudiobookCollections(Audiobook audiobook) throws SQLException {
 if (audiobook.getId() == null || audiobook.getCollections() == null) {
 return;
 }

 // Видаляємо існуючі зв'язки
 deleteAudiobookRelationships(audiobook.getId());

 // Додаємо нові зв'язки
 for (Collection collection : audiobook.getCollections()) {
 if (collection.getId() != null) {
 addAudiobookToCollection(audiobook.getId(), collection.getId());
 }
 }
 }

 /**
 * Зберігає зв'язки між колекцією та її аудіокнигами.
 *
 * @param collection колекція, зв'язки якої потрібно зберегти
 * @throws SQLException якщо виникла помилка при роботі з базою даних
 */
 public void saveCollectionAudiobooks(Collection collection) throws SQLException {
 if (collection.getId() == null || collection.getAudiobooks() == null) {
 return;
 }

 // Видаляємо існуючі зв'язки
 deleteCollectionRelationships(collection.getId());

 // Додаємо нові зв'язки
 for (Audiobook audiobook : collection.getAudiobooks()) {
 if (audiobook.getId() != null) {
 addAudiobookToCollection(audiobook.getId(), collection.getId());
 }
 }
 }

 /**
 * Відображає ResultSet на об'єкт Collection.
 *
 * @param resultSet результат запиту
 * @return об'єкт Collection
 * @throws SQLException якщо виникла помилка при роботі з ResultSet
 */
 private Collection mapResultSetToCollection(ResultSet resultSet) throws SQLException {
 Collection collection = new Collection();
 collection.setId(UUID.fromString(resultSet.getString("id")));
 collection.setUserId(UUID.fromString(resultSet.getString("user_id")));
 collection.setName(resultSet.getString("name"));
 collection.setCreatedAt(resultSet.getTimestamp("created_at").toLocalDateTime());
 return collection;
 }

 /**
 * Відображає ResultSet на об'єкт Audiobook.
 *
 * @param resultSet результат запиту
 * @return об'єкт Audiobook
 * @throws SQLException якщо виникла помилка при роботі з ResultSet
 */
 private Audiobook mapResultSetToAudiobook(ResultSet resultSet) throws SQLException {
 Audiobook audiobook = new Audiobook();
 audiobook.setId(UUID.fromString(resultSet.getString("id")));
 audiobook.setAuthorId(UUID.fromString(resultSet.getString("author_id")));
 audiobook.setGenreId(UUID.fromString(resultSet.getString("genre_id")));
 audiobook.setTitle(resultSet.getString("title"));
 audiobook.setDuration(resultSet.getInt("duration"));
 audiobook.setReleaseYear(resultSet.getInt("release_year"));
 audiobook.setDescription(resultSet.getString("description"));
