 1	package com.arakviel.infrastructure.persistence;
 2	
 3	import java.sql.Connection;
 4	import java.sql.DriverManager;
 5	import java.sql.SQLException;
 6	import java.util.concurrent.ArrayBlockingQueue;
 7	import java.util.concurrent.BlockingQueue;
 8	import java.util.concurrent.atomic.AtomicBoolean;
 9	
 10	/**
 11	 * Пул з'єднань для управління JDBC-з'єднаннями з базою даних.
 12	 * Забезпечує потокобезпечне отримання та повернення з'єднань із підтримкою обмеження максимальної кількості з'єднань.
 13	 */
 14	public class ConnectionPool {
 15	 private static volatile ConnectionPool instance;
 16	 private final BlockingQueue<Connection> availableConnections;
 17	 private final BlockingQueue<Connection> usedConnections;
 18	 private final String url;
 19	 private final String user;
 20	 private final String password;
 21	 private final int maxConnections;
 22	 private final AtomicBoolean isInitialized = new AtomicBoolean(false);
 23	
 24	 /**
 25	 * Приватний конструктор для ініціалізації пулу з'єднань.
 26	 *
 27	 * @param url URL бази даних
 28	 * @param user Ім'я користувача
 29	 * @param password Пароль
 30	 * @param maxConnections Максимальна кількість з'єднань
 31	 */
 32	 private ConnectionPool(String url, String user, String password, int maxConnections) {
 33	 this.url = url;
 34	 this.user = user;
 35	 this.password = password;
 36	 this.maxConnections = maxConnections;
 37	 this.availableConnections = new ArrayBlockingQueue<>(maxConnections);
 38	 this.usedConnections = new ArrayBlockingQueue<>(maxConnections);
 39	 initializePool();
 40	 }
 41	
 42	 /**
 43	 * Отримання єдиного екземпляра пулу з'єднань (патерн Singleton).
 44	 *
 45	 * @param url URL бази даних
 46	 * @param user Ім'я користувача
 47	 * @param password Пароль
 48	 * @param maxConnections Максимальна кількість з'єднань
 49	 * @return Екземпляр пулу з'єднань
 50	 */
 51	 public static ConnectionPool getInstance(String url, String user, String password, int maxConnections) {
 52	 if (instance == null) {
 53	 synchronized (ConnectionPool.class) {
 54	 if (instance == null) {
 55	 instance = new ConnectionPool(url, user, password, maxConnections);
 56	 }
 57	 }
 58	 }
 59	 return instance;
 60	 }
 61	
 62	 /**
 63	 * Ініціалізація пулу з'єднань.
 64	 */
 65	 private void initializePool() {
 66	 if (isInitialized.compareAndSet(false, true)) {
 67	 for (int i = 0; i < maxConnections; i++) {
 68	 try {
 69	 availableConnections.add(createConnection());
 70	 } catch (SQLException e) {
 71	 throw new RuntimeException("Не вдалося ініціалізувати пул з'єднань", e);
 72	 }
 73	 }
 74	 }
 75	 }
 76	
 77	 /**
 78	 * Створення нового з'єднання з базою даних.
 79	 *
 80	 * @return Нове з'єднання
 81	 * @throws SQLException У разі помилки створення з'єднання
 82	 */
 83	 private Connection createConnection() throws SQLException {
 84	 return DriverManager.getConnection(url, user, password);
 85	 }
 86	
 87	 /**
 88	 * Отримання з'єднання з пулу.
 89	 *
 90	 * @return Доступне з'єднання
 91	 * @throws SQLException Якщо немає доступних з'єднань
 92	 */
 93	 public Connection getConnection() throws SQLException {
 94	 Connection connection;
 95	 try {
 96	 connection = availableConnections.take(); // Блокується, якщо пул порожній
 97	 if (connection.isClosed()) {
 98	 connection = createConnection();
 99	 }
 100	 } catch (InterruptedException e) {
 101	 Thread.currentThread().interrupt();
 102	 throw new SQLException("Перервано очікування з'єднання", e);
 103	 }
 104	
 105	 synchronized (this) {
 106	 if (usedConnections.size() >= maxConnections) {
 107	 throw new SQLException("Досягнуто максимальної кількості з'єднань");
 108	 }
 109	 usedConnections.add(connection);
 110	 }
 111	 return connection;
 112	 }
 113	
 114	 /**
 115	 * Повернення з'єднання до пулу.
 116	 *
 117	 * @param connection З'єднання для повернення
 118	 */
 119	 public void releaseConnection(Connection connection) {
 120	 if (connection != null) {
 121	 synchronized (this) {
 122	 usedConnections.remove(connection);
 123	 }
 124	 try {
 125	 if (!connection.isClosed()) {
 126	 availableConnections.offer(connection);
 127	 }
 128	 } catch (SQLException e) {
 129	 // Логування помилки
 130	 }
 131	 }
 132	 }
 133	
 134	 /**
 135	 * Закриття всіх з'єднань і очищення пулу.
 136	 *
 137	 * @throws SQLException У разі помилки закриття з'єднань
 138	 */
 139	 public void shutdown() throws SQLException {
 140	 synchronized (this) {
 141	 for (Connection conn : availableConnections) {
 142	 conn.close();
 143	 }
 144	 for (Connection conn : usedConnections) {
 145	 conn.close();
 146	 }
 147	 availableConnections.clear();
 148	 usedConnections.clear();
 149	 isInitialized.set(false);
 150	 instance = null;
 151	 }
 152	 }
 153	}
