package com.arakviel.infrastructure.persistence;

import com.arakviel.domain.enums.FileFormat;
import java.lang.reflect.Field;
import java.sql.*;
import java.time.LocalDateTime;
import java.util.*;
import java.util.function.Function;

/**
 * Abstract generic repository providing common database operations.
 *
 * @param <T> the entity type
 * @param <ID> the type of the entity's identifier
 */
public abstract class GenericRepository<T, ID> implements Repository<T, ID> {

 protected final Connection connection;
 protected final Class<T> entityClass;
 protected final String tableName;

 @FunctionalInterface
 public interface Filter {
 void apply(StringJoiner whereClause, List<Object> parameters);
 }

 @FunctionalInterface
 public interface Aggregation {
 void apply(StringJoiner selectClause, StringJoiner groupByClause);
 }

 protected GenericRepository(Connection connection, Class<T> entityClass, String tableName) {
 this.connection = connection;
 this.entityClass = entityClass;
 this.tableName = tableName;
 }

 @Override
 public Optional<T> findById(ID id) throws SQLException {
 return findBy("id", id).stream().findFirst();
 }

 @Override
 public List<T> findBy(String fieldName, Object value) throws SQLException {
 var sql = String.format("SELECT * FROM %s WHERE %s = ?", tableName, fieldName);
 try (var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, value);
 try (var resultSet = statement.executeQuery()) {
 return mapResultSetToList(resultSet);
 }
 }
 }

 @Override
 public List<T> findAll(Filter filter, String sortBy, boolean isAscending, int offset, int limit) throws SQLException {
 var sql = new StringJoiner(" ");
 sql.add(String.format("SELECT * FROM %s", tableName));
 List<Object> parameters = new ArrayList<>();
 if (filter != null) {
 var whereClause = new StringJoiner(" AND ", " WHERE ", "");
 filter.apply(whereClause, parameters);
 sql.add(whereClause.toString());
 }
 if (sortBy != null && !sortBy.isEmpty()) {
 sql.add("ORDER BY " + sortBy + (isAscending ? " ASC" : " DESC"));
 }
 sql.add("OFFSET ? LIMIT ?");
 parameters.add(offset);
 parameters.add(limit);

 try (var statement = connection.prepareStatement(sql.toString())) {
 for (int i = 0; i < parameters.size(); i++) {
 statement.setObject(i + 1, parameters.get(i));
 }
 try (var resultSet = statement.executeQuery()) {
 return mapResultSetToList(resultSet);
 }
 }
 }

 @Override
 public long count(Filter filter) throws SQLException {
 var sql = new StringJoiner(" ");
 sql.add(String.format("SELECT COUNT(*) FROM %s", tableName));
 List<Object> parameters = new ArrayList<>();
 if (filter != null) {
 var whereClause = new StringJoiner(" AND ", " WHERE ", "");
 filter.apply(whereClause, parameters);
 sql.add(whereClause.toString());
 }

 try (var statement = connection.prepareStatement(sql.toString())) {
 for (int i = 0; i < parameters.size(); i++) {
 statement.setObject(i + 1, parameters.get(i));
 }
 try (var resultSet = statement.executeQuery()) {
 return resultSet.next() ? resultSet.getLong(1) : 0;
 }
 }
 }

 @Override
 public <R> List<R> groupBy(Aggregation aggregation, Function<ResultSet, R> resultMapper) throws SQLException {
 var selectClause = new StringJoiner(", ", "SELECT ", "");
 var groupByClause = new StringJoiner(", ", " GROUP BY ", "");
 aggregation.apply(selectClause, groupByClause);
 var sql = String.format("%s FROM %s%s", selectClause, tableName, groupByClause);
 try (var statement = connection.prepareStatement(sql);
 var resultSet = statement.executeQuery()) {
 List<R> results = new ArrayList<>();
 while (resultSet.next()) {
 results.add(resultMapper.apply(resultSet));
 }
 return results;
 }
 }

 @Override
 public T save(T entity) throws SQLException, IllegalAccessException {
 Field[] fields = entityClass.getDeclaredFields();
 var columns = new StringJoiner(", ");
 var placeHolders = new StringJoiner(", ");
 List<Object> values = new ArrayList<>();

 for (Field field : fields) {
 if (!field.getName().equals("id")) {
 field.setAccessible(true);
 columns.add(camelCaseToSnakeCase(field.getName()));
 placeHolders.add("?");
 Object value = field.get(entity);
 if (field.getType() == LocalDateTime.class) {
 value = value != null ? Timestamp.valueOf((LocalDateTime) value) : null;
 }
 values.add(value);
 }
 }

 var sql = String.format("INSERT INTO %s (%s) VALUES (%s)", tableName, columns, placeHolders);
 try (var statement = connection.prepareStatement(sql)) {
 for (int i = 0; i < values.size(); i++) {
 statement.setObject(i + 1, values.get(i));
 }
 statement.executeUpdate();
 }
 return entity;
 }

 @Override
 public T update(ID id, T entity) throws SQLException, IllegalAccessException {
 Field[] fields = entityClass.getDeclaredFields();
 var setClause = new StringJoiner(", ");
 List<Object> values = new ArrayList<>();

 for (Field field : fields) {
 if (!field.getName().equals("id")) {
 field.setAccessible(true);
 setClause.add(camelCaseToSnakeCase(field.getName()) + " = ?");
 Object value = field.get(entity);
 if (field.getType() == LocalDateTime.class) {
 value = value != null ? Timestamp.valueOf((LocalDateTime) value) : null;
 }
 values.add(value);
 }
 }

 var sql = String.format("UPDATE %s SET %s WHERE id = ?", tableName, setClause);
 try (var statement = connection.prepareStatement(sql)) {
 for (int i = 0; i < values.size(); i++) {
 statement.setObject(i + 1, values.get(i));
 }
 statement.setObject(values.size() + 1, id);
 statement.executeUpdate();
 }
 return entity;
 }

 @Override
 public void delete(ID id) throws SQLException {
 var sql = String.format("DELETE FROM %s WHERE id = ?", tableName);
 try (var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, id);
 statement.executeUpdate();
 }
 }

 protected T mapResultSetToEntity(ResultSet rs) throws SQLException {
 try {
 T entity = entityClass.getDeclaredConstructor().newInstance();
 Field[] fields = entityClass.getDeclaredFields();
 for (Field field : fields) {
 field.setAccessible(true);
 String columnName = camelCaseToSnakeCase(field.getName());
 try {
 Object value = rs.getObject(columnName);
 if (value != null) {
 field.set(entity, convertValue(value, field.getType()));
 }
 } catch (SQLException e) {
 // Ignore if column doesn't exist
 }
 }
 return entity;
 } catch (Exception e) {
 throw new SQLException("Failed to map ResultSet to entity", e);
 }
 }

 protected List<T> mapResultSetToList(ResultSet resultSet) throws SQLException {
 List<T> entities = new ArrayList<>();
 while (resultSet.next()) {
 entities.add(mapResultSetToEntity(resultSet));
 }
 return entities;
 }

 protected Object convertValue(Object value, Class<?> targetType) {
 if (value == null && !targetType.isPrimitive()) {
 return null;
 }
 switch (targetType.getName()) {
 case "java.lang.String":
 return value.toString();
 case "java.util.UUID":
 return value instanceof String ? UUID.fromString((String) value) : value;
 case "java.lang.Integer":
 case "int":
 return value instanceof Number ? ((Number) value).intValue() : value;
 case "java.time.LocalDateTime":
 return value instanceof Timestamp ? ((Timestamp) value).toLocalDateTime() : null;
 case "com.arakviel.domain.enums.FileFormat":
 return value instanceof String ? FileFormat.valueOf((String) value) : value;
 default:
 return value;
 }
 }

 protected static String camelCaseToSnakeCase(String input) {
 return input == null || input.isEmpty() ? input :
 input.replaceAll("([a-z])([A-Z]+)", "$1_$2").toLowerCase();
 }
