package com.arakviel.infrastructure.persistence.impl;

import com.arakviel.domain.enitites.Audiobook;
import com.arakviel.infrastructure.persistence.GenericRepository;

import java.sql.Connection;
import java.sql.SQLException;
import java.util.List;
import java.util.UUID;

/**
 * Repository implementation for Audiobook-specific operations.
 */
public class AudiobookRepository extends GenericRepository<Audiobook, UUID> implements AudiobookRepository {

 public AudiobookRepository(Connection connection) {
 super(connection, Audiobook.class, "audiobooks");
 }

 @Override
 public List<Audiobook> findByAuthorId(UUID authorId) throws SQLException {
 return findBy("author_id", authorId);
 }

 @Override
 public List<Audiobook> findByGenreId(UUID genreId) throws SQLException {
 return findBy("genre_id", genreId);
 }

 @Override
 public List<AudiobookFile> findFilesByAudiobookId(UUID audiobookId) throws SQLException {
 var sql = "SELECT * FROM audiobook_files WHERE audiobook_id = ?";
 try (var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, audiobookId);
 try (var resultSet = statement.executeQuery()) {
 return mapResultSetToAudiobookFiles(resultSet);
 }
 }
 }

 @Override
 public List<Audiobook> findByCollectionId(UUID collectionId) throws SQLException {
 var sql = """
 SELECT a.*
 FROM audiobooks a
 JOIN collection_audiobooks ca ON a.id = ca.audiobook_id
 WHERE ca.collection_id = ?
 """;
 try (var statement = connection.prepareStatement(sql)) {
 statement.setObject(1, collectionId);
 try (var resultSet = statement.executeQuery()) {
 return mapResultSetToList(resultSet);
 }
 }
 }

 private List<AudiobookFile> mapResultSetToAudiobookFiles(ResultSet rs) throws SQLException {
 List<AudiobookFile> files = new ArrayList<>();
 while (rs.next()) {
 AudiobookFile file = new AudiobookFile();
 file.setId((UUID) rs.getObject("id"));
 file.setAudiobookId((UUID) rs.getObject("audiobook_id"));
 file.setFilePath(rs.getString("file_path"));
 file.setFormat(rs.getString("format") != null ? FileFormat.valueOf(rs.getString("format")) : null);
 file.setSize(rs.getInt("size"));
 files.add(file);
 }
 return files;
 }
