 560	 } catch (IllegalArgumentException e) {
 561	 throw new EntityMappingException("Невірний формат файлу: " + value, e);
 562	 }
 563	 } else {
 564	 throw new EntityMappingException("Неможливо конвертувати " + value.getClass().getName() + " в FileFormat");
 565	 }
 566	 }
