 90	 public void commit() {
 91	 // Перевірка стану з'єднання перед початком транзакції
 92	 checkConnection();
 93	
 94	 try {
 95	 // Збереження нових сутностей
 96	 for (Object entity : newEntities) {
 97	 Repository<Object, Object> repository = getRepository(entity.getClass());
 98	 repository.save(entity);
 99	 // Перевірка стану з'єднання після кожної операції
 100	 checkConnection();
 101	 }
 102	
 103	 // Оновлення сутностей
 104	 for (Map.Entry<Object, Object> entry : updatedEntities.entrySet()) {
 105	 Repository<Object, Object> repository = getRepository(entry.getValue().getClass());
 106	 repository.update(entry.getKey(), entry.getValue());
 107	 // Перевірка стану з'єднання після кожної операції
 108	 checkConnection();
 109	 }
 110	
 111	 // Видалення сутностей
 112	 for (Object entity : deletedEntities) {
 113	 Repository<Object, Object> repository = getRepository(entity.getClass());
 114	 Object id = repository.extractId(entity);
 115	 repository.delete(id);
 116	 // Перевірка стану з'єднання після кожної операції
 117	 checkConnection();
 118	 }
 119	
 120	 // Коміт транзакції
 121	 connection.commit();
 122	 } catch (SQLException e) {
 123	 try {
 124	 if (connection != null && !connection.isClosed()) {
 125	 connection.rollback();
 126	 } else {
 127	 // Якщо з'єднання закрите, створюємо нове для відкату
 128	 initializeConnection();
 129	 connection.rollback();
 130	 }
 131	 } catch (SQLException rollbackEx) {
 132	 throw new DatabaseAccessException("Помилка відкатування транзакції", rollbackEx);
 133	 }
 134	 throw new DatabaseAccessException("Помилка виконання транзакції", e);
 135	 } finally {
 136	 clear();
 137	 closeConnection();
 138	 }
 139	 }
