43e\u0440\u0430.\n *\n * @return \u043d\u043e\u0432\u0438\u0439 \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0430\u0432\u0442\u043e\u0440\u0430\n */\n public static AuthorId generate() {\n return new AuthorId(UUID.randomUUID());\n }\n\n /**\n * \u041f\u043e\u0432\u0435\u0440\u0442\u0430\u0454 \u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\u0430 \u044f\u043a UUID.\n *\n * @return \u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044f UUID\n */\n public UUID getValue() {\n return value;\n }\n\n @Override\n public boolean equals(Object o) {\n if (this == o) return true;\n if (o == null || getClass() != o.getClass()) return false;\n AuthorId authorId = (AuthorId) o;\n return Objects.equals(value, authorId.value);\n }\n\n @Override\n public int hashCode() {\n return Objects.hash(value);\n }\n\n @Override\n public String toString() {\n return value.toString();\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"### 3. Create Domain Identifiers as Value Objects
