 17	/**
 18	 * Реалізація патерну Unit of Work для управління транзакціями та змінами сутностей.
 19	 * Відстежує створені, оновлені та видалені сутності, застосовуючи зміни в одній транзакції.
 20	 */
 21	@Component
 22	public class PersistenceContext {
 23	
 24	 private final ConnectionPool connectionPool;
 25	 private final AudiobookRepository audiobookRepository;
 26	 private final AudiobookFileRepository audiobookFileRepository;
 27	 private final AuthorRepository authorRepository;
 28	 private final GenreRepository genreRepository;
 29	 private final CollectionRepository collectionRepository;
 30	 private final ListeningProgressRepository listeningProgressRepository;
 31	 private final UserRepository userRepository;
 32	 private Connection connection;
 33	 private final Map<Class<?>, Repository<?, ?>> repositories;
 34	 private final List<Object> newEntities;
 35	 private final Map<Object, Object> updatedEntities; // Map<Id, Entity>
 36	 private final List<Object> deletedEntities;
 37	
 38	 /**
 39	 * Конструктор для створення контексту з пулом з'єднань.
 40	 *
 41	 * @param connectionPool пул з'єднань для управління з'єднаннями
 42	 */
 43	 public PersistenceContext(ConnectionPool connectionPool,
 44	 AudiobookRepository audiobookRepository,
 45	 AudiobookFileRepository audiobookFileRepository,
 46	 AuthorRepository authorRepository,
 47	 GenreRepository genreRepository,
 48	 CollectionRepository collectionRepository,
 49	 ListeningProgressRepository listeningProgressRepository,
 50	 UserRepository userRepository) {
 51	 this.connectionPool = connectionPool;
 52	
 53	 this.audiobookRepository = audiobookRepository;
 54	 this.audiobookFileRepository = audiobookFileRepository;
 55	 this.authorRepository = authorRepository;
 56	 this.genreRepository = genreRepository;
 57	 this.collectionRepository = collectionRepository;
 58	 this.listeningProgressRepository = listeningProgressRepository;
 59	 this.userRepository = userRepository;
 60	
 61	 this.repositories = new HashMap<>();
 62	 this.newEntities = new ArrayList<>();
 63	 this.updatedEntities = new HashMap<>();
 64	 this.deletedEntities = new ArrayList<>();
 65	 initializeConnection();
 66	 }
 67	
 68	 @PostConstruct
 69	 private void init() {
 70	 this.registerRepository(Audiobook.class, audiobookRepository);
 71	 this.registerRepository(AudiobookFile.class, audiobookFileRepository);
 72	 this.registerRepository(Author.class, authorRepository);
 73	 this.registerRepository(Genre.class, genreRepository);
 74	 this.registerRepository(Collection.class, collectionRepository);
 75	 this.registerRepository(ListeningProgress.class, listeningProgressRepository);
 76	 this.registerRepository(User.class, userRepository);
 77	 }
 78	
 79	 /**
 80	 * Реєстрація репозиторію для певного типу сутності.
 81	 *
 82	 * @param entityClass клас сутності
 83	 * @param repository репозиторій для роботи з сутністю
 84	 */
 85	 public <T, ID> void registerRepository(Class<T> entityClass, Repository<T, ID> repository) {
 86	 repositories.put(entityClass, repository);
 87	 }
 88	
 89	 /**
 90	 * Реєстрація нової сутності для збереження.
 91	 *
 92	 * @param entity сутність для створення
 93	 */
 94	 public void registerNew(Object entity) {
 95	 if (entity == null) {
 96	 throw new IllegalArgumentException("Сутність не може бути null");
 97	 }
 98	 newEntities.add(entity);
 99	 }
 100	
 101	 /**
 102	 * Реєстрація сутності для оновлення.
 103	 *
 104	 * @param id ідентифікатор сутності
 105	 * @param entity сутність з новими даними
 106	 */
 107	 public void registerUpdated(Object id, Object entity) {
 108	 if (id == null || entity == null) {
 109	 throw new IllegalArgumentException("Ідентифікатор або сутність не можуть бути null");
 110	 }
 111	 updatedEntities.put(id, entity);
 112	 }
 113	
 114	 /**
 115	 * Реєстрація сутності для видалення.
 116	 *
 117	 * @param entity сутність для видалення
 118	 */
 119	 public void registerDeleted(Object entity) {
 120	 if (entity == null) {
 121	 throw new IllegalArgumentException("Сутність не може бути null");
 122	 }
 123	 deletedEntities.add(entity);
 124	 }
 125	
 126	 /**
 127	 * Застосування всіх зареєстрованих змін у транзакції.
 128	 */
 129	 public void commit() {
 130	 try {
 131	 // Збереження нових сутностей
 132	 for (Object entity : newEntities) {
 133	 Repository<Object, Object> repository = getRepository(entity.getClass());
 134	 repository.save(entity);
 135	 }
 136	
 137	 // Оновлення сутностей
 138	 for (Map.Entry<Object, Object> entry : updatedEntities.entrySet()) {
