 21	 private static final String DML_SCRIPT_PATH = "db/dml_h2.sql";
 22	 private static final String CLEAR_SCRIPT_PATH = "db/ddl_clear_data_h2.sql";
 23	 private final ConnectionPool connectionPool;
 24	
 25	 /**
 26	 * Конструктор ініціалізатора.
 27	 *
 28	 * @param connectionPool пул з'єднань для управління з'єднаннями
 29	 */
 30	 public PersistenceInitializer(ConnectionPool connectionPool) {
 31	 this.connectionPool = connectionPool;
 32	 }
 33	
 34	 /**
 35	 * Ініціалізація бази даних: виконання DDL та DML скриптів.
 36	 */
 37	 public void init() {
 38	 init(true);
 39	 }
 40	
 41	 /**
 42	 * Ініціалізація бази даних: виконання DDL та DML скриптів.
 43	 */
 44	 public void init(boolean isRunDml) {
 45	 try (Connection connection = connectionPool.getConnection();
 46	 Statement statement = connection.createStatement()) {
 47	 connection.setAutoCommit(false);
 48	
 49	 // Очищаємо дані та ініціалізуємо в одній транзакції
 50	 if (Boolean.parseBoolean(System.getProperty("db.init.clean", "false"))) {
 51	 statement.execute(getSQL(CLEAR_SCRIPT_PATH));
 52	 }
 53	 statement.execute(getSQL(DDL_SCRIPT_PATH));
 54	 if (isRunDml) {
 55	 statement.execute(getSQL(DML_SCRIPT_PATH));
 56	 }
 57	 connection.commit();
 58	 } catch (SQLException e) {
 59	 throw new DatabaseAccessException("Помилка ініціалізації бази даних", e);
 60	 }
 61	 }
 62	
 63	 /**
 64	 * Очищення всіх даних у базі без видалення структури.
 65	 */
 66	 public void clearData() {
 67	 try (Connection connection = connectionPool.getConnection();
 68	 Statement statement = connection.createStatement()) {
 69	 connection.setAutoCommit(false);
 70	
 71	 statement.execute(getSQL(CLEAR_SCRIPT_PATH));
 72	 connection.commit();
 73	 } catch (SQLException e) {
 74	 throw new DatabaseAccessException("Помилка очищення даних у базі", e);
 75	 }
 76	 }
 77	
 78	 /**
 79	 * Зчитування SQL-скрипту з ресурсів.
 80	 *
 81	 * @param resourcePath шлях до SQL-файлу в ресурсах
 82	 * @return вміст SQL-скрипту
 83	 */
 84	 private String getSQL(String resourcePath) {
 85	 try (BufferedReader reader = new BufferedReader(
 86	 new InputStreamReader(
 87	 Objects.requireNonNull(
 88	 PersistenceInitializer.class.getClassLoader().getResourceAsStream(resourcePath))))) {
 89	 return reader.lines().collect(Collectors.joining("\n"));
 90	 } catch (Exception e) {
 91	 throw new DatabaseAccessException("Помилка зчитування SQL-скрипту: " + resourcePath, e);
 92	 }
 93	 }
 94	}
