 38	 /**
 39	 * Створює новий жанр.
 40	 *
 41	 * @param genre жанр для створення
 42	 * @return створений жанр
 43	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 44	 * @throws ValidationException якщо порушено бізнес-правила (наприклад, дублювання жанру)
 45	 */
 46	 @Override
 47	 public Genre create(Genre genre) {
 48	 validateGenre(genre);
 49	 if (genre.getId() == null) {
 50	 genre.setId(UUID.randomUUID());
 51	 }
 52	
 53	 // Перевірка на дублювання жанру
 54	 if (genreRepository.existsByName(genre.getName())) {
 55	 throw new ValidationException("Жанр з назвою '" + genre.getName() + "' уже існує.");
 56	 }
 57	
 58	 persistenceContext.registerNew(genre);
 59	 persistenceContext.commit();
 60	 return genre;
 61	 }
