 47	 @Override
 48	 public List<Audiobook> findAudiobooksByGenreId(UUID genreId) {
 49	 String baseSql = "SELECT * FROM audiobooks WHERE genre_id = ?";
 50	 return executeQuery(baseSql, stmt -> stmt.setObject(1, genreId), this::mapResultSetToAudiobook);
 51	 }
