 151	 private AudiobookFile mapResultSetToAudiobookFiles(ResultSet rs) {
 152	 try {
 153	 AudiobookFile file = new AudiobookFile();
 154	 file.setId(rs.getObject("id", UUID.class));
 155	 file.setAudiobookId(rs.getObject("audiobook_id", UUID.class));
 156	 file.setFilePath(rs.getString("file_path"));
 157	 String format = rs.getString("format");
 158	 file.setFormat(format != null ? FileFormat.valueOf(format) : null);
 159	 file.setSize(rs.getInt("size"));
 160	 return file;
 161	 } catch (Exception e) {
 162	 throw new EntityMappingException("Помилка зіставлення ResultSet із файлом аудіокниги", e);
 163	 }
