Path: src/main/java/com/arakviel/infrastructure/persistence/util/ConnectionPool.java
 1	package com.arakviel.infrastructure.persistence.util;
 2	
 3	import java.lang.reflect.Proxy;
 4	import java.sql.Connection;
 5	import java.sql.DriverManager;
 6	import java.sql.SQLException;
 7	import java.util.Properties;
 8	import java.util.concurrent.ArrayBlockingQueue;
 9	import java.util.concurrent.BlockingQueue;
 10	import java.util.concurrent.atomic.AtomicBoolean;
 11	
 12	/**
 13	 * Пул з'єднань для управління JDBC-з'єднаннями з H2 базою даних.
 14	 * Використовує Proxy для перевизначення close, повертаючи з'єднання в пул.
 15	 */
 16	public class ConnectionPool {
 17	 private final BlockingQueue<Connection> availableConnections;
 18	 private final String url;
 19	 private final String user;
 20	 private final String password;
 21	 private final int maxConnections;
 22	 private final boolean autoCommit;
 23	 private final AtomicBoolean isInitialized = new AtomicBoolean(false);
 24	
 25	 public ConnectionPool(PoolConfig config) {
 26	 this.url = config.url;
 27	 this.user = config.user;
 28	 this.password = config.password;
 29	 this.maxConnections = config.maxConnections;
 30	 this.autoCommit = config.autoCommit;
 31	 this.availableConnections = new ArrayBlockingQueue<>(maxConnections);
 32	 initializePool();
 33	 }
 34	
 35	 private void initializePool() {
 36	 if (isInitialized.compareAndSet(false, true)) {
 37	 for (int i = 0; i < maxConnections; i++) {
 38	 try {
 39	 availableConnections.add(createProxyConnection());
 40	 } catch (SQLException e) {
 41	 throw new RuntimeException("Помилка ініціалізації пулу з'єднань", e);
 42	 }
 43	 }
 44	 }
 45	 }
 46	
 47	 private Connection createProxyConnection() throws SQLException {
 48	 Connection connection = DriverManager.getConnection(url, user, password);
 49	 connection.setAutoCommit(autoCommit);
 50	 return (Connection) Proxy.newProxyInstance(
 51	 ConnectionPool.class.getClassLoader(),
 52	 new Class[]{Connection.class},
 53	 (proxy, method, args) -> {
 54	 if ("close".equals(method.getName())) {
 55	 try {
 56	 connection.setAutoCommit(autoCommit);
 57	 } catch (SQLException e) {
 58	 throw new RuntimeException("Не вдалось встановити autoCommit", e);
 59	 }
 60	 availableConnections.offer((Connection) proxy);
 61	 return null;
 62	 }
 63	 return method.invoke(connection, args);
 64	 });
 65	 }
 66	
 67	 public Connection getConnection() {
 68	 try {
 69	 Connection connection = availableConnections.take();
 70	 if (connection.isClosed()) {
 71	 Connection newConnection = createProxyConnection();
 72	 availableConnections.offer(newConnection);
 73	 return newConnection;
 74	 }
 75	 return connection;
 76	 } catch (InterruptedException e) {
 77	 Thread.currentThread().interrupt();
 78	 throw new RuntimeException("Перервано очікування з'єднання", e);
 79	 } catch (SQLException e) {
 80	 throw new RuntimeException("Помилка отримання з'єднання", e);
 81	 }
 82	 }
 83	
 84	 public void shutdown() {
 85	 try {
 86	 for (Connection connection : availableConnections) {
 87	 if (!connection.isClosed()) {
 88	 connection.unwrap(Connection.class).close();
 89	 }
 90	 }
 91	 availableConnections.clear();
 92	 isInitialized.set(false);
 93	 } catch (SQLException e) {
 94	 throw new RuntimeException("Помилка закриття пулу з'єднань", e);
 95	 }
 96	 }
 97	
 98	 public static class PoolConfig {
 99	 private static final String DEFAULT_URL = "jdbc:h2:~/audiobooks;MODE=PostgreSQL";
 100	 private static final String DEFAULT_USER = "sa";
 101	 private static final String DEFAULT_PASSWORD = "";
 102	 private static final int DEFAULT_MAX_CONNECTIONS = 5;
 103	 private static final boolean DEFAULT_AUTO_COMMIT = true;
 104	
 105	 private final String url;
 106	 private final String user;
 107	 private final String password;
 108	 private final int maxConnections;
 109	 private final boolean autoCommit;
 110	
 111	 private PoolConfig(Builder builder) {
 112	 this.url = builder.url;
 113	 this.user = builder.user;
 114	 this.password = builder.password;
 115	 this.maxConnections = builder.maxConnections;
 116	 this.autoCommit = builder.autoCommit;
 117	 }
 118	
 119	 public static PoolConfig fromProperties(Properties properties) {
 120	 return new Builder()
 121	 .withUrl(properties.getProperty("db.url", DEFAULT_URL))
 122	 .withUser(properties.getProperty("db.username", DEFAULT_USER))
 123	 .withPassword(properties.getProperty("db.password", DEFAULT_PASSWORD))
 124	 .withMaxConnections(Integer.parseInt(properties.getProperty("db.pool.size", String.valueOf(DEFAULT_MAX_CONNECTIONS))))
 125	 .withAutoCommit(Boolean.parseBoolean(properties.getProperty("db.auto.commit", String.valueOf(DEFAULT_AUTO_COMMIT))))
 126	 .build();
 127	 }
 128	
 129	 public static class Builder {
 130	 private String url = DEFAULT_URL;
 131	 private String user = DEFAULT_USER;
 132	 private String password = DEFAULT_PASSWORD;
 133	 private int maxConnections = DEFAULT_MAX_CONNECTIONS;
 134	 private boolean autoCommit = DEFAULT_AUTO_COMMIT;
 135	
 136	 public Builder withUrl(String url) {
 137	 this.url = url;
 138	 return this;
