 124	
 125	 /**
 126	 * Застосування всіх зареєстрованих змін у транзакції.
 127	 */
 128	 public void commit() {
 129	 try {
 130	 // Збереження нових сутностей
 131	 for (Object entity : newEntities) {
 132	 Repository<Object, Object> repository = getRepository(entity.getClass());
 133	 System.out.println("Saving entity: " + entity); // Логування
 134	 repository.save(entity);
 135	 }
 136	
 137	 // Оновлення сутностей
 138	 for (Map.Entry<Object, Object> entry : updatedEntities.entrySet()) {
 139	 Repository<Object, Object> repository = getRepository(entry.getValue().getClass());
 140	 repository.update(entry.getKey(), entry.getValue());
 141	 }
 142	
 143	 // Видалення сутностей
 144	 for (Object entity : deletedEntities) {
 145	 Repository<Object, Object> repository = getRepository(entity.getClass());
 146	 Object id = repository.extractId(entity);
 147	 repository.delete(id);
 148	 }
 149	
 150	 // Коміт транзакції
 151	 connection.commit();
 152	 } catch (SQLException e) {
 153	 try {
 154	 connection.rollback();
 155	 } catch (SQLException rollbackEx) {
 156	 throw new DatabaseAccessException("Помилка відкатування транзакції", rollbackEx);
 157	 }
 158	 throw new DatabaseAccessException("Помилка виконання транзакції", e);
 159	 } finally {
 160	 clear();
 161	 try {
 162	 connection.close(); // Закриваємо з'єднання для повернення в пул
 163	 } catch (SQLException e) {
 164	 throw new DatabaseAccessException("Помилка закриття з'єднання", e);
 165	 }
 166	 }
 167	 }
 168	
 169	 /**
 170	 * Очищення списків змінених сутностей.
 171	 */
 172	 private void clear() {
 173	 newEntities.clear();
 174	 updatedEntities.clear();
 175	 deletedEntities.clear();
 176	 }
 177	
 178	 /**
 179	 * Ініціалізація з'єднання з пулом.
 180	 */
 181	 private void initializeConnection() {
 182	 try {
 183	 if (connection != null && !connection.isClosed()) {
 184	 connection.close(); // Закриваємо старе з'єднання
 185	 }
 186	 this.connection = connectionPool.getConnection();
 187	 this.connection.setAutoCommit(false); // Вимикаємо автокоміт для транзакцій
 188	 } catch (SQLException e) {
 189	 throw new DatabaseAccessException("Помилка ініціалізації з'єднання", e);
 190	 }
 191	 }
