## Аналіз Domain моделі

**Основні сутності:**
1. **User** - користувач системи
2. **Author** - автор аудіокниги 
3. **Genre** - жанр аудіокниги
4. **Audiobook** - аудіокнига
5. **AudiobookFile** - файл аудіокниги
6. **Collection** - колекція аудіокниг користувача
7. **ListeningProgress** - прогрес прослуховування

**Існуючі сервіси:**
- ✅ AuthorService
- ✅ GenreService 
- ✅ AudiobookService (частково)

**Потрібно реалізувати:**
- UserService
- CollectionService
- ListeningProgressService
- AudiobookFileService (окремо від AudiobookService)

Давайте створимо план та реалізуємо всі недостаючі сервіси:

## План реалізації сервісів

1. **UserService** - управління користувачами
2. **CollectionService** - управління колекціями аудіокниг
3. **ListeningProgressService** - відстеження прогресу прослуховування
4. **AudiobookFileService** - управління файлами аудіокниг

Почнемо з реалізації:

### 1. UserService
","workspace_file_chunks":[]},{"status":"success","request_id":"a4e2c396-d134-4796-8ef3-ce87b97ccd20","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01GSTgbL8tTJTACKiFj3N2cP","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "src/main/java/com/arakviel/application/impl/UserServiceImpl.java", "file_content": "package com.arakviel.application.impl;\n\nimport com.arakviel.application.contract.UserService;\nimport com.arakviel.application.exception.ValidationException;\nimport com.arakviel.domain.entities.Collection;\nimport com.arakviel.domain.entities.ListeningProgress;\nimport com.arakviel.domain.entities.User;\nimport com.arakviel.infrastructure.file.FileStorageService;\nimport com.arakviel.infrastructure.persistence.PersistenceContext;\nimport com.arakviel.infrastructure.persistence.contract.CollectionRepository;\nimport com.arakviel.infrastructure.persistence.contract.ListeningProgressRepository;\nimport com.arakviel.infrastructure.persistence.contract.UserRepository;\nimport org.springframework.stereotype.Service;\n\nimport java.io.InputStream;\nimport java.nio.file.Path;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/**\n * \u0420\u0435\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f \u0441\u0435\u0440\u0432\u0456\u0441\u0443 \u0434\u043b\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u0456\u043d\u043d\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\u043c\u0438.\n */\n@Service\npublic class UserServiceImpl implements UserService {\n\n private final UserRepository userRepository;\n private final CollectionRepository collectionRepository;\n private final ListeningProgressRepository listeningProgressRepository;\n private final PersistenceContext persistenceContext;\n private final FileStorageService fileStorageService;\n\n public UserServiceImpl(UserRepository userRepository,\n CollectionRepository collectionRepository,\n ListeningProgressRepository listeningProgressRepository,\n PersistenceContext persistenceContext,\n FileStorageService fileStorageService) {\n this.userRepository = userRepository;\n this.collectionRepository = collectionRepository;\n this.listeningProgressRepository = listeningProgressRepository;\n this.persistenceContext = persistenceContext;\n this.fileStorageService = fileStorageService;\n }\n\n /**\n * \u0421\u0442\u0432\u043e\u0440\u044e\u0454 \u043d\u043e\u0432\u043e\u0433\u043e \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0442\u0430, \u0437\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0438, \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0443\u0454 \u0430\u0432\u0430\u0442\u0430\u0440.\n */\n @Override\n public User create(User user, InputStream avatar, String avatarName) {\n validateUser(user);\n if (user.getId() == null) {\n user.setId(UUID.randomUUID());\n }\n\n // \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u043a\u0430 \u043d\u0430 \u0434\u0443\u0431\u043b\u044e\u0432\u0430\u043d\u043d\u044f username\n if (existsByUsername(user.getUsername())) {\n throw new ValidationException(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u0437 \u0442\u0430\u043a\u0438\u043c \u0456\u043c'\u044f\u043c \u0443\u0436\u0435 \u0456\u0441\u043d\u0443\u0454: \" + user.getUsername());\n }\n\n // \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u043a\u0430 \u043d\u0430 \u0434\u0443\u0431\u043b\u044e\u0432\u0430\u043d\u043d\u044f email\n if (existsByEmail(user.getEmail())) {\n throw new ValidationException(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u0437 \u0442\u0430\u043a\u0438\u043c email \u0443\u0436\u0435 \u0456\u0441\u043d\u0443\u0454: \" + user.getEmail());\n }\n\n // \u0425\u0435\u0448\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u0430\u0440\u043e\u043b\u044f\n user.setPasswordHash(hashPassword(user.getPasswordHash()));\n\n // \u041e\u0431\u0440\u043e\u0431\u043a\u0430 \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f \u0430\u0432\u0430\u0442\u0430\u0440\u0430\n if (avatar != null && avatarName != null) {\n Path avatarPath = fileStorageService.save(avatar, avatarName, user.getId());\n user.setAvatarPath(avatarPath.toString());\n }\n\n persistenceContext.registerNew(user);\n persistenceContext.commit();\n return user;\n }\n\n /**\n * \u041e\u043d\u043e\u0432\u043b\u044e\u0454 \u0456\u0441\u043d\u0443\u044e\u0447\u043e\u0433\u043e \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0442\u0430, \u0437\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0438, \u043e\u043d\u043e\u0432\u043b\u044e\u0454 \u0430\u0432\u0430\u0442\u0430\u0440.\n */\n @Override\n public User update(UUID id, User user, InputStream avatar, String avatarName) {\n validateUser(user);\n user.setId(id);\n\n // \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u043a\u0430 \u0456\u0441\u043d\u0443\u0432\u0430\u043d\u043d\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n Optional<User> existingUserOpt = userRepository.findById(id);\n if (!existingUserOpt.isPresent()) {\n throw new ValidationException(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u0437 \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\u043e\u043c \" + id + \" \u043d\u0435 \u0456\u0441\u043d\u0443\u0454.\");\n }\n\n User existingUser = existingUserOpt.get();\n\n // \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u043a\u0430 \u043d\u0430 \u0434\u0443\u0431\u043b\u044e\u0432\u0430\u043d\u043d\u044f username (\u044f\u043a\u0449\u043e \u0437\u043c\u0456\u043d\u044e\u0454\u0442\u044c\u0441\u044f)\n if (!existingUser.getUsername().equals(user.getUsername()) && existsByUsername(user.getUsername())) {\n throw new ValidationException(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u0437 \u0442\u0430\u043a\u0438\u043c \u0456\u043c'\u044f\u043c \u0443\u0436\u0435 \u0456\u0441\u043d\u0443\u0454: \" + user.getUsername());\n }\n\n // \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u043a\u0430 \u043d\u0430 \u0434\u0443\u0431\u043b\u044e\u0432\u0430\u043d\u043d\u044f email (\u044f\u043a\u0449\u043e \u0437\u043c\u0456\u043d\u044e\u0454\u0442\u044c\u0441\u044f)\n if (!existingUser.getEmail().equals(user.getEmail()) && existsByEmail(user.getEmail())) {\n throw new ValidationException(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u0437 \u0442\u0430\u043a\u0438\u043c email \u0443\u0436\u0435 \u0456\u0441\u043d\u0443\u0454: \" + user.getEmail());\n }\n\n // \u0425\u0435\u0448\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u0430\u0440\u043e\u043b\u044f, \u044f\u043a\u0449\u043e \u0432\u0456\u043d \u0437\u043c\u0456\u043d\u0438\u0432\u0441\u044f\n if (!user.getPasswordHash().equals(existingUser.getPasswordHash())) {\n user.setPasswordHash(hashPassword(user.getPasswordHash()));\n }\n\n // \u041e\u0431\u0440\u043e\u0431\u043a\u0430 \u0456\u0441\u043d\u0443\u044e\u0447\u043e\u0433\u043e \u0430\u0432\u0430\u0442\u0430\u0440\u0430\n if (existingUser.getAvatarPath() != null && avatar != null && avatarName != null) {\n String fileName = Path.of(existingUser.getAvatarPath()).getFileName().toString();\n fileStorageService.delete(fileName, id);\n }\n\n // \u041e\u0431\u0440\u043e\u0431\u043a\u0430 \u043d\u043e\u0432\u043e\u0433\u043e \u0430\u0432\u0430\u0442\u0430\u0440\u0430\n if (avatar != null && avatarName != null) {\n Path avatarPath = fileStorageService.save(avatar, avatarName, id);\n user.setAvatarPath(avatarPath.toString());\n } else if (existingUser.getAvatarPath() != null) {\n user.setAvatarPath(existingUser.getAvatarPath());\n }\n\n persistenceContext.registerUpdated(id, user);\n persistenceContext.commit();\n return user;\n }\n\n /**\n * \u0412\u0438\u0434\u0430\u043b\u044f\u0454 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0442\u0430 \u043f\u043e\u0432'\u044f\u0437\u0430\u043d\u0438\u0439 \u0430\u0432\u0430\u0442\u0430\u0440.\n */\n @Override\n public void delete(UUID id) {\n Optional<User> userOpt = userRepository.findById(id);\n if (userOpt.isPresent()) {\n User user = userOpt.get();\n\n // \u0412\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u0430\u0432\u0430\u0442\u0430\u0440\u0430\n if (user.getAvatarPath() != null) {\n String fileName = Path.of(user.getAvatarPath()).getFileName().toString();\n fileStorageService.delete(fileName, id);\n }\n\n persistenceContext.registerDeleted(user);\n persistenceContext.commit();\n }\n }\n\n @Override\n public Optional<User> findById(UUID id) {\n return userRepository.findById(id);\n }\n\n @Override\n public List<User> findAll(int offset, int limit) {\n validatePagination(offset, limit);\n return userRepository.findAll(offset, limit);\n }\n\n @Override\n public List<User> findByUsername(String username) {\n if (username == null || username.trim().isEmpty()) {\n throw new ValidationException(\"Username \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n return userRepository.findByUsername(username);\n }\n\n @Override\n public List<User> findByEmail(String email) {\n if (email == null || email.trim().isEmpty()) {\n throw new ValidationException(\"Email \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n return userRepository.findByEmail(email);\n }\n\n @Override\n public boolean existsByUsername(String username) {\n return userRepository.existsByUsername(username);\n }\n\n @Override\n public boolean existsByEmail(String email) {\n return userRepository.existsByEmail(email);\n }\n\n @Override\n public List<Collection> findCollectionsByUserId(UUID userId) {\n if (userId == null) {\n throw new ValidationException(\"\u0406\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 null.\");\n }\n return collectionRepository.findByUserId(userId);\n }\n\n @Override\n public List<ListeningProgress> findListeningProgressByUserId(UUID userId) {\n if (userId == null) {\n throw new ValidationException(\"\u0406\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 null.\");\n }\n return listeningProgressRepository.findByUserId(userId);\n }\n\n @Override\n public long countCollectionsByUserId(UUID userId) {\n if (userId == null) {\n throw new ValidationException(\"\u0406\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 null.\");\n }\n return collectionRepository.countByUserId(userId);\n }\n\n @Override\n public long countListeningProgressByUserId(UUID userId) {\n if (userId == null) {\n throw new ValidationException(\"\u0406\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 null.\");\n }\n return listeningProgressRepository.countByUserId(userId);\n }\n\n @Override\n public void changePassword(UUID userId, String oldPassword, String newPassword) {\n if (userId == null) {\n throw new ValidationException(\"\u0406\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 null.\");\n }\n if (oldPassword == null || oldPassword.trim().isEmpty()) {\n throw new ValidationException(\"\u0421\u0442\u0430\u0440\u0438\u0439 \u043f\u0430\u0440\u043e\u043b\u044c \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n if (newPassword == null || newPassword.trim().isEmpty()) {\n throw new ValidationException(\"\u041d\u043e\u0432\u0438\u0439 \u043f\u0430\u0440\u043e\u043b\u044c \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n\n Optional<User> userOpt = userRepository.findById(userId);\n if (!userOpt.isPresent()) {\n throw new ValidationException(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u043d\u0435 \u0437\u043d\u0430\u0439\u0434\u0435\u043d\u0438\u0439.\");\n }\n\n User user = userOpt.get();\n String hashedOldPassword = hashPassword(oldPassword);\n \n if (!user.getPasswordHash().equals(hashedOldPassword)) {\n throw new ValidationException(\"\u041d\u0435\u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u0438\u0439 \u0441\u0442\u0430\u0440\u0438\u0439 \u043f\u0430\u0440\u043e\u043b\u044c.\");\n }\n\n user.setPasswordHash(hashPassword(newPassword));\n persistenceContext.registerUpdated(userId, user);\n persistenceContext.commit();\n }\n\n @Override\n public Optional<User> authenticate(String username, String password) {\n if (username == null || username.trim().isEmpty()) {\n throw new ValidationException(\"Username \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n if (password == null || password.trim().isEmpty()) {\n throw new ValidationException(\"\u041f\u0430\u0440\u043e\u043b\u044c \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n\n List<User> users = findByUsername(username);\n if (users.isEmpty()) {\n return Optional.empty();\n }\n\n User user = users.get(0);\n String hashedPassword = hashPassword(password);\n \n if (user.getPasswordHash().equals(hashedPassword)) {\n return Optional.of(user);\n }\n \n return Optional.empty();\n }\n\n /**\n * \u0412\u0430\u043b\u0456\u0434\u0443\u0454 \u0434\u0430\u043d\u0456 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430.\n */\n private void validateUser(User user) {\n if (user == null) {\n throw new ValidationException(\"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 null.\");\n }\n if (user.getUsername() == null || user.getUsername().trim().isEmpty()) {\n throw new ValidationException(\"Username \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n if (user.getPasswordHash() == null || user.getPasswordHash().trim().isEmpty()) {\n throw new ValidationException(\"\u041f\u0430\u0440\u043e\u043b\u044c \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n if (user.getEmail() == null || user.getEmail().trim().isEmpty()) {\n throw new ValidationException(\"Email \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c.\");\n }\n if (!isValidEmail(user.getEmail())) {\n throw new ValidationException(\"\u041d\u0435\u043a\u043e\u0440\u0435\u043a\u0442\u043d\u0438\u0439 \u0444\u043e\u0440\u043c\u0430\u0442 email.\");\n }\n }\n\n /**\n * \u0412\u0430\u043b\u0456\u0434\u0443\u0454 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438 \u043f\u0430\u0433\u0456\u043d\u0430\u0446\u0456\u0457.\n */\n private void validatePagination(int offset, int limit) {\n if (offset < 0) {\n throw new ValidationException(\"Offset \u043d\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0456\u0434'\u0454\u043c\u043d\u0438\u043c.\");\n }\n if (limit <= 0) {\n throw new ValidationException(\"Limit \u043f\u043e\u0432\u0438\u043d\u0435\u043d \u0431\u0443\u0442\u0438 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0443\u043b\u044f.\");\n }\n }\n\n /**\n * \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0454 \u0432\u0430\u043b\u0456\u0434\u043d\u0456\u0441\u0442\u044c email.\n */\n private boolean isValidEmail(String email) {\n return email.contains(\"@\") && email.contains(\".\");\n }\n\n /**\n * \u0425\u0435\u0448\u0443\u0454 \u043f\u0430\u0440\u043e\u043b\u044c \u0437\u0430 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u043e\u044e SHA-256.\n */\n private String hashPassword(String password) {\n try {\n MessageDigest digest = MessageDigest.getInstance(\"SHA-256\");\n byte[] hash = digest.digest(password.getBytes());\n StringBuilder hexString = new StringBuilder();\n for (byte b : hash) {\n String hex = Integer.toHexString(0xff & b);\n if (hex.length() == 1) {\n hexString.append('0');\n }\n hexString.append(hex);\n }\n return hexString.toString();\n } catch (NoSuchAlgorithmException e) {\n throw new RuntimeException(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430 \u0445\u0435\u0448\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u0430\u0440\u043e\u043b\u044f\", e);\n }\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":""},{"id":2,"type":2,"content":""},{"id":3,"type":3,"content":""}],"seen_state":"seen","structured_request_nodes":[{"id":1,"type":1,"tool_result_node":{"content":"File saved. Saved file {src/main/java/com/arakviel/application/contract/UserService.java}","is_error":false,"request_id":"","tool_use_id":"toolu_01NdozFbiAtor4aucPtSTdQu"}},{"id":2,"type":4,"ide_state_node":{"workspaceFolders":[{"repositoryRoot":"/home/arakviel/Projects/JavaProjects","folderRoot":"/home/arakviel/Projects/JavaProjects"}],"workspaceFoldersUnchanged":false}}],"timestamp":"2025-06-30T20:51:43.199Z","response_text":"","workspace_file_chunks":[]},{"status":"success","request_id":"145bcc9c-a986-4d76-bcce-1cd6c4c8c3c3","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01GUVJSB9yskpozeAB8HK1fH","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "src/main/java/com/arakviel/application/contract/CollectionService.java", "file_content": "package com.arakviel.application.contract;\n\nimport com.arakviel.application.exception.ValidationException;\nimport com.arakviel.domain.entities.Audiobook;\nimport com.arakviel.domain.entities.Collection;\nimport com.arakviel.infrastructure.persistence.exception.DatabaseAccessException;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/**\n * \u0406\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441 \u0434\u043b\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u0456\u043d\u043d\u044f \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f\u043c\u0438 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0456\u0432.\n */\npublic interface CollectionService {\n\n /**\n * \u0421\u0442\u0432\u043e\u0440\u044e\u0454 \u043d\u043e\u0432\u0443 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044e \u0434\u043b\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430.\n *\n * @param collection \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f \u0434\u043b\u044f \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f\n * @return \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u0430 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f\n * @throws DatabaseAccessException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n * @throws ValidationException \u044f\u043a\u0449\u043e \u043f\u043e\u0440\u0443\u0448\u0435\u043d\u043e \u0431\u0456\u0437\u043d\u0435\u0441-\u043f\u0440\u0430\u0432\u0438\u043b\u0430 (\u043d\u0430\u043f\u0440\u0438\u043a\u043b\u0430\u0434, \u0434\u0443\u0431\u043b\u044e\u0432\u0430\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0438 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0434\u043b\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430)\n */\n Collection create(Collection collection);\n\n /**\n * \u041e\u043d\u043e\u0432\u043b\u044e\u0454 \u0456\u0441\u043d\u0443\u044e\u0447\u0443 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044e.\n *\n * @param id \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0434\u043b\u044f \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f\n * @param collection \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u0456 \u0434\u0430\u043d\u0456 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u0430 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f\n * @throws DatabaseAccessException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n * @throws ValidationException \u044f\u043a\u0449\u043e \u043f\u043e\u0440\u0443\u0448\u0435\u043d\u043e \u0431\u0456\u0437\u043d\u0435\u0441-\u043f\u0440\u0430\u0432\u0438\u043b\u0430\n */\n Collection update(UUID id, Collection collection);\n\n /**\n * \u0412\u0438\u0434\u0430\u043b\u044f\u0454 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044e \u0442\u0430 \u0432\u0441\u0456 \u043f\u043e\u0432'\u044f\u0437\u0430\u043d\u0456 \u0437 \u043d\u0435\u044e \u0437\u0432'\u044f\u0437\u043a\u0438 \u0437 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430\u043c\u0438.\n *\n * @param id \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0434\u043b\u044f \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f\n * @throws DatabaseAccessException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n */\n void delete(UUID id);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044e \u0437\u0430 \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\u043e\u043c.\n *\n * @param id \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return Optional \u0437 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0454\u044e, \u044f\u043a\u0449\u043e \u0437\u043d\u0430\u0439\u0434\u0435\u043d\u043e\n */\n Optional<Collection> findById(UUID id);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u0432\u0441\u0456 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0437 \u043f\u0430\u0433\u0456\u043d\u0430\u0446\u0456\u0454\u044e.\n *\n * @param offset \u0437\u043c\u0456\u0449\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u043f\u0430\u0433\u0456\u043d\u0430\u0446\u0456\u0457\n * @param limit \u043a\u0456\u043b\u044c\u043a\u0456\u0441\u0442\u044c \u0437\u0430\u043f\u0438\u0441\u0456\u0432 \u0434\u043b\u044f \u043e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439\n */\n List<Collection> findAll(int offset, int limit);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0437\u0430 \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\u043e\u043c \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430.\n *\n * @param userId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n */\n List<Collection> findByUserId(UUID userId);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0437\u0430 \u043d\u0430\u0437\u0432\u043e\u044e.\n *\n * @param name \u043d\u0430\u0437\u0432\u0430 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439\n */\n List<Collection> findByName(String name);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0437\u0430 \u0447\u0430\u0441\u0442\u043a\u043e\u0432\u043e\u044e \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u043d\u0456\u0441\u0442\u044e \u043d\u0430\u0437\u0432\u0438.\n *\n * @param partialName \u0447\u0430\u0441\u0442\u043a\u043e\u0432\u0430 \u043d\u0430\u0437\u0432\u0430 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439\n */\n List<Collection> findByPartialName(String partialName);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0432 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457.\n *\n * @param collectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433 \u0443 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n */\n List<Audiobook> findAudiobooksByCollectionId(UUID collectionId);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457, \u0449\u043e \u043c\u0456\u0441\u0442\u044f\u0442\u044c \u043f\u0435\u0432\u043d\u0443 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443.\n *\n * @param audiobookId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439\n */\n List<Collection> findByAudiobookId(UUID audiobookId);\n\n /**\n * \u0414\u043e\u0434\u0430\u0454 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443 \u0434\u043e \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457.\n *\n * @param collectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @param audiobookId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n * @throws DatabaseAccessException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n * @throws ValidationException \u044f\u043a\u0449\u043e \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430 \u0432\u0436\u0435 \u0454 \u0432 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0430\u0431\u043e \u043d\u0435 \u0456\u0441\u043d\u0443\u0454\n */\n void addAudiobookToCollection(UUID collectionId, UUID audiobookId);\n\n /**\n * \u0412\u0438\u0434\u0430\u043b\u044f\u0454 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443 \u0437 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457.\n *\n * @param collectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @param audiobookId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n * @throws DatabaseAccessException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n */\n void removeAudiobookFromCollection(UUID collectionId, UUID audiobookId);\n\n /**\n * \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0454, \u0447\u0438 \u043c\u0456\u0441\u0442\u0438\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f \u043f\u0435\u0432\u043d\u0443 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443.\n *\n * @param collectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @param audiobookId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n * @return true, \u044f\u043a\u0449\u043e \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0430 \u0454 \u0432 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n */\n boolean containsAudiobook(UUID collectionId, UUID audiobookId);\n\n /**\n * \u041f\u0456\u0434\u0440\u0430\u0445\u043e\u0432\u0443\u0454 \u043a\u0456\u043b\u044c\u043a\u0456\u0441\u0442\u044c \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433 \u0443 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457.\n *\n * @param collectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return \u043a\u0456\u043b\u044c\u043a\u0456\u0441\u0442\u044c \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\n */\n long countAudiobooksByCollectionId(UUID collectionId);\n\n /**\n * \u041f\u0456\u0434\u0440\u0430\u0445\u043e\u0432\u0443\u0454 \u043a\u0456\u043b\u044c\u043a\u0456\u0441\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430.\n *\n * @param userId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n * @return \u043a\u0456\u043b\u044c\u043a\u0456\u0441\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439\n */\n long countByUserId(UUID userId);\n\n /**\n * \u0417\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0437\u0430 \u043d\u0430\u0437\u0432\u043e\u044e.\n *\n * @param userId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n * @param name \u043d\u0430\u0437\u0432\u0430 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0439\n */\n List<Collection> findByUserIdAndName(UUID userId, String name);\n\n /**\n * \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0454, \u0447\u0438 \u0456\u0441\u043d\u0443\u0454 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f \u0437 \u0442\u0430\u043a\u043e\u044e \u043d\u0430\u0437\u0432\u043e\u044e \u0443 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430.\n *\n * @param userId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\n * @param name \u043d\u0430\u0437\u0432\u0430 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @return true, \u044f\u043a\u0449\u043e \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044f \u0456\u0441\u043d\u0443\u0454\n */\n boolean existsByUserIdAndName(UUID userId, String name);\n\n /**\n * \u041a\u043e\u043f\u0456\u044e\u0454 \u0432\u0441\u0456 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0437 \u043e\u0434\u043d\u0456\u0454\u0457 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u0432 \u0456\u043d\u0448\u0443.\n *\n * @param sourceCollectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0432\u0438\u0445\u0456\u0434\u043d\u043e\u0457 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @param destinationCollectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u0446\u0456\u043b\u044c\u043e\u0432\u043e\u0457 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @throws DatabaseAccessException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n * @throws ValidationException \u044f\u043a\u0449\u043e \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457 \u043d\u0435 \u0456\u0441\u043d\u0443\u044e\u0442\u044c \u0430\u0431\u043e \u043d\u0430\u043b\u0435\u0436\u0430\u0442\u044c \u0440\u0456\u0437\u043d\u0438\u043c \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\u043c\n */\n void copyAudiobooksToCollection(UUID sourceCollectionId, UUID destinationCollectionId);\n\n /**\n * \u041e\u0447\u0438\u0449\u0430\u0454 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u044e (\u0432\u0438\u0434\u0430\u043b\u044f\u0454 \u0432\u0441\u0456 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0437 \u043d\u0435\u0457).\n *\n * @param collectionId \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440 \u043a\u043e\u043b\u0435\u043a\u0446\u0456\u0457\n * @throws DatabaseAccessException \u044f\u043a\u0449\u043e \u0432\u0438\u043d\u0438\u043a\u0430\u0454 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u0440\u0438 \u0440\u043e\u0431\u043e\u0442\u0456 \u0437 \u0431\u0430\u0437\u043e\u044e \u0434\u0430\u043d\u0438\u0445\n */\n void clearCollection(UUID collectionId);\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"### 2. CollectionService
