 83	 * @param coverImage потік даних нової обкладинки, може бути null
 84	 * @param coverImageName ім'я файлу нової обкладинки, може бути null
 85	 * @return оновлена аудіокнига
 86	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 87	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 88	 */
 89	 @Override
 90	 public Audiobook update(UUID id, Audiobook audiobook, InputStream coverImage, String coverImageName) {
 91	 audiobook.setId(id);
 92	
 93	 // Обробка існуючої обкладинки
 94	 if (audiobook.getCoverImagePath() != null && coverImage != null && coverImageName != null) {
 95	 fileStorageService.delete(audiobook.getCoverImagePath(), id);
 96	 }
 97	
 98	 // Обробка нової обкладинки
 99	 if (coverImage != null && coverImageName != null) {
 100	 Path coverImagePath = fileStorageService.save(coverImage, coverImageName, id);
 101	 audiobook.setCoverImagePath(coverImagePath.toString());
 102	 }
 103	
 104	 persistenceContext.registerUpdated(id, audiobook);
 105	 persistenceContext.commit();
 106	 return audiobook;
 107	 }
