 113	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 114	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 115	 */
 116	 @Override
 117	 public void delete(UUID id) {
 118	 Optional<Audiobook> audiobookOpt = audiobookRepository.findById(id);
 119	 if (audiobookOpt.isPresent()) {
 120	 Audiobook audiobook = audiobookOpt.get();
 121	
 122	 // Видалення обкладинки
 123	 if (audiobook.getCoverImagePath() != null) {
 124	 fileStorageService.delete(audiobook.getCoverImagePath(), id);
 125	 }
 126	
 127	 // Видалення пов'язаних аудіофайлів
 128	 List<AudiobookFile> files = audiobookFileRepository.findByAudiobookId(id);
 129	 for (AudiobookFile file : files) {
 130	 fileStorageService.delete(file.getFilePath(), id);
 131	 persistenceContext.registerDeleted(file);
 132	 }
 133	
 134	 persistenceContext.registerDeleted(audiobook);
 135	 persistenceContext.commit();
 136	 }
 137	 }
