 20	/**
 21	 * Реалізація сервісу для управління сутностями авторів, включаючи операції з файлами фотографій та пов'язаними аудіокнигами.
 22	 */
 23	@Service
 24	public class AuthorServiceImpl implements AuthorService {
 25	
 26	 private final AuthorRepository authorRepository;
 27	 private final PersistenceContext persistenceContext;
 28	 private final FileStorageService fileStorageService;
 29	
 30	 /**
 31	 * Конструктор для ін'єкції залежностей.
 32	 *
 33	 * @param authorRepository репозиторій авторів
 34	 * @param persistenceContext контекст для управління транзакціями
 35	 * @param fileStorageService сервіс для роботи з файлами
 36	 */
 37	 public AuthorServiceImpl(
 38	 AuthorRepository authorRepository,
 39	 PersistenceContext persistenceContext,
 40	 FileStorageService fileStorageService) {
 41	 this.authorRepository = authorRepository;
 42	 this.persistenceContext = persistenceContext;
 43	 this.fileStorageService = fileStorageService;
 44	 }
 45	
 46	 /**
 47	 * Створює нового автора та, за потреби, завантажує фотографію.
 48	 *
 49	 * @param author автор для створення
 50	 * @param photo потік даних фотографії, може бути null
 51	 * @param photoName ім'я файлу фотографії, може бути null
 52	 * @return створений автор
 53	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 54	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 55	 * @throws ValidationException якщо порушено бізнес-правила (наприклад, дублювання автора)
 56	 */
 57	 @Override
 58	 public Author create(Author author, InputStream photo, String photoName) {
 59	 validateAuthor(author);
 60	 if (author.getId() == null) {
 61	 author.setId(UUID.randomUUID());
 62	 }
 63	
 64	 // Перевірка на дублювання автора
 65	 List<Author> existingAuthors = authorRepository.findByName(author.getFirstName(), author.getLastName());
 66	 if (!existingAuthors.isEmpty()) {
 67	 throw new ValidationException("Автор з таким ім'ям та прізвищем уже існує.");
 68	 }
 69	
 70	 // Обробка завантаження фотографії
 71	 if (photo != null && photoName != null) {
 72	 Path photoPath = fileStorageService.save(photo, photoName, author.getId());
 73	 author.setImagePath(photoPath.toString());
 74	 }
 75	
 76	 persistenceContext.registerNew(author);
 77	 persistenceContext.commit();
 78	 return author;
 79	 }
 80	
 81	 /**
 82	 * Оновлює існуючого автора та, за потреби, оновлює фотографію.
 83	 *
 84	 * @param id ідентифікатор автора для оновлення
 85	 * @param author оновлені дані автора
 86	 * @param photo потік даних нової фотографії, може бути null
 87	 * @param photoName ім'я файлу нової фотографії, може бути null
 88	 * @return оновлений автор
 89	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 90	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 91	 * @throws ValidationException якщо порушено бізнес-правила
 92	 */
 93	 @Override
 94	 public Author update(UUID id, Author author, InputStream photo, String photoName) {
 95	 validateAuthor(author);
 96	 author.setId(id);
 97	
 98	 // Перевірка існування автора
 99	 if (!authorRepository.findById(id).isPresent()) {
 100	 throw new ValidationException("Автор з ідентифікатором " + id + " не існує.");
 101	 }
 102	
 103	 // Обробка існуючої фотографії
 104	 if (author.getImagePath() != null && photo != null && photoName != null) {
 105	 fileStorageService.delete(author.getImagePath(), id);
 106	 }
 107	
 108	 // Обробка нової фотографії
 109	 if (photo != null && photoName != null) {
 110	 Path photoPath = fileStorageService.save(photo, photoName, id);
 111	 author.setImagePath(photoPath.toString());
 112	 }
 113	
 114	 persistenceContext.registerUpdated(id, author);
 115	 persistenceContext.commit();
 116	 return author;
 117	 }
 118	
 119	 /**
 120	 * Видаляє автора та пов'язану фотографію, якщо автор не пов'язаний з аудіокнигами.
 121	 *
 122	 * @param id ідентифікатор автора для видалення
 123	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 124	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 125	 * @throws ValidationException якщо автор пов'язаний з аудіокнигами
 126	 */
 127	 @Override
 128	 public void delete(UUID id) {
 129	 Optional<Author> authorOpt = authorRepository.findById(id);
 130	 if (authorOpt.isPresent()) {
 131	 Author author = authorOpt.get();
 132	
 133	 // Перевірка, чи автор пов'язаний з аудіокнигами
 134	 if (countAudiobooksByAuthorId(id) > 0) {
 135	 throw new ValidationException("Неможливо видалити автора, оскільки він пов'язаний з аудіокнигами.");
 136	 }
 137	
 138	 // Видалення фотографії
 139	 if (author.getImagePath() != null) {
 140	 fileStorageService.delete(author.getImagePath(), id);
 141	 }
 142	
 143	 persistenceContext.registerDeleted(author);
 144	 persistenceContext.commit();
 145	 }
 146	 }
 147	
 148	 /**
 149	 * Знаходить автора за ідентифікатором.
 150	 *
 151	 * @param id ідентифікатор автора
 152	 * @return Optional з автором, якщо знайдено
 153	 */
 154	 @Override
 155	 public Optional<Author> findById(UUID id) {
 156	 return authorRepository.findById(id);
 157	 }
 158	
 159	 /**
 160	 * Знаходить всіх авторів з пагінацією.
