 162	 * @param offset зміщення для пагінації
 163	 * @param limit кількість записів для отримання
 164	 * @return список авторів
 165	 */
 166	 @Override
 167	 public List<Author> findAll(int offset, int limit) {
 168	 return authorRepository.findAll(offset, limit);
 169	 }
