 1	package com.arakviel.infrastructure.file.impl;
 2	
 3	import com.arakviel.infrastructure.file.FileStorageService;
 4	import com.arakviel.infrastructure.file.exception.FileStorageException;
 5	
 6	import java.io.ByteArrayOutputStream;
 7	import java.io.IOException;
 8	import java.io.InputStream;
 9	import java.nio.file.Files;
 10	import java.nio.file.Path;
 11	import java.nio.file.Paths;
 12	import java.nio.file.StandardCopyOption;
 13	import java.util.Arrays;
 14	import java.util.HashSet;
 15	import java.util.Set;
 16	import java.util.UUID;
 17	
 18	/**
 19	 * Реалізація сервісу для роботи зі зберіганням файлів, зокрема зображень.
 20	 */
 21	public class FileStorageServiceImpl implements FileStorageService {
 22	
 23	 private final Path storageRoot;
 24	 private final Set<String> allowedExtensions;
 25	 private final long maxFileSize;
 26	
 27	 /**
 28	 * Конструктор із конфігурацією кореневої директорії та дозволених розширень.
 29	 *
 30	 * @param storageRootPath шлях до кореневої директорії для зберігання файлів
 31	 * @param allowedExtensions набір дозволених розширень файлів (наприклад, "jpg", "png")
 32	 * @param maxFileSize максимальний розмір файлу у байтах
 33	 */
 34	 public FileStorageServiceImpl(String storageRootPath, String[] allowedExtensions, long maxFileSize) {
 35	 this.storageRoot = Paths.get(storageRootPath).toAbsolutePath().normalize();
 36	 this.allowedExtensions = new HashSet<>(Arrays.asList(allowedExtensions));
 37	 this.maxFileSize = maxFileSize;
 38	 initializeStorage();
 39	 }
 40	
 41	 /**
 42	 * Ініціалізація директорії для зберігання файлів.
 43	 */
 44	 private void initializeStorage() {
 45	 try {
 46	 Files.createDirectories(storageRoot);
 47	 } catch (IOException e) {
 48	 throw new FileStorageException("Не вдалося ініціалізувати директорію для зберігання файлів: " + storageRoot, e);
 49	 }
 50	 }
 51	
 52	 /**
 53	 * Зберігає файл у вказаній директорії та повертає шлях до нього.
 54	 *
 55	 * @param inputStream потік даних файлу
 56	 * @param fileName ім’я файлу (з розширенням)
 57	 * @param entityId ідентифікатор сутності (наприклад, аудіокниги)
 58	 * @return шлях до збереженого файлу
 59	 * @throws FileStorageException якщо сталася помилка під час збереження
 60	 */
 61	 @Override
 62	 public Path save(InputStream inputStream, String fileName, UUID entityId) {
 63	 validateFileName(fileName);
 64	 Path entityDir = createEntityDirectory(entityId);
 65	 Path filePath = entityDir.resolve(fileName);
 66	
 67	 try {
 68	 Files.copy(inputStream, filePath, StandardCopyOption.REPLACE_EXISTING);
 69	 return filePath;
 70	 } catch (IOException e) {
 71	 throw new FileStorageException("Помилка збереження файлу: " + filePath, e);
 72	 }
 73	 }
 74	
 75	 /**
 76	 * Отримує шлях до файлу за ідентифікатором сутності та ім’ям файлу.
 77	 *
 78	 * @param fileName ім’я файлу
 79	 * @param entityId ідентифікатор сутності
 80	 * @return шлях до файлу
 81	 * @throws FileStorageException якщо файл не знайдено
 82	 */
 83	 @Override
 84	 public Path getFilePath(String fileName, UUID entityId) {
 85	 validateFileName(fileName);
 86	 Path filePath = storageRoot.resolve(entityId.toString()).resolve(fileName);
 87	
 88	 if (!Files.exists(filePath)) {
 89	 throw new FileStorageException("Файл не знайдено: " + filePath);
 90	 }
 91	
 92	 return filePath;
 93	 }
 94	
 95	 /**
 96	 * Видаляє файл за ідентифікатором сутності та ім’ям файлу.
 97	 *
 98	 * @param fileName ім’я файлу
 99	 * @param entityId ідентифікатор сутності
 100	 * @throws FileStorageException якщо сталася помилка під час видалення
 101	 */
 102	 @Override
 103	 public void delete(String fileName, UUID entityId) {
 104	 validateFileName(fileName);
 105	 Path filePath = storageRoot.resolve(entityId.toString()).resolve(fileName);
 106	
 107	 try {
 108	 if (Files.exists(filePath)) {
 109	 Files.delete(filePath);
 110	 }
 111	 } catch (IOException e) {
 112	 throw new FileStorageException("Помилка видалення файлу: " + filePath, e);
 113	 }
 114	 }
 115	
 116	 /**
 117	 * Перевіряє, чи існує файл.
 118	 *
 119	 * @param fileName ім’я файлу
 120	 * @param entityId ідентифікатор сутності
 121	 * @return true, якщо файл існує
 122	 */
 123	 @Override
 124	 public boolean exists(String fileName, UUID entityId) {
 125	 validateFileName(fileName);
 126	 Path filePath = storageRoot.resolve(entityId.toString()).resolve(fileName);
 127	 return Files.exists(filePath);
 128	 }
 129	
 130	 /**
 131	 * Створює директорію для сутності, якщо вона ще не існує.
 132	 *
 133	 * @param entityId ідентифікатор сутності
 134	 * @return шлях до директорії
 135	 */
 136	 private Path createEntityDirectory(UUID entityId) {
 137	 Path entityDir = storageRoot.resolve(entityId.toString());
 138	 try {
 139	 Files.createDirectories(entityDir);
 140	 return entityDir;
 141	 } catch (IOException e) {
 142	 throw new FileStorageException("Помилка створення директорії для сутності: " + entityDir, e);
 143	 }
 144	 }
 145	
 146	 /**
 147	 * Валідує ім’я файлу, перевіряючи його розширення та коректність.
 148	 *
 149	 * @param fileName ім’я файлу
 150	 */
 151	 private void validateFileName(String fileName) {
 152	 if (fileName == null || fileName.trim().isEmpty()) {
 153	 throw new FileStorageException("Ім’я файлу не може бути порожнім");
 154	 }
 155	
 156	 String extension = getFileExtension(fileName).toLowerCase();
 157	 if (!allowedExtensions.contains(extension)) {
 158	 throw new FileStorageException("Непідтримуваний формат файлу: " + extension);
 159	 }
 160	
 161	 if (fileName.contains("..") || fileName.contains("/") || fileName.contains("\\")) {
 162	 throw new FileStorageException("Некоректне ім’я файлу: " + fileName);
 163	 }
 164	 }
 165	
 166	 /**
 167	 * Валідує розмір файлу, перевіряючи, чи не перевищує він максимальний ліміт.
 168	 *
 169	 * @param inputStream потік даних файлу
 170	 * @throws FileStorageException якщо розмір файлу перевищує ліміт
 171	 */
 172	 private void validateFileSize(InputStream inputStream) {
 173	 try {
 174	 ByteArrayOutputStream buffer = new ByteArrayOutputStream();
 175	 byte[] data = new byte[1024];
 176	 int bytesRead;
 177	 long totalSize = 0;
 178	
 179	 while ((bytesRead = inputStream.read(data, 0, data.length)) != -1) {
 180	 totalSize += bytesRead;
 181	 if (totalSize > maxFileSize) {
 182	 throw new FileStorageException("Розмір файлу перевищує 5 МБ");
 183	 }
 184	 buffer.write(data, 0, bytesRead);
 185	 }
 186	
 187	 // Відновлюємо InputStream для подальшого використання
 188	 inputStream.close();
 189	 inputStream = new java.io.ByteArrayInputStream(buffer.toByteArray());
 190	 } catch (IOException e) {
 191	 throw new FileStorageException("Помилка перевірки розміру файлу", e);
 192	 }
 193	 }
 194	
 195	 /**
 196	 * Отримує розширення файлу.
 197	 *
 198	 * @param fileName ім’я файлу
 199	 * @return розширення файлу (без крапки)
 200	 */
 201	 private String getFileExtension(String fileName) {
 202	 int lastDotIndex = fileName.lastIndexOf('.');
 203	 if (lastDotIndex > 0 && lastDotIndex < fileName.length() - 1) {
 204	 return fileName.substring(lastDotIndex + 1).toLowerCase();
 205	 }
 206	 return "";
 207	 }
 208	}
