 107	
 108	 // Обробка нової фотографії
 109	 if (photo != null && photoName != null) {
 110	 Path photoPath = fileStorageService.save(photo, photoName, id);
 111	 author.setImagePath(photoPath.toString());
 112	 }
 113	
 114	 persistenceContext.registerUpdated(id, author);
 115	 persistenceContext.commit();
 116	 return author;
 117	 }
