 53	 *
 54	 * @param audiobook аудіокнига для створення
 55	 * @param coverImage потік даних обкладинки, може бути null
 56	 * @param coverImageName ім'я файлу обкладинки, може бути null
 57	 * @return створена аудіокнига
 58	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 59	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 60	 */
 61	 @Override
 62	 public Audiobook create(Audiobook audiobook, InputStream coverImage, String coverImageName) {
 63	 if (audiobook.getId() == null) {
 64	 audiobook.setId(UUID.randomUUID());
 65	 }
 66	
 67	 // Обробка завантаження обкладинки
 68	 if (coverImage != null && coverImageName != null) {
 69	 Path coverImagePath = fileStorageService.save(coverImage, coverImageName, audiobook.getId());
 70	 audiobook.setCoverImagePath(coverImagePath.toString());
 71	 }
 72	
 73	 persistenceContext.registerNew(audiobook);
 74	 persistenceContext.commit();
 75	 return audiobook;
 76	 }
 77	
 78	 /**
 79	 * Оновлює існуючу аудіокнигу та, за потреби, оновлює обкладинку.
 80	 *
 81	 * @param id ідентифікатор аудіокниги для оновлення
 82	 * @param audiobook оновлені дані аудіокниги
 83	 * @param coverImage потік даних нової обкладинки, може бути null
 84	 * @param coverImageName ім'я файлу нової обкладинки, може бути null
 85	 * @return оновлена аудіокнига
 86	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 87	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 88	 */
 89	 @Override
 90	 public Audiobook update(UUID id, Audiobook audiobook, InputStream coverImage, String coverImageName) {
 91	 audiobook.setId(id);
 92	
 93	 // Обробка існуючої обкладинки
 94	 if (audiobook.getCoverImagePath() != null && coverImage != null && coverImageName != null) {
 95	 fileStorageService.delete(audiobook.getCoverImagePath(), id);
 96	 }
 97	
 98	 // Обробка нової обкладинки
 99	 if (coverImage != null && coverImageName != null) {
 100	 Path coverImagePath = fileStorageService.save(coverImage, coverImageName, id);
 101	 audiobook.setCoverImagePath(coverImagePath.toString());
 102	 }
 103	
 104	 persistenceContext.registerUpdated(id, audiobook);
 105	 persistenceContext.commit();
 106	 return audiobook;
 107	 }
 108	
 109	 /**
 110	 * Видаляє аудіокнигу та всі пов'язані файли.
 111	 *
 112	 * @param id ідентифікатор аудіокниги для видалення
 113	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 114	 * @throws FileStorageException якщо виникає помилка при роботі з файлами
 115	 */
 116	 @Override
 117	 public void delete(UUID id) {
 118	 Optional<Audiobook> audiobookOpt = audiobookRepository.findById(id);
 119	 if (audiobookOpt.isPresent()) {
 120	 Audiobook audiobook = audiobookOpt.get();
 121	
 122	 // Видалення обкладинки
 123	 if (audiobook.getCoverImagePath() != null) {
 124	 fileStorageService.delete(audiobook.getCoverImagePath(), id);
 125	 }
 126	
 127	 // Видалення пов'язаних аудіофайлів
 128	 List<AudiobookFile> files = audiobookFileRepository.findByAudiobookId(id);
 129	 for (AudiobookFile file : files) {
 130	 fileStorageService.delete(file.getFilePath(), id);
 131	 persistenceContext.registerDeleted(file);
 132	 }
 133	
 134	 persistenceContext.registerDeleted(audiobook);
 135	 persistenceContext.commit();
 136	 }
 137	 }
