 50	 @Override
 51	 public User create(User user, InputStream avatar, String avatarName) {
 52	 validateUser(user);
 53	 if (user.getId() == null) {
 54	 user.setId(UUID.randomUUID());
 55	 }
 56	
 57	 // Перевірка на дублювання username
 58	 if (existsByUsername(user.getUsername())) {
 59	 throw new ValidationException("Користувач з таким ім'ям уже існує: " + user.getUsername());
 60	 }
 61	
 62	 // Перевірка на дублювання email
 63	 if (existsByEmail(user.getEmail())) {
 64	 throw new ValidationException("Користувач з таким email уже існує: " + user.getEmail());
 65	 }
 66	
 67	 // Хешування пароля
 68	 user.setPasswordHash(hashPassword(user.getPasswordHash()));
 69	
 70	 // Обробка завантаження аватара
 71	 if (avatar != null && avatarName != null) {
 72	 Path avatarPath = fileStorageService.save(avatar, avatarName, user.getId());
 73	 user.setAvatarPath(avatarPath.toString());
 74	 }
 75	
 76	 persistenceContext.registerNew(user);
 77	 persistenceContext.commit();
 78	 return user;
 79	 }
