 79	 audiobook.setId(UUID.randomUUID());
 80	 }
 81	
 82	 // Обробка завантаження обкладинки
 83	 if (coverImage != null && coverImageName != null) {
 84	 Path coverImagePath = fileStorageService.save(coverImage, coverImageName, audiobook.getId());
 85	 audiobook.setCoverImagePath(coverImagePath.toString());
 86	 }
 87	
 88	 persistenceContext.registerNew(audiobook);
 89	 persistenceContext.commit();
 90	 return audiobook;
