 104	 @Override
 105	 public Audiobook update(UUID id, Audiobook audiobook, InputStream coverImage, String coverImageName) {
 106	 audiobook.setId(id);
 107	
 108	 // Обробка існуючої обкладинки
 109	 if (audiobook.getCoverImagePath() != null && coverImage != null && coverImageName != null) {
 110	 fileStorageService.delete(audiobook.getCoverImagePath(), id);
 111	 }
 112	
 113	 // Обробка нової обкладинки
 114	 if (coverImage != null && coverImageName != null) {
 115	 Path coverImagePath = fileStorageService.save(coverImage, coverImageName, id);
 116	 audiobook.setCoverImagePath(coverImagePath.toString());
 117	 }
