 8	/**
 9	 * Сутність, що представляє аудіокнигу.
 10	 */
 11	@Getter
 12	@Setter
 13	@AllArgsConstructor
 14	@NoArgsConstructor
 15	public class Audiobook implements Comparable<Audiobook> {
 16	
 17	 @EqualsAndHashCode.Include
 18	 private UUID id;
 19	 private UUID authorId;
 20	 private UUID genreId;
 21	 private String title;
 22	 private int duration;
 23	 private int releaseYear;
 24	 private String description;
 25	 private String coverImagePath;
 26	
 27	 @Override
 28	 public boolean equals(Object o) {
 29	 if (this == o) return true;
 30	 if (o == null || getClass() != o.getClass()) return false;
 31	 Audiobook audiobook = (Audiobook) o;
 32	 return Objects.equals(id, audiobook.id);
 33	 }
 34	
 35	 @Override
 36	 public int hashCode() {
 37	 return Objects.hash(id);
 38	 }
 39	
 40	 @Override
 41	 public int compareTo(Audiobook other) {
 42	 // First compare by title
 43	 int titleComparison = this.title.compareToIgnoreCase(other.title);
 44	 if (titleComparison != 0) {
 45	 return titleComparison;
 46	 }
 47	
 48	 // If titles are equal, compare by release year (descending - newer first)
 49	 return Integer.compare(other.releaseYear, this.releaseYear);
 50	 }
 51	}
