 249	 @Override
 250	 public Optional<User> authenticate(String username, String password) {
 251	 if (username == null || username.trim().isEmpty()) {
 252	 throw new ValidationException("Username не може бути порожнім.");
 253	 }
 254	 if (password == null || password.trim().isEmpty()) {
 255	 throw new ValidationException("Пароль не може бути порожнім.");
 256	 }
 257	
 258	 List<User> users = findByUsername(username);
 259	 if (users.isEmpty()) {
 260	 return Optional.empty();
 261	 }
 262	
 263	 User user = users.get(0);
 264	 String hashedPassword = hashPassword(password);
 265	 
 266	 if (user.getPasswordHash().equals(hashedPassword)) {
 267	 return Optional.of(user);
 268	 }
 269	 
 270	 return Optional.empty();
 271	 }
