 68	 * Оновлює існуючу колекцію.
 69	 */
 70	 @Override
 71	 public Collection update(UUID id, Collection collection) {
 72	 validateCollection(collection);
 73	 collection.setId(id);
 74	
 75	 // Перевірка існування колекції
 76	 Optional<Collection> existingCollectionOpt = collectionRepository.findById(id);
 77	 if (!existingCollectionOpt.isPresent()) {
 78	 throw new ValidationException("Колекція з ідентифікатором " + id + " не існує.");
 79	 }
 80	
 81	 Collection existingCollection = existingCollectionOpt.get();
 82	
 83	 // Перевірка на дублювання назви (якщо назва змінюється)
 84	 if (!existingCollection.getName().equals(collection.getName()) && 
 85	 existsByUserIdAndName(collection.getUserId(), collection.getName())) {
 86	 throw new ValidationException("Колекція з назвою '" + collection.getName() + "' вже існує у користувача.");
 87	 }
 88	
 89	 // Зберігаємо дату створення
 90	 collection.setCreatedAt(existingCollection.getCreatedAt());
 91	
 92	 persistenceContext.registerUpdated(id, collection);
 93	 persistenceContext.commit();
 94	 return collection;
 95	 }
