 102	 Optional<Collection> collectionOpt = collectionRepository.findById(id);
 103	 if (collectionOpt.isPresent()) {
 104	 Collection collection = collectionOpt.get();
 105	 persistenceContext.registerDeleted(collection);
 106	 persistenceContext.commit();
 107	 }
 108	 }
