 66	 *
 67	 * @param filter фільтр для вибірки та пошуку (може бути null)
 68	 * @param sortBy поле для сортування (може бути null)
 69	 * @param isAscending напрямок сортування (true - за зростанням)
 70	 * @param offset зміщення для пагінації
 71	 * @param limit ліміт кількості записів
 72	 * @param baseSql базовий SQL-запит (наприклад, із JOIN)
 73	 * @return список знайдених сутностей
 74	 */
 75	 @Override
 76	 public List<T> findAll(Filter filter, String sortBy, boolean isAscending, int offset, int limit, String baseSql) {
 77	 StringJoiner sql = new StringJoiner(" ");
 78	 sql.add(baseSql);
 79	 List<Object> parameters = new ArrayList<>();
 80	
 81	 if (filter != null) {
 82	 StringJoiner whereClause = new StringJoiner(" AND ", " WHERE ", "");
 83	 filter.apply(whereClause, parameters);
 84	 sql.add(whereClause.toString());
 85	 }
 86	 if (sortBy != null && !sortBy.isEmpty()) {
 87	 sql.add("ORDER BY " + sortBy + (isAscending ? " ASC" : " DESC"));
 88	 }
 89	 sql.add("LIMIT ? OFFSET ?");
 90	 parameters.add(limit);
 91	 parameters.add(offset);
 92	
 93	 return executeQuery(sql.toString(), stmt -> setParameters(stmt, parameters));
 94	 }
