 45	 @Override
 46	 public AudiobookFile create(AudiobookFile audiobookFile, InputStream inputStream, String fileName) {
 47	 validateAudiobookFile(audiobookFile);
 48	 if (audiobookFile.getId() == null) {
 49	 audiobookFile.setId(UUID.randomUUID());
 50	 }
 51	
 52	 // Перевірка існування аудіокниги
 53	 if (!audiobookRepository.findById(audiobookFile.getAudiobookId()).isPresent()) {
 54	 throw new ValidationException("Аудіокнига з ідентифікатором " + audiobookFile.getAudiobookId() + " не існує.");
 55	 }
 56	
 57	 // Перевірка на дублювання шляху файлу
 58	 if (existsByAudiobookIdAndFilePath(audiobookFile.getAudiobookId(), audiobookFile.getFilePath())) {
 59	 throw new ValidationException("Файл з таким шляхом вже існує для цієї аудіокниги.");
 60	 }
 61	
 62	 // Завантаження файлу
 63	 if (inputStream != null && fileName != null) {
 64	 Path savedPath = fileStorageService.save(inputStream, fileName, audiobookFile.getAudiobookId());
 65	 audiobookFile.setFilePath(savedPath.toString());
 66	 }
 67	
 68	 persistenceContext.registerNew(audiobookFile);
 69	 persistenceContext.commit();
 70	 return audiobookFile;
 71	 }
