 76	 @Override
 77	 public AudiobookFile update(UUID id, AudiobookFile audiobookFile, InputStream inputStream, String fileName) {
 78	 validateAudiobookFile(audiobookFile);
 79	 audiobookFile.setId(id);
 80	
 81	 // Перевірка існування файлу
 82	 Optional<AudiobookFile> existingFileOpt = audiobookFileRepository.findById(id);
 83	 if (!existingFileOpt.isPresent()) {
 84	 throw new ValidationException("Файл аудіокниги з ідентифікатором " + id + " не існує.");
 85	 }
 86	
 87	 AudiobookFile existingFile = existingFileOpt.get();
 88	
 89	 // Обробка існуючого файлу
 90	 if (existingFile.getFilePath() != null && inputStream != null && fileName != null) {
 91	 String oldFileName = Path.of(existingFile.getFilePath()).getFileName().toString();
 92	 fileStorageService.delete(oldFileName, existingFile.getAudiobookId());
 93	 }
 94	
 95	 // Завантаження нового файлу
 96	 if (inputStream != null && fileName != null) {
 97	 Path savedPath = fileStorageService.save(inputStream, fileName, audiobookFile.getAudiobookId());
 98	 audiobookFile.setFilePath(savedPath.toString());
 99	 } else if (existingFile.getFilePath() != null) {
 100	 audiobookFile.setFilePath(existingFile.getFilePath());
 101	 }
 102	
 103	 persistenceContext.registerUpdated(id, audiobookFile);
 104	 persistenceContext.commit();
 105	 return audiobookFile;
 106	 }
