 5	/**
 6	 * Виняток для валідації з підтримкою множинних помилок по полях.
 7	 * Зберігає словник, де ключ - назва поля, значення - список помилок для цього поля.
 8	 */
 9	public class MultiFieldValidationException extends RuntimeException {
 10	
 11	 private final Map<String, List<String>> fieldErrors;
 12	
 13	 /**
 14	 * Конструктор з порожнім словником помилок.
 15	 */
 16	 public MultiFieldValidationException() {
 17	 super("Validation failed for multiple fields");
 18	 this.fieldErrors = new HashMap<>();
 19	 }
 20	
 21	 /**
 22	 * Конструктор з готовим словником помилок.
 23	 *
 24	 * @param fieldErrors словник помилок по полях
 25	 */
 26	 public MultiFieldValidationException(Map<String, List<String>> fieldErrors) {
 27	 super(buildMessage(fieldErrors));
 28	 this.fieldErrors = new HashMap<>(fieldErrors);
 29	 }
 30	
 31	 /**
 32	 * Конструктор з повідомленням та словником помилок.
 33	 *
 34	 * @param message загальне повідомлення про помилку
 35	 * @param fieldErrors словник помилок по полях
 36	 */
 37	 public MultiFieldValidationException(String message, Map<String, List<String>> fieldErrors) {
 38	 super(message);
 39	 this.fieldErrors = new HashMap<>(fieldErrors);
 40	 }
 41	
 42	 /**
 43	 * Додає помилку для конкретного поля.
 44	 *
 45	 * @param fieldName назва поля
 46	 * @param errorMessage повідомлення про помилку
 47	 */
 48	 public void addFieldError(String fieldName, String errorMessage) {
 49	 fieldErrors.computeIfAbsent(fieldName, k -> new ArrayList<>()).add(errorMessage);
 50	 }
