 28	 public Application(PersistenceContext persistenceContext,
 29	 AuthorRepository authorRepository,
 30	 PersistenceInitializer persistenceInitializer,
 31	 ConnectionPool connectionPool) {
 32	 this.persistenceContext = persistenceContext;
