 43	 persistenceInitializer.init();
 44	
 45	
 46	 Author author2 = new Author(UUID.randomUUID(), "John", "Doe", "Bio", null);
 47	 persistenceContext.registerNew(author2);
 48	 persistenceContext.commit();
 49	
 50	 // Вибірка всіх авторів
 51	 List<Author> authors = authorRepository.findAll();
 52	 System.out.println("Знайдені автори:");
 53	 authors.forEach(author ->
 54	 System.out.printf("ID: %s, Ім'я: %s %s%n",
 55	 author.getId(),
 56	 author.getFirstName(),
 57	 author.getLastName())
 58	 );
 59	
 60	 // Закриття пулу з'єднань
 61	 connectionPool.shutdown();
 62	 }
 63	
 64	 public static void main(String[] args) {
 65	 ApplicationContext context = new AnnotationConfigApplicationContext(InfrastructureConfig.class, AppConfig.class);
 66	 Application app = context.getBean(Application.class);
 67	 app.run();
 68	 }
