 313	 /**
 314	 * Хешує пароль за допомогою SHA-256.
 315	 */
 316	 String hashPassword(String password) {
 317	 try {
 318	 MessageDigest digest = MessageDigest.getInstance("SHA-256");
 319	 byte[] hash = digest.digest(password.getBytes());
 320	 StringBuilder hexString = new StringBuilder();
 321	 for (byte b : hash) {
 322	 String hex = Integer.toHexString(0xff & b);
 323	 if (hex.length() == 1) {
 324	 hexString.append('0');
 325	 }
 326	 hexString.append(hex);
 327	 }
 328	 return hexString.toString();
 329	 } catch (NoSuchAlgorithmException e) {
 330	 throw new RuntimeException("Помилка хешування пароля", e);
 331	 }
 332	 }
 333	}
