 282	 @Override
 283	 public void clearCollection(UUID collectionId) {
 284	 if (collectionId == null) {
 285	 throw new ValidationException("Ідентифікатор колекції не може бути null.");
 286	 }
 287	
 288	 List<Audiobook> audiobooks = findAudiobooksByCollectionId(collectionId);
 289	 for (Audiobook audiobook : audiobooks) {
 290	 collectionRepository.removeAudiobookFromCollection(collectionId, audiobook.getId());
 291	 }
 292	 }
 293	
 294	 /**
 295	 * Валідує дані колекції.
 296	 */
 297	 private void validateCollection(Collection collection) {
 298	 if (collection == null) {
 299	 throw new ValidationException("Колекція не може бути null.");
 300	 }
 301	 if (collection.getUserId() == null) {
 302	 throw new ValidationException("Ідентифікатор користувача не може бути null.");
 303	 }
 304	 if (collection.getName() == null || collection.getName().trim().isEmpty()) {
 305	 throw new ValidationException("Назва колекції не може бути порожньою.");
 306	 }
 307	 }
 308	
 309	 /**
 310	 * Валідує параметри пагінації.
 311	 */
 312	 private void validatePagination(int offset, int limit) {
 313	 if (offset < 0) {
 314	 throw new ValidationException("Offset не може бути від'ємним.");
 315	 }
 316	 if (limit <= 0) {
 317	 throw new ValidationException("Limit повинен бути більше нуля.");
 318	 }
 319	 }
 320	}
