 216	 @Override
 217	 public List<Audiobook> findSimilar(UUID audiobookId, int limit) {
 218	 // Простий підхід - знаходимо аудіокниги того ж автора або жанру
 219	 java.util.Optional<Audiobook> audiobookOpt = findById(audiobookId);
 220	 if (!audiobookOpt.isPresent()) {
 221	 return java.util.Collections.emptyList();
 222	 }
 223	
 224	 Audiobook audiobook = audiobookOpt.get();
 225	 List<Audiobook> similar = new java.util.ArrayList<>();
 226	
 227	 // Додаємо аудіокниги того ж автора
 228	 similar.addAll(findByAuthorId(audiobook.getAuthorId()));
 229	
 230	 // Додаємо аудіокниги того ж жанру
 231	 similar.addAll(findByGenreId(audiobook.getGenreId()));
 232	
 233	 // Видаляємо оригінальну аудіокнигу та дублікати
 234	 return similar.stream()
 235	 .filter(a -> !a.getId().equals(audiobookId))
 236	 .distinct()
 237	 .limit(limit)
 238	 .collect(java.util.stream.Collectors.toList());
 239	 }
