 328	 @Override
 329	 public List<Collection> findMostPopularPublicCollections(int limit) {
 330	 String sql = """
 331	 SELECT c.* FROM collections c
 332	 LEFT JOIN audiobook_collection ac ON c.id = ac.collection_id
 333	 WHERE c.user_id IS NULL
 334	 GROUP BY c.id, c.user_id, c.name, c.created_at
 335	 ORDER BY COUNT(ac.audiobook_id) DESC, c.created_at DESC
 336	 LIMIT ?
 337	 """;
 338	 return executeQuery(sql, stmt -> stmt.setInt(1, limit), this::mapResultSetToCollection);
 339	 }
