 134	 @Override
 135	 public void delete(UUID id) {
 136	 Optional<User> userOpt = userRepository.findById(id);
 137	 if (userOpt.isPresent()) {
 138	 User user = userOpt.get();
 139	
 140	 // Видалення аватара
 141	 if (user.getAvatarPath() != null) {
 142	 String fileName = Path.of(user.getAvatarPath()).getFileName().toString();
 143	 fileStorageService.delete(fileName, id);
 144	 }
 145	
 146	 persistenceContext.registerDeleted(user);
 147	 persistenceContext.commit();
 148	 }
 149	 }
