 21	/**
 22	 * Реалізація сервісу для управління файлами аудіокниг.
 23	 */
 24	@Service
 25	public class AudiobookFileServiceImpl implements AudiobookFileService {
 26	
 27	 private final AudiobookFileRepository audiobookFileRepository;
 28	 private final AudiobookRepository audiobookRepository;
 29	 private final PersistenceContext persistenceContext;
 30	 private final FileStorageService fileStorageService;
 31	
 32	 public AudiobookFileServiceImpl(AudiobookFileRepository audiobookFileRepository,
 33	 AudiobookRepository audiobookRepository,
 34	 PersistenceContext persistenceContext,
 35	 FileStorageService fileStorageService) {
 36	 this.audiobookFileRepository = audiobookFileRepository;
 37	 this.audiobookRepository = audiobookRepository;
 38	 this.persistenceContext = persistenceContext;
 39	 this.fileStorageService = fileStorageService;
 40	 }
 41	
 42	 /**
 43	 * Створює новий файл аудіокниги та завантажує його.
 44	 */
 45	 @Override
 46	 public AudiobookFile create(AudiobookFile audiobookFile, InputStream inputStream, String fileName) {
 47	 validateAudiobookFile(audiobookFile);
 48	 if (audiobookFile.getId() == null) {
 49	 audiobookFile.setId(UUID.randomUUID());
 50	 }
 51	
 52	 // Перевірка існування аудіокниги
 53	 if (!audiobookRepository.findById(audiobookFile.getAudiobookId()).isPresent()) {
 54	 throw new ValidationException("Аудіокнига з ідентифікатором " + audiobookFile.getAudiobookId() + " не існує.");
 55	 }
 56	
 57	 // Перевірка на дублювання шляху файлу
 58	 if (existsByAudiobookIdAndFilePath(audiobookFile.getAudiobookId(), audiobookFile.getFilePath())) {
 59	 throw new ValidationException("Файл з таким шляхом вже існує для цієї аудіокниги.");
 60	 }
 61	
 62	 // Завантаження файлу
 63	 if (inputStream != null && fileName != null) {
 64	 Path savedPath = fileStorageService.save(inputStream, fileName, audiobookFile.getAudiobookId());
 65	 audiobookFile.setFilePath(savedPath.toString());
 66	 }
 67	
 68	 persistenceContext.registerNew(audiobookFile);
 69	 persistenceContext.commit();
 70	 return audiobookFile;
 71	 }
 72	
 73	 /**
 74	 * Оновлює існуючий файл аудіокниги.
 75	 */
 76	 @Override
 77	 public AudiobookFile update(UUID id, AudiobookFile audiobookFile, InputStream inputStream, String fileName) {
 78	 validateAudiobookFile(audiobookFile);
 79	 audiobookFile.setId(id);
 80	
 81	 // Перевірка існування файлу
 82	 Optional<AudiobookFile> existingFileOpt = audiobookFileRepository.findById(id);
 83	 if (!existingFileOpt.isPresent()) {
 84	 throw new ValidationException("Файл аудіокниги з ідентифікатором " + id + " не існує.");
 85	 }
 86	
 87	 AudiobookFile existingFile = existingFileOpt.get();
 88	
 89	 // Обробка існуючого файлу
 90	 if (existingFile.getFilePath() != null && inputStream != null && fileName != null) {
 91	 String oldFileName = Path.of(existingFile.getFilePath()).getFileName().toString();
 92	 fileStorageService.delete(oldFileName, existingFile.getAudiobookId());
 93	 }
 94	
 95	 // Завантаження нового файлу
 96	 if (inputStream != null && fileName != null) {
 97	 Path savedPath = fileStorageService.save(inputStream, fileName, audiobookFile.getAudiobookId());
 98	 audiobookFile.setFilePath(savedPath.toString());
 99	 } else if (existingFile.getFilePath() != null) {
 100	 audiobookFile.setFilePath(existingFile.getFilePath());
 101	 }
 102	
 103	 persistenceContext.registerUpdated(id, audiobookFile);
 104	 persistenceContext.commit();
 105	 return audiobookFile;
 106	 }
