 108	 /**
 109	 * Видаляє файл аудіокниги та пов'язаний фізичний файл.
 110	 */
 111	 @Override
 112	 public void delete(UUID id) {
 113	 Optional<AudiobookFile> fileOpt = audiobookFileRepository.findById(id);
 114	 if (fileOpt.isPresent()) {
 115	 AudiobookFile file = fileOpt.get();
 116	
 117	 // Видалення фізичного файлу
 118	 if (file.getFilePath() != null) {
 119	 String fileName = Path.of(file.getFilePath()).getFileName().toString();
 120	 fileStorageService.delete(fileName, file.getAudiobookId());
 121	 }
 122	
 123	 persistenceContext.registerDeleted(file);
 124	 persistenceContext.commit();
 125	 }
 126	 }
