 229	 @Override
 230	 public AudiobookFile copyFile(UUID sourceFileId, UUID targetAudiobookId, String newFileName) {
 231	 if (sourceFileId == null) {
 232	 throw new ValidationException("Ідентифікатор вихідного файлу не може бути null.");
 233	 }
 234	 if (targetAudiobookId == null) {
 235	 throw new ValidationException("Ідентифікатор цільової аудіокниги не може бути null.");
 236	 }
 237	 if (newFileName == null || newFileName.trim().isEmpty()) {
 238	 throw new ValidationException("Нове ім'я файлу не може бути порожнім.");
 239	 }
 240	
 241	 // Перевірка існування вихідного файлу
 242	 Optional<AudiobookFile> sourceFileOpt = audiobookFileRepository.findById(sourceFileId);
 243	 if (!sourceFileOpt.isPresent()) {
 244	 throw new ValidationException("Вихідний файл не існує.");
 245	 }
 246	
 247	 // Перевірка існування цільової аудіокниги
 248	 if (!audiobookRepository.findById(targetAudiobookId).isPresent()) {
 249	 throw new ValidationException("Цільова аудіокнига не існує.");
 250	 }
 251	
 252	 AudiobookFile sourceFile = sourceFileOpt.get();
 253	
 254	 // Створення копії файлу
 255	 AudiobookFile newFile = new AudiobookFile(
 256	 UUID.randomUUID(),
 257	 targetAudiobookId,
 258	 null, // filePath буде встановлено при збереженні
 259	 sourceFile.getFormat(),
 260	 sourceFile.getSize()
 261	 );
 262	
 263	 // Тут потрібно було б скопіювати фізичний файл, але це складно без доступу до файлової системи
 264	 // Для спрощення просто створюємо запис у базі даних
 265	 persistenceContext.registerNew(newFile);
 266	 persistenceContext.commit();
 267	 return newFile;
 268	 }
