 335	 /**
 336	 * Створює нову публічну колекцію (загальнодоступну).
 337	 */
 338	 @Override
 339	 public Collection createPublicCollection(Collection collection) {
 340	 validateCollection(collection);
 341	 if (collection.getId() == null) {
 342	 collection.setId(UUID.randomUUID());
 343	 }
 344	 if (collection.getCreatedAt() == null) {
 345	 collection.setCreatedAt(LocalDateTime.now());
 346	 }
 347	
 348	 // Встановлюємо userId в null для публічної колекції
 349	 collection.setUserId(null);
 350	
 351	 // Перевірка на дублювання назви публічної колекції
 352	 if (existsPublicCollectionByName(collection.getName())) {
 353	 throw new ValidationException("Публічна колекція з назвою '" + collection.getName() + "' вже існує.");
 354	 }
 355	
 356	 persistenceContext.registerNew(collection);
 357	 persistenceContext.commit();
 358	 return collection;
 359	 }
