-pref-width: 230px;\n}\n\n.logout-button:hover {\n -fx-background-color: #c0392b;\n}\n\n/* \u0421\u0442\u0438\u043b\u0456 \u0434\u043b\u044f \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u043d\u043e\u0457 \u043e\u0431\u043b\u0430\u0441\u0442\u0456 */\n.page-header {\n -fx-background-color: white;\n -fx-border-color: #dee2e6;\n -fx-border-width: 0 0 1px 0;\n}\n\n.page-title {\n -fx-text-fill: #2c3e50;\n -fx-font-weight: bold;\n}\n\n.page-subtitle {\n -fx-text-fill: #6c757d;\n -fx-font-size: 16px;\n}\n\n/* \u0421\u0442\u0438\u043b\u0456 \u0434\u043b\u044f \u0434\u0430\u0448\u0431\u043e\u0440\u0434\u0443 */\n.statistics-grid {\n -fx-background-color: transparent;\n}\n\n.stat-card {\n -fx-background-color: white;\n -fx-background-radius: 10px;\n -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.1), 10, 0, 0, 2);\n -fx-alignment: CENTER;\n -fx-spacing: 10px;\n -fx-min-height: 150px;\n}\n\n.stat-card:hover {\n -fx-effect: dropshadow(gaussian, rgba(0, 0, 0, 0.15), 15, 0, 0, 3);\n}\n\n.stat-icon {\n -fx-font-size: 32px;\n}\n\n.stat-number {\n -fx-text-fill: #2c3e50;\n -fx-font-weight: bold;\n}\n\n.stat-label {\n -fx-text-fill: #6c757d;\n -fx-font-size: 16px;\n -fx-font-weight: bold;\n}\n\n/* \u0421\u0442\u0438\u043b\u0456 \u0434\u043b\u044f \u043f\u0430\u043d\u0435\u043b\u0456 \u0456\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0456\u0432 */\n.toolbar {\n -fx-background-color: white;\n -fx-border-color: #dee2e6;\n -fx-border-width: 0 0 1px 0;\n}\n\n.primary-button {\n -fx-background-color: #3498db;\n -fx-text-fill: white;\n -fx-font-size: 14px;\n -fx-font-weight: bold;\n -fx-padding: 10px 20px;\n -fx-border-radius: 6px;\n -fx-background-radius: 6px;\n -fx-cursor: hand;\n}\n\n.primary-button:hover {\n -fx-background-color: #2980b9;\n}\n\n.secondary-button {\n -fx-background-color: #95a5a6;\n -fx-text-fill: white;\n -fx-font-size: 14px;\n -fx-padding: 10px 20px;\n -fx-border-radius: 6px;\n -fx-background-radius: 6px;\n -fx-cursor: hand;\n}\n\n.secondary-button:hover {\n