 52	 @Override
 53	 public User create(User user, InputStream avatar, String avatarName) {
 54	 validateUser(user);
 55	 if (user.getId() == null) {
 56	 user.setId(UUID.randomUUID());
 57	 }
 58	
 59	 // Перевірка на дублювання username та email
 60	 ValidationHelper duplicateValidator = new ValidationHelper();
 61	 if (existsByUsername(user.getUsername())) {
 62	 duplicateValidator.addError("username", "користувач з таким ім'ям уже існує");
 63	 }
 64	 if (existsByEmail(user.getEmail())) {
 65	 duplicateValidator.addError("email", "користувач з таким email уже існує");
 66	 }
 67	 duplicateValidator.throwIfHasErrors();
 68	
 69	 // Хешування пароля
 70	 user.setPasswordHash(hashPassword(user.getPasswordHash()));
 71	
 72	 // Обробка завантаження аватара
 73	 if (avatar != null && avatarName != null) {
 74	 Path avatarPath = fileStorageService.save(avatar, avatarName, user.getId());
 75	 user.setAvatarPath(avatarPath.toString());
 76	 }
 77	
 78	 persistenceContext.registerNew(user);
 79	 persistenceContext.commit();
 80	 return user;
 81	 }
