 228	 public void changePassword(UUID userId, String oldPassword, String newPassword) {
 229	 ValidationHelper passwordValidator = new ValidationHelper()
 230	 .validUuid("userId", userId)
 231	 .notEmpty("oldPassword", oldPassword)
 232	 .notEmpty("newPassword", newPassword);
 233	
 234	 Optional<User> userOpt = userRepository.findById(userId);
 235	 if (!userOpt.isPresent()) {
 236	 passwordValidator.addError("userId", "користувач не знайдений");
 237	 }
 238	
 239	 passwordValidator.throwIfHasErrors();
 240	
 241	 User user = userOpt.get();
 242	 String hashedOldPassword = hashPassword(oldPassword);
 243	
 244	 if (!user.getPasswordHash().equals(hashedOldPassword)) {
 245	 new ValidationHelper()
 246	 .addError("oldPassword", "неправильний старий пароль")
 247	 .throwIfHasErrors();
 248	 }
 249	
 250	 user.setPasswordHash(hashPassword(newPassword));
 251	 persistenceContext.registerUpdated(userId, user);
 252	 persistenceContext.commit();
 253	 }
