 306	 /**
 307	 * Хешує пароль за допомогою SHA-256.
 308	 */
 309	 String hashPassword(String password) {
 310	 try {
 311	 MessageDigest digest = MessageDigest.getInstance("SHA-256");
 312	 byte[] hash = digest.digest(password.getBytes());
 313	 StringBuilder hexString = new StringBuilder();
 314	 for (byte b : hash) {
 315	 String hex = Integer.toHexString(0xff & b);
 316	 if (hex.length() == 1) {
 317	 hexString.append('0');
 318	 }
 319	 hexString.append(hex);
 320	 }
 321	 return hexString.toString();
 322	 } catch (NoSuchAlgorithmException e) {
 323	 throw new RuntimeException("Помилка хешування пароля", e);
 324	 }
 325	 }
 326	}
