","workspace_file_chunks":[]},{"status":"success","request_id":"03453cdd-af98-4134-a65a-bb5abdc35d24","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_vrtx_01Aniz4WDvdmTH4xZiCJm7jZ","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO BE ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "src/main/java/com/arakviel/presentation/controller/AudiobooksController.java", "file_content": "package com.arakviel.presentation.controller;\n\nimport com.arakviel.application.contract.AudiobookService;\nimport com.arakviel.domain.entities.Audiobook;\nimport com.arakviel.presentation.util.ServiceProvider;\nimport javafx.collections.FXCollections;\nimport javafx.collections.ObservableList;\nimport javafx.concurrent.Task;\nimport javafx.fxml.FXML;\nimport javafx.fxml.Initializable;\nimport javafx.scene.control.*;\nimport javafx.scene.control.cell.PropertyValueFactory;\n\nimport java.net.URL;\nimport java.util.List;\nimport java.util.ResourceBundle;\n\n/**\n * \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0440 \u0434\u043b\u044f \u0441\u0442\u043e\u0440\u0456\u043d\u043a\u0438 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433.\n */\npublic class AudiobooksController implements Initializable {\n\n @FXML private TextField searchField;\n @FXML private Button searchButton;\n @FXML private Button addButton;\n @FXML private TableView<Audiobook> audiobooksTable;\n @FXML private TableColumn<Audiobook, String> titleColumn;\n @FXML private TableColumn<Audiobook, String> authorColumn;\n @FXML private TableColumn<Audiobook, String> genreColumn;\n @FXML private TableColumn<Audiobook, Integer> durationColumn;\n @FXML private TableColumn<Audiobook, Integer> yearColumn;\n @FXML private ProgressIndicator loadingIndicator;\n @FXML private Label statusLabel;\n\n private AudiobookService audiobookService;\n private ObservableList<Audiobook> audiobooks;\n\n @Override\n public void initialize(URL location, ResourceBundle resources) {\n audiobookService = ServiceProvider.getAudiobookService();\n audiobooks = FXCollections.observableArrayList();\n \n setupTable();\n loadAudiobooks();\n }\n\n /**\n * \u041d\u0430\u043b\u0430\u0448\u0442\u043e\u0432\u0443\u0454 \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433.\n */\n private void setupTable() {\n titleColumn.setCellValueFactory(new PropertyValueFactory<>(\"title\"));\n durationColumn.setCellValueFactory(new PropertyValueFactory<>(\"duration\"));\n yearColumn.setCellValueFactory(new PropertyValueFactory<>(\"releaseYear\"));\n \n // \u0414\u043b\u044f author \u0442\u0430 genre \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u043e \u0431\u0443\u0434\u0435 \u0434\u043e\u0434\u0430\u0442\u0438 \u043c\u0435\u0442\u043e\u0434\u0438 \u043e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u043d\u0430\u0437\u0432\n authorColumn.setCellValueFactory(cellData -> {\n // \u0422\u0443\u0442 \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u043e \u0431\u0443\u0434\u0435 \u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438 \u0456\u043c'\u044f \u0430\u0432\u0442\u043e\u0440\u0430 \u0437\u0430 ID\n return new javafx.beans.property.SimpleStringProperty(\"\u0410\u0432\u0442\u043e\u0440 \" + cellData.getValue().getAuthorId());\n });\n \n genreColumn.setCellValueFactory(cellData -> {\n // \u0422\u0443\u0442 \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u043e \u0431\u0443\u0434\u0435 \u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438 \u043d\u0430\u0437\u0432\u0443 \u0436\u0430\u043d\u0440\u0443 \u0437\u0430 ID\n return new javafx.beans.property.SimpleStringProperty(\"\u0416\u0430\u043d\u0440 \" + cellData.getValue().getGenreId());\n });\n\n audiobooksTable.setItems(audiobooks);\n \n // \u0414\u043e\u0434\u0430\u0454\u043c\u043e \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u043d\u0435 \u043c\u0435\u043d\u044e\n setupContextMenu();\n }\n\n /**\n * \u041d\u0430\u043b\u0430\u0448\u0442\u043e\u0432\u0443\u0454 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u043d\u0435 \u043c\u0435\u043d\u044e \u0434\u043b\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0456.\n */\n private void setupContextMenu() {\n ContextMenu contextMenu = new ContextMenu();\n \n MenuItem editItem = new MenuItem(\"\u0420\u0435\u0434\u0430\u0433\u0443\u0432\u0430\u0442\u0438\");\n editItem.setOnAction(e -> editSelectedAudiobook());\n \n MenuItem deleteItem = new MenuItem(\"\u0412\u0438\u0434\u0430\u043b\u0438\u0442\u0438\");\n deleteItem.setOnAction(e -> deleteSelectedAudiobook());\n \n contextMenu.getItems().addAll(editItem, deleteItem);\n audiobooksTable.setContextMenu(contextMenu);\n }\n\n /**\n * \u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0443\u0454 \u0441\u043f\u0438\u0441\u043e\u043a \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433.\n */\n private void loadAudiobooks() {\n loadingIndicator.setVisible(true);\n statusLabel.setText(\"\u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433...\");\n\n Task<List<Audiobook>> loadTask = new Task<List<Audiobook>>() {\n @Override\n protected List<Audiobook> call() throws Exception {\n return audiobookService.findAll();\n }\n };\n\n loadTask.setOnSucceeded(e -> {\n loadingIndicator.setVisible(false);\n audiobooks.clear();\n audiobooks.addAll(loadTask.getValue());\n statusLabel.setText(\"\u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043e \" + audiobooks.size() + \" \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\");\n });\n\n loadTask.setOnFailed(e -> {\n loadingIndicator.setVisible(false);\n statusLabel.setText(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430 \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\");\n showErrorAlert(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430\", \"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0438\u0442\u0438 \u0441\u043f\u0438\u0441\u043e\u043a \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\");\n });\n\n new Thread(loadTask).start();\n }\n\n /**\n * \u041e\u0431\u0440\u043e\u0431\u043b\u044f\u0454 \u043f\u043e\u0448\u0443\u043a \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433.\n */\n @FXML\n private void handleSearch() {\n String searchText = searchField.getText().trim();\n if (searchText.isEmpty()) {\n loadAudiobooks();\n return;\n }\n\n loadingIndicator.setVisible(true);\n statusLabel.setText(\"\u041f\u043e\u0448\u0443\u043a...\");\n\n Task<List<Audiobook>> searchTask = new Task<List<Audiobook>>() {\n @Override\n protected List<Audiobook> call() throws Exception {\n return audiobookService.findByTitle(searchText);\n }\n };\n\n searchTask.setOnSucceeded(e -> {\n loadingIndicator.setVisible(false);\n audiobooks.clear();\n audiobooks.addAll(searchTask.getValue());\n statusLabel.setText(\"\u0417\u043d\u0430\u0439\u0434\u0435\u043d\u043e \" + audiobooks.size() + \" \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\");\n });\n\n searchTask.setOnFailed(e -> {\n loadingIndicator.setVisible(false);\n statusLabel.setText(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430 \u043f\u043e\u0448\u0443\u043a\u0443\");\n showErrorAlert(\"\u041f\u043e\u043c\u0438\u043b\u043a\u0430\", \"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0432\u0438\u043a\u043e\u043d\u0430\u0442\u0438 \u043f\u043e\u0448\u0443\u043a\");\n });\n\n new Thread(searchTask).start();\n }\n\n /**\n * \u041e\u0431\u0440\u043e\u0431\u043b\u044f\u0454 \u0434\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f \u043d\u043e\u0432\u043e\u0457 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438.\n */\n @FXML\n private void handleAdd() {\n // \u0422\u0443\u0442 \u0431\u0443\u0434\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0432\u0430\u0442\u0438\u0441\u044f \u0434\u0456\u0430\u043b\u043e\u0433 \u0434\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f \u043d\u043e\u0432\u043e\u0457 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438\n showInfoAlert(\"\u0406\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044f\", \"\u0424\u0443\u043d\u043a\u0446\u0456\u044f \u0434\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0431\u0443\u0434\u0435 \u0440\u0435\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430 \u043f\u0456\u0437\u043d\u0456\u0448\u0435\");\n }\n\n /**\n * \u0420\u0435\u0434\u0430\u0433\u0443\u0454 \u0432\u0438\u0431\u0440\u0430\u043d\u0443 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443.\n */\n private void editSelectedAudiobook() {\n Audiobook selected = audiobooksTable.getSelectionModel().getSelectedItem();\n if (selected != null) {\n showInfoAlert(\"\u0406\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044f\", \"\u0424\u0443\u043d\u043a\u0446\u0456\u044f \u0440\u0435\u0434\u0430\u0433\u0443\u0432\u0430\u043d\u043d\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0431\u0443\u0434\u0435 \u0440\u0435\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430 \u043f\u0456\u0437\u043d\u0456\u0448\u0435\");\n }\n }\n\n /**\n * \u0412\u0438\u0434\u0430\u043b\u044f\u0454 \u0432\u0438\u0431\u0440\u0430\u043d\u0443 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443.\n */\n private void deleteSelectedAudiobook() {\n Audiobook selected = audiobooksTable.getSelectionModel().getSelectedItem();\n if (selected != null) {\n Alert alert = new Alert(Alert.AlertType.CONFIRMATION);\n alert.setTitle(\"\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f\");\n alert.setHeaderText(\"\u0412\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443?\");\n alert.setContentText(\"\u0412\u0438 \u0434\u0456\u0439\u0441\u043d\u043e \u0445\u043e\u0447\u0435\u0442\u0435 \u0432\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0443 \\\"\" + selected.getTitle() + \"\\\"?\");\n\n alert.showAndWait().ifPresent(response -> {\n if (response == ButtonType.OK) {\n // \u0422\u0443\u0442 \u0431\u0443\u0434\u0435 \u043b\u043e\u0433\u0456\u043a\u0430 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f\n showInfoAlert(\"\u0406\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044f\", \"\u0424\u0443\u043d\u043a\u0446\u0456\u044f \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u0430\u0443\u0434\u0456\u043e\u043a\u043d\u0438\u0433\u0438 \u0431\u0443\u0434\u0435 \u0440\u0435\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430 \u043f\u0456\u0437\u043d\u0456\u0448\u0435\");\n }\n });\n }\n }\n\n /**\n * \u041f\u043e\u043a\u0430\u0437\u0443\u0454 \u0434\u0456\u0430\u043b\u043e\u0433 \u043f\u043e\u043c\u0438\u043b\u043a\u0438.\n */\n private void showErrorAlert(String title, String message) {\n Alert alert = new Alert(Alert.AlertType.ERROR);\n alert.setTitle(title);\n alert.setHeaderText(null);\n alert.setContentText(message);\n alert.showAndWait();\n }\n\n /**\n * \u041f\u043e\u043a\u0430\u0437\u0443\u0454 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u0439\u043d\u0438\u0439 \u0434\u0456\u0430\u043b\u043e\u0433.\n */\n private void showInfoAlert(String title, String message) {\n Alert alert = new Alert(Alert.AlertType.INFORMATION);\n alert.setTitle(title);\n alert.setHeaderText(null);\n alert.setContentText(message);\n alert.showAndWait();\n }\n}"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер давайте створимо простий контролер для аудіокниг як приклад розширення функціоналу:
