b\u0430\u0448\u0442\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u043e \u0440\u0456\u0437\u043d\u0438\u0445 \u043c\u0456\u0441\u0446\u044f\u0445\n\n**\u0421\u0442\u0430\u043b\u043e:**\n- `MainApplication.java` - \u0454\u0434\u0438\u043d\u0438\u0439 \u0433\u043e\u043b\u043e\u0432\u043d\u0438\u0439 \u043a\u043b\u0430\u0441 JavaFX \u0434\u043e\u0434\u0430\u0442\u043a\u0443\n- `MainConfig.java` - \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430 \u043a\u043e\u043d\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044f \u0434\u043b\u044f \u0432\u0441\u0456\u0445 \u0448\u0430\u0440\u0456\u0432\n- \u0412\u0441\u0456 \u0448\u0430\u0440\u0438 \u0430\u0440\u0445\u0456\u0442\u0435\u043a\u0442\u0443\u0440\u0438 \u043d\u0430\u043b\u0430\u0448\u0442\u043e\u0432\u0443\u044e\u0442\u044c\u0441\u044f \u0432 \u043e\u0434\u043d\u043e\u043c\u0443 \u043c\u0456\u0441\u0446\u0456\n\n### 2. \u0421\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043a\u043e\u043d\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u0457\n\n#### MainConfig.java\n```java\n@Configuration\n@ComponentScan(basePackages = {\n \"com.arakviel.presentation\", // UI \u0448\u0430\u0440\n \"com.arakviel.application\", // \u0411\u0456\u0437\u043d\u0435\u0441-\u043b\u043e\u0433\u0456\u043a\u0430\n \"com.arakviel.infrastructure\", // \u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0457, \u0411\u0414\n \"com.arakviel.domain\" // \u0421\u0443\u0442\u043d\u043e\u0441\u0442\u0456, \u0435\u043d\u0443\u043c\u0438\n})\n@Import({ApplicationConfig.class, InfrastructureConfig.class})\npublic class MainConfig {\n // \u0413\u043e\u043b\u043e\u0432\u043d\u0430 \u043a\u043e\u043d\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044f \u0432\u0441\u0456\u0445 \u0448\u0430\u0440\u0456\u0432\n}\n```\n\n#### MainApplication.java\n```java\n@Override\npublic void init() {\n // \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f Spring \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0443 \u0437 \u0443\u0441\u0456\u043c\u0430 \u0448\u0430\u0440\u0430\u043c\u0438\n springContext = new AnnotationConfigApplicationContext(MainConfig.class);\n ServiceProvider.setApplicationContext(springContext);\n \n // \u041b\u043e\u0433\u0443\u0432\u0430\u043d\u043d\u044f \u0443\u0441\u043f\u0456\u0448\u043d\u043e\u0457 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457\n System.out.println(\"\u2705 Spring \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u043e \u0437 \u0443\u0441\u0456\u043c\u0430 \u0448\u0430\u0440\u0430\u043c\u0438:\");\n System.out.println(\" - Infrastructure \u0448\u0430\u0440 (\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0457, \u0431\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445)\");\n System.out.println(\" - Application \u0448\u0430\u0440 (\u0441\u0435\u0440\u0432\u0456\u0441\u0438, \u0431\u0456\u0437\u043d\u0435\u0441-\u043b\u043e\u0433\u0456\u043a\u0430)\");\n System.out.println(\" - Presentation \u0448\u0430\u0440 (JavaFX \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0440\u0438)\");\n}\n```\n\n### 3. \u041f\u0435\u0440\u0435\u0432\u0430\u0433\u0438 \u043d\u043e\u0432\u043e\u0457 \u0430\u0440\u0445\u0456\u0442\u0435\u043a\u0442\u0443\u0440\u0438\n\n#### \u0426\u0435\u043d\u0442\u0440\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0456\u043d\u043d\u044f\n- **\u0404\u0434\u0438\u043d\u0430 \u0442\u043e\u0447\u043a\u0430 \u043a\u043e\u043d\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u0457** \u0434\u043b\u044f \u0432\u0441\u0456\u0445 \u0448\u0430\u0440\u0456\u0432\n- **\u041f\u0440\u043e\u0441\u0442\u0456\u0448\u0435 \u043d\u0430\u043b\u0430\u0433\u043e\u0434\u0436\u0435\u043d\u043d\u044f** \u0442\u0430 \u043f\u0456\u0434\u0442\u0440\u0438\u043c\u043a\u0430\n- **\u0417\u0440\u043e\u0437\u0443\u043c\u0456\u043b\u0430 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430** \u0437\u0430\u043b\u0435\u0436\u043d\u043e\u0441\u0442\u0435\u0439\n\n#### \u041f\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0430 \u0456\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0456\u044f\n- **\u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u0435 \u0441\u043a\u0430\u043d\u0443\u0432\u0430\u043d\u043d\u044f** \u0432\u0441\u0456\u0445 \u043f\u0430\u043a\u0435\u0442\u0456\u0432\n- **\u041f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u0430 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f** \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0456\u0432\n- **\u0413\u0430\u0440\u0430\u043d\u0442\u043e\u0432\u0430\u043d\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0456\u0441\u0442\u044c** \u0441\u0435\u0440\u0432\u0456\u0441\u0456\u0432\n\n#### \u041c\u0430\u0441\u0448\u0442\u0430\u0431\u043e\u0432\u0430\u043d\u0456\u0441\u0442\u044c\n- **\u041b\u0435\u0433\u043a\u0435 \u0434\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f** \u043d\u043e\u0432\u0438\u0445 \u0448\u0430\u0440\u0456\u0432\n- **\u041c\u043e\u0434\u0443\u043b\u044c\u043d\u0430 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430** \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0456\u0432\n- **\u0413\u043d\u0443\u0447\u043a\u0430 \u043a\u043e\u043d\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044f** \u0437\u0430\u043b\u0435\u0436\u043d\u043e\u0441\u0442\u0435\u0439\n\n### 4. \u0412\u0438\u0434\u0430\u043b\u0435\u043d\u0456 \u0444\u0430\u0439\u043b\u0438\n- \u274c `src/main/java/com/arakviel/Application.java`\n- \u274c `src/main/java/com/arakviel/presentation/config/PresentationConfig.java`\n\n### 5. \u0414\u043e\u0434\u0430\u043d\u0456 \u0444\u0430\u0439\u043b\u0438\n- \u2705 `src/main/java/com/arakviel/config/MainConfig.java`\n\n### 6. \u041e\u043d\u043e\u0432\u043b\u0435\u043d\u0456 \u0444\u0430\u0439\u043b\u0438\n- \ud83d\udd04 `src/main/java/com/arakviel/presentation/MainApplication.java`\n- \ud83d\udd04 `pom.xml` (main class \u0437\u0430\u043b\u0438\u0448\u0438\u0432\u0441\u044f \u0442\u043e\u0439 \u0441\u0430\u043c\u0438\u0439)\n\n## \ud83c\udfd7\ufe0f \u041d\u043e\u0432\u0430 \u0430\u0440\u0445\u0456\u0442\u0435\u043a\u0442\u0443\u0440\u0430\n\n```\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 MainApplication \u2502\n\u2502 (JavaFX Entry Point) \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n \u2502\n \u25bc\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 MainConfig \u2502\n\u2502 (\u0426\u0435\u043d\u0442\u0440\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430 \u043a\u043e\u043d\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044f) \u2502\n\u2502 \u2502\n\u2502 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502\n\u2502 \u2502 ComponentScan: \u2502 \u2502\n\u2502 \u2502 \u2022 com.arakviel.presentation \u2502 \u2502\n\u2502 \u2502 \u2022 com.arakviel.application \u2502 \u2502\n\u2502 \u2502 \u2022 com.arakviel.infrastructure \u2502 \u2502\n\u2502 \u2502 \u2022 com.arakviel.domain \u2502 \u2502\n\u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500