43b\u0456\u0437\u0430\u0446\u0456\u0457\n\n```java\n@Override\npublic void init() {\n // \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f Spring \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0443 \u0437 \u0443\u0441\u0456\u043c\u0430 \u0448\u0430\u0440\u0430\u043c\u0438 \u0430\u0440\u0445\u0456\u0442\u0435\u043a\u0442\u0443\u0440\u0438\n springContext = new AnnotationConfigApplicationContext(MainConfig.class);\n ServiceProvider.setApplicationContext(springContext);\n \n System.out.println(\"\u2705 Spring \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u043e \u0437 \u0443\u0441\u0456\u043c\u0430 \u0448\u0430\u0440\u0430\u043c\u0438:\");\n System.out.println(\" - Infrastructure \u0448\u0430\u0440 (\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0457, \u0431\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445)\");\n System.out.println(\" - Application \u0448\u0430\u0440 (\u0441\u0435\u0440\u0432\u0456\u0441\u0438, \u0431\u0456\u0437\u043d\u0435\u0441-\u043b\u043e\u0433\u0456\u043a\u0430)\");\n System.out.println(\" - Presentation \u0448\u0430\u0440 (JavaFX \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0440\u0438)\");\n \n // \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445\n initializeDatabase();\n}\n\n/**\n * \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0443\u0454 \u0431\u0430\u0437\u0443 \u0434\u0430\u043d\u0438\u0445 \u0437\u0430 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u043e\u044e PersistenceInitializer.\n */\nprivate void initializeDatabase() {\n try {\n System.out.println(\"\ud83d\udd27 \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445...\");\n \n PersistenceInitializer persistenceInitializer = springContext.getBean(PersistenceInitializer.class);\n persistenceInitializer.init(); // \u0412\u0438\u043a\u043e\u043d\u0443\u0454 DDL \u0442\u0430 DML \u0441\u043a\u0440\u0438\u043f\u0442\u0438\n \n System.out.println(\"\u2705 \u0411\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445 \u0443\u0441\u043f\u0456\u0448\u043d\u043e \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430!\");\n System.out.println(\" - DDL \u0441\u043a\u0440\u0438\u043f\u0442\u0438 \u0432\u0438\u043a\u043e\u043d\u0430\u043d\u043e (\u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u044c)\");\n System.out.println(\" - DML \u0441\u043a\u0440\u0438\u043f\u0442\u0438 \u0432\u0438\u043a\u043e\u043d\u0430\u043d\u043e (\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0456 \u0434\u0430\u043d\u0456)\");\n \n } catch (Exception e) {\n System.err.println(\"\u274c \u041f\u043e\u043c\u0438\u043b\u043a\u0430 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457 \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445: \" + e.getMessage());\n e.printStackTrace();\n \n // \u041c\u043e\u0436\u043d\u0430 \u0432\u0438\u0440\u0456\u0448\u0438\u0442\u0438, \u0447\u0438 \u0437\u0443\u043f\u0438\u043d\u044f\u0442\u0438 \u0434\u043e\u0434\u0430\u0442\u043e\u043a \u043f\u0440\u0438 \u043f\u043e\u043c\u0438\u043b\u0446\u0456 \u0411\u0414\n // throw new RuntimeException(\"\u041a\u0440\u0438\u0442\u0438\u0447\u043d\u0430 \u043f\u043e\u043c\u0438\u043b\u043a\u0430 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457 \u0411\u0414\", e);\n }\n}\n```\n\n## \ud83d\udd27 \u0429\u043e \u0432\u0456\u0434\u0431\u0443\u0432\u0430\u0454\u0442\u044c\u0441\u044f \u043f\u0440\u0438 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457\n\n### 1. Spring Context\n- \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0443\u0454\u0442\u044c\u0441\u044f Spring \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0437 \u0443\u0441\u0456\u043c\u0430 \u0448\u0430\u0440\u0430\u043c\u0438\n- \u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0443\u044e\u0442\u044c\u0441\u044f \u0432\u0441\u0456 bean'\u0438 \u0442\u0430 \u0437\u0430\u043b\u0435\u0436\u043d\u043e\u0441\u0442\u0456\n- \u041d\u0430\u043b\u0430\u0448\u0442\u043e\u0432\u0443\u044e\u0442\u044c\u0441\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0457 \u0442\u0430 \u0441\u0435\u0440\u0432\u0456\u0441\u0438\n\n### 2. Database Initialization\n- \u041e\u0442\u0440\u0438\u043c\u0443\u0454\u0442\u044c\u0441\u044f `PersistenceInitializer` \u0437 Spring \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0443\n- \u0412\u0438\u043a\u043b\u0438\u043a\u0430\u0454\u0442\u044c\u0441\u044f \u043c\u0435\u0442\u043e\u0434 `init()`\n- \u0412\u0438\u043a\u043e\u043d\u0443\u044e\u0442\u044c\u0441\u044f DDL \u0441\u043a\u0440\u0438\u043f\u0442\u0438 (\u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u044c)\n- \u0412\u0438\u043a\u043e\u043d\u0443\u044e\u0442\u044c\u0441\u044f DML \u0441\u043a\u0440\u0438\u043f\u0442\u0438 (\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0456 \u0434\u0430\u043d\u0456)\n\n### 3. Error Handling\n- \u041f\u0435\u0440\u0435\u0445\u043e\u043f\u043b\u044e\u044e\u0442\u044c\u0441\u044f \u043f\u043e\u043c\u0438\u043b\u043a\u0438 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457\n- \u0412\u0438\u0432\u043e\u0434\u044f\u0442\u044c\u0441\u044f \u0434\u0435\u0442\u0430\u043b\u044c\u043d\u0456 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u043f\u0440\u043e \u043f\u043e\u043c\u0438\u043b\u043a\u0438\n- \u0414\u043e\u0434\u0430\u0442\u043e\u043a \u043c\u043e\u0436\u0435 \u043f\u0440\u043e\u0434\u043e\u0432\u0436\u0438\u0442\u0438 \u0440\u043e\u0431\u043e\u0442\u0443 \u043d\u0430\u0432\u0456\u0442\u044c \u043f\u0440\u0438 \u043f\u043e\u043c\u0438\u043b\u043a\u0430\u0445 \u0411\u0414\n\n## \ud83d\udccb \u041b\u043e\u0433\u0438 \u043f\u0440\u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0443\n\n```\n\u2705 Spring \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u043e \u0437 \u0443\u0441\u0456\u043c\u0430 \u0448\u0430\u0440\u0430\u043c\u0438:\n - Infrastructure \u0448\u0430\u0440 (\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0456\u0457, \u0431\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445)\n - Application \u0448\u0430\u0440 (\u0441\u0435\u0440\u0432\u0456\u0441\u0438, \u0431\u0456\u0437\u043d\u0435\u0441-\u043b\u043e\u0433\u0456\u043a\u0430)\n - Presentation \u0448\u0430\u0440 (JavaFX \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0440\u0438)\n\ud83d\udd27 \u0406\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f \u0431\u0430\u0437\u0438 \u0434\u0430\u043d\u0438\u0445...\n\u2705 \u0411\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445 \u0443\u0441\u043f\u0456\u0448\u043d\u043e \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u043e\u0432\u0430\u043d\u0430!\n - DDL \u0441\u043a\u0440\u0438\u043f\u0442\u0438 \u0432\u0438\u043a\u043e\u043d\u0430\u043d\u043e (\u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u044c)\n - DML \u0441\u043a\u0440\u0438\u043f\u0442\u0438 \u0432\u0438\u043a\u043e\u043d\u0430\u043d\u043e (\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0456 \u0434\u0430\u043d\u0456)\n```\n\n## \ud83c\udfaf \u041f\u0435\u0440\u0435\u0432\u0430\u0433\u0438\n\n### \u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0437\u0430\u0446\u0456\u044f\n- **\u041d\u0435\u043c\u0430\u0454 \u043f\u043e\u0442\u0440\u0435\u0431\u0438** \u0432 \u0440\u0443\u0447\u043d\u043e\u043c\u0443 \u0437\u0430\u043f\u0443\u0441\u043a\u0443 \u0441\u043a\u0440\u0438\u043f\u0442\u0456\u0432 \u0411\u0414\n- **\u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u0435 \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f** \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438 \u0411\u0414 \u043f\u0440\u0438 \u043f\u0435\u0440\u0448\u043e\u043c\u0443 \u0437\u0430\u043f\u0443\u0441\u043a\u0443\n- **\u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f \u0442\u0435\u0441\u0442\u043e\u0432\u0438\u0445 \u0434\u0430\u043d\u0438\u0445** \u0434\u043b\u044f \u0440\u043e\u0437\u0440\u043e\u0431\u043a\u0438\n\n### \u041d\u0430\u0434\u0456\u0439\u043d\u0456\u0441\u0442\u044c\n- **\u041e\u0431\u0440\u043e\u0431\u043a\u0430 \u043f\u043e\u043c\u0438\u043b\u043e\u043a** \u0437 \u0434\u0435\u0442\u0430\u043b\u044c\u043d\u0438\u043c\u0438 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f\u043c\u0438\n- **\u041b\u043e\u0433\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u0440\u043e\u0446\u0435\u0441\u0443** \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457\n- **\u041c\u043e\u0436\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u043f\u0440\u043e\u0434\u043e\u0432\u0436\u0435\u043d\u043d\u044f \u0440\u043e\u0431\u043e\u0442\u0438** \u043f\u0440\u0438 \u043f\u043e\u043c\u0438\u043b\u043a\u0430\u0445\n\n### \u0417\u0440\u0443\u0447\u043d\u0456\u0441\u0442\u044c \u0440\u043e\u0437\u0440\u043e\u0431\u043a\u0438\n- **\u0413\u043e\u0442\u043e\u0432\u0430 \u0411\u0414** \u043e\u0434\u0440\u0430\u0437\u0443 \u043f\u0456\u0441\u043b\u044f \u0437\u0430\u043f\u0443\u0441\u043a\u0443\n- **\u0422\u0435\u0441\u0442\u043e\u0432\u0456 \u0434\u0430\u043d\u0456** \u0434\u043b\u044f \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u043a\u0438 \u0444\u0443\u043d\u043a\u0446\u0456\u043e\u043d\u0430\u043b\u0443\n- **\u041a\u043e\u043d\u0441\u0438\u0441\u0442\u0435\u043d\u0442\u043d\u0435 \u0441\u0435\u0440\u0435\u0434\u043e\u0432\u0438\u0449\u0435** \u0434\u043b\u044f \u0432\u0441\u0456\u0445 \u0440\u043e\u0437\u0440\u043e\u0431\u043d\u0438\u043a\u0456\u0432\n\n## \ud83d\udd04 \u041f\u043e\u0441\u043b\u0456\u0434\u043e\u0432\u043d\u0456\u0441\u0442\u044c \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457\n\n1. **JavaFX Application.init()** \u0432\u0438\u043a\u043b\u0438\u043a\u0430\u0454\u0442\u044c\u0441\u044f\n2. **Spring Context** \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0443\u0454\u0442\u044c\u0441\u044f \u0437 MainConfig\n3. **ServiceProvider** \u043d\u0430\u043b\u0430\u0448\u0442\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f\n4. **PersistenceInitializer** \u043e\u0442\u0440\u0438\u043c\u0443\u0454\u0442\u044c\u0441\u044f \u0437 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0443\n5. **Database initialization** \u0432\u0438\u043a\u043e\u043d\u0443\u0454\u0442\u044c\u0441\u044f\n6. **JavaFX Application.start()** \u0432\u0438\u043a\u043b\u0438\u043a\u0430\u0454\u0442\u044c\u0441\u044f\n7. **UI** \u0432\u0456\u0434\u043e\u0431\u0440\u0430\u0436\u0430\u0454\u0442\u044c\u0441\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0443\n\n## \u2699\ufe0f \u041d\u0430\u043b\u0430\u0448\u0442\u0443\u0432\u0430\u043d\u043d\u044f\n\n### \u0412\u0438\u043c\u043a\u043d\u0435\u043d\u043d\u044f \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u0457 \u0411\u0414\n\u042f\u043a\u0449\u043e \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u043e \u0432\u0438\u043c\u043a\u043d\u0443\u0442\u0438 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u0443 \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044e, \u043c\u043e\u0436\u043d\u0430:\n\n```java\n// \u0414\u043e\u0434\u0430\u0442\u0438 \u0443\u043c\u043e\u0432\u0443 \u0430\u0431\u043e \u043a\u043e\u043d\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u0439\u043d\u0438\u0439 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\nif (shouldInitializeDatabase()) {\n initializeDatabase();\n}\n```\n\n### \u0414\u043e\u0434\u0430\u0432\u0430\u043d\u043d\u044f \u043d\u043e\u0432\u0438\u0445 \u0441\u043a\u0440\u0438\u043f\u0442\u0456\u0432\n\u041d\u043e\u0432\u0456 DDL/DML \u0441\u043a\u0440\u0438\u043f\u0442\u0438 \u0434\u043e\u0434\u0430\u044e\u0442\u044c\u0441\u044f \u0432:\n- `src/main/resources/sql/ddl/` - \u0434\u043b\u044f \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u044c\n- `src/main/resources/sql/dml/` - \u0434\u043b\u044f \u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0438\u0445 \u0434\u0430\u043d\u0438\u0445\n\n## \ud83d\ude80 \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\n\n\u0422\u0435\u043f\u0435\u0440 \u043f\u0440\u0438 \u043a\u043e\u0436\u043d\u043e\u043c\u0443 \u0437\u0430\u043f\u0443\u0441\u043a\u0443 \u0434\u043e\u0434\u0430\u0442\u043a\u0443:\n1. \u2705 \u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e \u0456\u043d\u0456\u0446\u0456\u0430\u043b\u0456\u0437\u0443\u0454\u0442\u044c\u0441\u044f \u0431\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445\n2. \u2705 \u0421\u0442\u0432\u043e\u0440\u044e\u044e\u0442\u044c\u0441\u044f \u0432\u0441\u0456 \u043d\u0435\u043e\u0431\u0445\u0456\u0434\u043d\u0456 \u0442\u0430\u0431\u043b\u0438\u0446\u0456\n3. \u2705 \u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0443\u044e\u0442\u044c\u0441\u044f \u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0456 \u0434\u0430\u043d\u0456\n4. \u2705 \u0414\u043e\u0434\u0430\u0442\u043e\u043a \u0433\u043e\u0442\u043e\u0432\u0438\u0439 \u0434\u043e \u0440\u043e\u0431\u043e\u0442\u0438 \u0437 \u0434\u0430\u043d\u0438\u043c\u0438\n\n**\u0411\u0430\u0437\u0430 \u0434\u0430\u043d\u0438\u0445 \u0437\u0430\u0432\u0436\u0434\u0438 \u0432 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u043e\u043c\u0443 \u0441\u0442\u0430\u043d\u0456! \ud83c\udfaf**"}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер створимо короткий підсумок про додавання PersistenceInitializer:
