fo {\n -fx-spacing: 8px;\n}\n\n.card-title {\n -fx-text-fill: #2c3e50;\n -fx-font-weight: bold;\n -fx-wrap-text: true;\n}\n\n.card-author {\n -fx-text-fill: #3498db;\n -fx-font-weight: bold;\n}\n\n.card-genre {\n -fx-text-fill: #7f8c8d;\n -fx-font-style: italic;\n}\n\n.card-details {\n -fx-alignment: CENTER_LEFT;\n}\n\n.card-duration, .card-year {\n -fx-text-fill: #95a5a6;\n}\n\n.card-separator {\n -fx-text-fill: #bdc3c7;\n}\n\n.card-actions {\n -fx-background-color: #f8f9fa;\n -fx-background-radius: 0 0 12px 12px;\n}\n\n.card-action-button {\n -fx-background-color: transparent;\n -fx-text-fill: #7f8c8d;\n -fx-font-size: 16px;\n -fx-min-width: 35px;\n -fx-min-height: 35px;\n -fx-max-width: 35px;\n -fx-max-height: 35px;\n -fx-background-radius: 18px;\n -fx-cursor: hand;\n}\n\n.card-action-button:hover {\n -fx-background-color: #ecf0f1;\n -fx-text-fill: #2c3e50;\n -fx-scale-x: 1.1;\n -fx-scale-y: 1.1;\n}\n\n/* \u0410\u043d\u0456\u043c\u0430\u0446\u0456\u0457 */\n.menu-button, .primary-button, .secondary-button {\n -fx-transition: all 0.2s ease;\n}\n\n.stat-card, .audiobook-card {\n -fx-transition: all 0.3s ease;\n}\n\n.play-button, .card-action-button {\n -fx-transition: all 0.2s ease;\n}", "old_str_start_line_number_1": 174, "old_str_end_line_number_1": 180}","mcp_server_name":"","mcp_tool_name":""}},{"id":0,"type":0,"content":"Тепер додамо CSS стилі для карток аудіокниг:
