 40	 /**
 41	 * Створює новий жанр.
 42	 *
 43	 * @param genre жанр для створення
 44	 * @return створений жанр
 45	 * @throws DatabaseAccessException якщо виникає помилка при роботі з базою даних
 46	 * @throws ValidationException якщо порушено бізнес-правила (наприклад, дублювання жанру)
 47	 */
 48	 @Override
 49	 public Genre create(Genre genre) {
 50	 validateGenre(genre);
 51	 if (genre.getId() == null) {
 52	 genre.setId(UUID.randomUUID());
 53	 }
 54	
 55	 // Перевірка на дублювання жанру
 56	 if (genreRepository.existsByName(genre.getName())) {
 57	 new ValidationHelper()
 58	 .addError("name", "жанр з такою назвою вже існує")
 59	 .throwIfHasErrors();
 60	 }
 61	
 62	 persistenceContext.registerNew(genre);
 63	 persistenceContext.commit();
 64	 return genre;
 65	 }
