 25	
 26	 @Override
 27	 public boolean equals(Object o) {
 28	 if (this == o) return true;
 29	 if (o == null || getClass() != o.getClass()) return false;
 30	 User user = (User) o;
 31	 return Objects.equals(id, user.id);
 32	 }
 33	
 34	 @Override
 35	 public int hashCode() {
 36	 return Objects.hash(id);
 37	 }
 38	
 39	 @Override
 40	 public int compareTo(User other) {
 41	 // Compare by username
 42	 return this.username.compareToIgnoreCase(other.username);
 43	 }
