 49	 /**
 50	 * Створює нового користувача та, за потреби, завантажує аватар.
 51	 */
 52	 @Override
 53	 public User create(User user, InputStream avatar, String avatarName) {
 54	 validateUser(user);
 55	 if (user.getId() == null) {
 56	 user.setId(UUID.randomUUID());
 57	 }
 58	
 59	 // Перевірка на дублювання username та email
 60	 ValidationHelper duplicateValidator = new ValidationHelper();
 61	 if (existsByUsername(user.getUsername())) {
 62	 duplicateValidator.addError("username", "користувач з таким ім'ям уже існує");
 63	 }
 64	 if (existsByEmail(user.getEmail())) {
 65	 duplicateValidator.addError("email", "користувач з таким email уже існує");
 66	 }
 67	 duplicateValidator.throwIfHasErrors();
 68	
 69	 // Хешування пароля
 70	 user.setPasswordHash(hashPassword(user.getPasswordHash()));
 71	
 72	 // Обробка завантаження аватара
 73	 if (avatar != null && avatarName != null) {
 74	 Path avatarPath = fileStorageService.save(avatar, avatarName, user.getId());
 75	 user.setAvatarPath(avatarPath.toString());
 76	 }
 77	
 78	 persistenceContext.registerNew(user);
 79	 persistenceContext.commit();
 80	 return user;
 81	 }
 82	
 83	 /**
 84	 * Оновлює існуючого користувача та, за потреби, оновлює аватар.
 85	 */
 86	 @Override
 87	 public User update(UUID id, User user, InputStream avatar, String avatarName) {
 88	 validateUser(user);
 89	 user.setId(id);
 90	
 91	 // Перевірка існування користувача
 92	 Optional<User> existingUserOpt = userRepository.findById(id);
 93	 ValidationHelper updateValidator = new ValidationHelper();
 94	
 95	 if (!existingUserOpt.isPresent()) {
 96	 updateValidator.addError("id", "користувач з таким ідентифікатором не існує");
 97	 updateValidator.throwIfHasErrors();
 98	 }
 99	
 100	 User existingUser = existingUserOpt.get();
 101	
 102	 // Перевірка на дублювання username (якщо змінюється)
 103	 if (!existingUser.getUsername().equals(user.getUsername()) && existsByUsername(user.getUsername())) {
 104	 updateValidator.addError("username", "користувач з таким ім'ям уже існує");
 105	 }
 106	
 107	 // Перевірка на дублювання email (якщо змінюється)
 108	 if (!existingUser.getEmail().equals(user.getEmail()) && existsByEmail(user.getEmail())) {
 109	 updateValidator.addError("email", "користувач з таким email уже існує");
 110	 }
 111	
 112	 updateValidator.throwIfHasErrors();
 113	
 114	 // Хешування пароля, якщо він змінився
 115	 if (!user.getPasswordHash().equals(existingUser.getPasswordHash())) {
 116	 user.setPasswordHash(hashPassword(user.getPasswordHash()));
 117	 }
 118	
 119	 // Обробка існуючого аватара
 120	 if (existingUser.getAvatarPath() != null && avatar != null && avatarName != null) {
 121	 String fileName = Path.of(existingUser.getAvatarPath()).getFileName().toString();
 122	 fileStorageService.delete(fileName, id);
 123	 }
 124	
 125	 // Обробка нового аватара
 126	 if (avatar != null && avatarName != null) {
 127	 Path avatarPath = fileStorageService.save(avatar, avatarName, id);
 128	 user.setAvatarPath(avatarPath.toString());
 129	 } else if (existingUser.getAvatarPath() != null) {
 130	 user.setAvatarPath(existingUser.getAvatarPath());
 131	 }
 132	
 133	 persistenceContext.registerUpdated(id, user);
 134	 persistenceContext.commit();
 135	 return user;
 136	 }
