 140	 */
 141	 @Override
 142	 public void delete(UUID id) {
 143	 Optional<User> userOpt = userRepository.findById(id);
 144	 if (userOpt.isPresent()) {
 145	 User user = userOpt.get();
 146	
 147	 // Видалення аватара
 148	 if (user.getAvatarPath() != null) {
 149	 String fileName = Path.of(user.getAvatarPath()).getFileName().toString();
 150	 fileStorageService.delete(fileName, id);
 151	 }
 152	
 153	 persistenceContext.registerDeleted(user);
 154	 persistenceContext.commit();
 155	 }
 156	 }
