 244	 if (!user.getPasswordHash().equals(hashedOldPassword)) {
 245	 new ValidationHelper()
 246	 .addError("oldPassword", "неправильний старий пароль")
 247	 .throwIfHasErrors();
 248	 }
 249	
 250	 user.setPasswordHash(hashPassword(newPassword));
 251	 persistenceContext.registerUpdated(userId, user);
 252	 persistenceContext.commit();
 253	 }
 254	
 255	 @Override
 256	 public Optional<User> authenticate(String username, String password) {
 257	 new ValidationHelper()
 258	 .notEmpty("username", username)
 259	 .notEmpty("password", password)
 260	 .throwIfHasErrors();
 261	
 262	 List<User> users = findByUsername(username);
 263	 if (users.isEmpty()) {
 264	 return Optional.empty();
 265	 }
 266	
 267	 User user = users.get(0);
 268	 String hashedPassword = hashPassword(password);
 269	 
 270	 if (user.getPasswordHash().equals(hashedPassword)) {
 271	 return Optional.of(user);
 272	 }
 273	 
 274	 return Optional.empty();
 275	 }
 276	
 277	 /**
 278	 * Валідує дані користувача з використанням нового підходу.
 279	 */
 280	 private void validateUser(User user) {
 281	 ValidationHelper validator = new ValidationHelper()
 282	 .notNull("user", user);
 283	
 284	 if (user != null) {
 285	 validator
 286	 .notEmpty("username", user.getUsername())
 287	 .validUsername("username", user.getUsername())
 288	 .notEmpty("passwordHash", user.getPasswordHash())
 289	 .notEmpty("email", user.getEmail())
 290	 .validEmail("email", user.getEmail());
 291	 }
 292	
 293	 validator.throwIfHasErrors();
 294	 }
 295	
 296	 /**
 297	 * Валідує параметри пагінації з використанням нового підходу.
 298	 */
 299	 private void validatePagination(int offset, int limit) {
 300	 new ValidationHelper()
 301	 .nonNegative("offset", offset)
 302	 .positive("limit", limit)
 303	 .throwIfHasErrors();
 304	 }
 305	
 306	 /**
 307	 * Хешує пароль за допомогою SHA-256.
 308	 */
 309	 String hashPassword(String password) {
 310	 try {
 311	 MessageDigest digest = MessageDigest.getInstance("SHA-256");
 312	 byte[] hash = digest.digest(password.getBytes());
 313	 StringBuilder hexString = new StringBuilder();
 314	 for (byte b : hash) {
 315	 String hex = Integer.toHexString(0xff & b);
 316	 if (hex.length() == 1) {
 317	 hexString.append('0');
 318	 }
 319	 hexString.append(hex);
 320	 }
 321	 return hexString.toString();
 322	 } catch (NoSuchAlgorithmException e) {
 323	 throw new RuntimeException("Помилка хешування пароля", e);
 324	 }
 325	 }
 326	}
