 56	 user.setId(UUID.randomUUID());
 57	 }
 58	
 59	 // Перевірка на дублювання username та email
 60	 ValidationHelper duplicateValidator = new ValidationHelper();
 61	 if (existsByUsername(user.getUsername())) {
 62	 duplicateValidator.addError("username", "користувач з таким ім'ям уже існує");
 63	 }
 64	 if (existsByEmail(user.getEmail())) {
 65	 duplicateValidator.addError("email", "користувач з таким email уже існує");
 66	 }
