 99	 private static final String DEFAULT_URL = "jdbc:h2:~/audiobooks;MODE=PostgreSQL";
 100	 private static final String DEFAULT_USER = "sa";
 101	 private static final String DEFAULT_PASSWORD = "";
 102	 private static final int DEFAULT_MAX_CONNECTIONS = 5;
 103	 private static final boolean DEFAULT_AUTO_COMMIT = true;
 104	
 105	 private final String url;
 106	 private final String user;
 107	 private final String password;
 108	 private final int maxConnections;
 109	 private final boolean autoCommit;
 110	
 111	 private PoolConfig(Builder builder) {
 112	 this.url = builder.url;
 113	 this.user = builder.user;
 114	 this.password = builder.password;
 115	 this.maxConnections = builder.maxConnections;
 116	 this.autoCommit = builder.autoCommit;
 117	 }
 118	
 119	 public static PoolConfig fromProperties(Properties properties) {
 120	 return new Builder()
 121	 .withUrl(properties.getProperty("db.url", DEFAULT_URL))
 122	 .withUser(properties.getProperty("db.username", DEFAULT_USER))
 123	 .withPassword(properties.getProperty("db.password", DEFAULT_PASSWORD))
 124	 .withMaxConnections(Integer.parseInt(properties.getProperty("db.pool.size", String.valueOf(DEFAULT_MAX_CONNECTIONS))))
 125	 .withAutoCommit(Boolean.parseBoolean(properties.getProperty("db.auto.commit", String.valueOf(DEFAULT_AUTO_COMMIT))))
 126	 .build();
 127	 }
